window.PACK={"book":{"id":"diwan-zaydun","title":"ديوان ابن زيدون","type":"diwan","author":"ابن زيدون (ت ٤٦٣هـ)","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"andalusi","packVersion":"822c0e63e8af"},"items":[{"id":"diwan-zaydun:1","bookId":"diwan-zaydun","type":"poem","seq":1,"chapter":"البحر: بسيط تام","title":"أضحى التنائي بديلا من تدانينا ،","page":"","text":"أضحى التنائي بديلا من تدانينا ، … وناب عن طيب لقيانا تجافينا\nألا وقد حان صبح البين ، صبحنا … حين ، فقام بنا للحين ناعينا\nمن مبلغ الملبسينا ، بانتزاحهم ، … حزنا ، مع الدهر لا يبلى ويبلينا\nغيظ العدا من تساقينا الهوى فدعوا … بأن نغص ، فقال الدهر آمينا\nفانحل ما كان معقودا بأنفسنا ؛ … وانبت ما كان موصولا بأيدينا\nوقد نكون ، وما يخشى تفرقنا ، … فاليوم نحن ، وما يرجى تلاقينا\nيا ليت شعري ، ولم نعتب أعاديكم ، … هل نال حظا من العتبى أعادينا\nلم نعتقد بعدكم إلا الوفاء لكم … رأيا ، ولم نتقلد غيره دينا\nما حقنا أن تقروا عين ذي حسد … بنا ، ولا أن تسروا كاشحا فينا\nكنا نرى اليأس تسلينا عوارضه ، … وقد يئسنا فما لليأس يغرينا\nبنتم وبنا ، فما ابتلت جوانحنا … شوقا إليكم ، ولا جفت مآقينا\nنكاد ، حين تناجيكم ضمائرنا ، … يقضي علينا الأسى لولا تأسينا\nحالت لفقدكم أيامنا ، فغدت … سودا ، وكانت بكم بيضا ليالينا\nإذ جانب العيش طلق من تألفنا ؛ … ومربع اللهو صاف من تصافينا\nوإذ هصرنا فنون الوصل دانية … قطافها ، فجنينا منه ما شينا\nليسق عهدكم عهد السرور فما … كنتم لأرواحن ا إلا رياحين ا\nلا تحسبوا نأيكم عنا يغيرنا ؛ … أن طالما غير النأي المحبينا !\nوالله ما طلبت أهواؤنا بدلا … منكم ، ولا انصرفت عنكم أمانينا\nيا ساري البرق غاد القصر واسق به … من كان صرف الهوى والود يسقينا\nواسأل هنالك : هل عنى تذكرنا … إلفا ، تذكره أمسى يعنينا ؟\nويا نسيم الصبا بلغ تحيتنا … من لو على البعد حيا كان يحيينا\nفهل أرى الدهر يقضينا مساعفة … منه ، وإن لم يكن غبا تقاضينا\nربيب ملك ، كأن الله أنشأه … مسكا ، وقدر إنشاء الورى طينا\nأو صاغه ورقا محضا ، وتوجه … من ناصع التبر إبداعا وتحسينا\nإذا تأود آدته ، رفاهية ، … توم العقود ، وأدمته البرى لينا\nكانت له الشمس ظئرا في أكلته ، … بل ما تجلى لها إلا أحايينا\nكأنما أثبتت ، في صحن وجنته ، … زهر الكواكب تعويذا وتزيينا\nما ضر أن لم نكن أكفاءه شرفا ، … وفي المودة كاف من تكافينا ؟\nيا روضة طالما أجنت لواحظنا … وردا ، جلاه الصبا غضا ، ونسرينا\nويا حياة تملينا ، بزهرتها ، … منى ضروبا ، ولذات أفانينا\nويا نعيما خطرنا ، من غضارته ، … في وشي نعمى ، سحبنا ذيله حينا\nلسنا نسميك إجلالا وتكرمة ؛ … وقدرك المعتلي عن ذاك يغنينا\nإذا انفردت وما شوركت في صفة ، … فحسبنا الوصف إيضاحا وتبيينا\nيا جنة الخلد أبدننا ، بسدرتها … والكوثر العذب ، زقوما وغسلينا\nكأننا لم نبت ، والوصل ثالثنا ، … والسعد قد غض من أجفان واشينا\nإن كان قد عز في الدنيا اللقاء بكم … في موقف الحشر نلقاكم وتلقونا\nسران في خاطر الظلماء يكتمنا ، … حتى يكاد لسان الصبح يفشينا\nلا غرو في أن ذكرنا الحزن حين نهت … عنه النهى ، وتركنا الصبر ناسينا\nإنا قرأنا الأسى ، يوم النوى ، سورا … مكتوبة ، وأخذنا الصبر تلقينا\nأما هواك ، فلم نعدل بمنهله … شربا وإن كان يروينا فيظمينا\nلم نجف أفق جمال أنت كوكبه … سالين عنه ، ولم نهجره قالينا\nولا اختيارا تجنبناه عن كثب ، … لكن عدتنا ، على كره ، عوادينا\nنأسى عليك إذا حثت ، مشعشعة ، … فينا الشمول ، وغنانا مغنينا\nلا أكؤس الراح تبدي من شمائلنا … سيما ارتياح ، ولا الأوتار تلهينا\nدومي على العهد ، ما دمنا ، محافظة ، … فالحر من دان إنصافا كما دينا\nفما استعضنا خليلا منك يحبسنا … ولا استفدنا حبيبا عنك يثنينا\nولو صبا نحونا ، من علو مطلعه ، … بدر الدجى لم يكن حاشاك يصبينا\nأبكي وفاء ، وإن لم تبذلي صلة ، … فالطيف يقنعنا ، والذكر يكفينا\nوفي الجواب متاع ، إن شفعت به … بيض الأيادي ، التي ما زلت تولينا\nك منا سلام الله ما بقيت … صبابة بك نخفيها ، فتخفينا"},{"id":"diwan-zaydun:2","bookId":"diwan-zaydun","type":"poem","seq":2,"chapter":"البحر: مجتث","title":"بالله خذ من حياتي","page":"","text":"بالله خذ من حياتي … يوما وصلني ساعه\nكيما أنال بقرض … ما لم أنل بشفاعه"},{"id":"diwan-zaydun:3","bookId":"diwan-zaydun","type":"poem","seq":3,"chapter":"البحر: وافر تام","title":"علام صرمت حبلك من وصول ؛","page":"","text":"علام صرمت حبلك من وصول ؛ … فديتك ، واعتززت على ذليل ؟\nوفيم أنفت من تعليل صب ، … صحيح الود ، ذي جسم عليل ؟\nفهلا عدتني ، إذ لم تعود … بشخصك ، بالكتاب أو الرسول ؟\nلقد أعيا تلونك احتيالي ، … وهل يعني احتيال في ملول ؟"},{"id":"diwan-zaydun:4","bookId":"diwan-zaydun","type":"poem","seq":4,"chapter":"البحر: مجزوء الرمل","title":"وضح الحق المبين ؛","page":"","text":"وضح الحق المبين ؛ … ونفى الشك اليقين\nورأى الأعداء ما غر … تهم منه الظنون\nأملوا ما ليس يمنى ؛ … ورجوا ما لا يكون\nوتمنوءا أن يخون ال … عهد مولى لا يخون\nفإذا الغيب سليم ، … وإذا الود مصون !\nقل لمن دان بهجري ، … وهواه لي دين\nيا جوادا بي ! إني … بك ، والله ، ضنين\nأرخص الحب فؤادي … لك ، والعلق ثمين\nيا هلالا ! تترا … ءاه نفوس ، لا عيون\nعجبا للقلب يقسو … منك ، والقد يلين\nما الذي ضرك لو س … ر بمرآك الحزين\nوتلطفت لصب ، … حينه فيك يحين\nفوجوه اللفظ شتى ، … والمعاذير فنون"},{"id":"diwan-zaydun:5","bookId":"diwan-zaydun","type":"poem","seq":5,"chapter":"البحر: مجزوء الخفيف","title":"يا غزالا ! أصارني","page":"","text":"يا غزالا ! أصارني … موثقا ، في يد المحن\nإنني ، مذ هجرتني ، … لم أذق لذة الوسن\nليت حظي إشارة … منك ، أو لحظة عنن\nشافعي ، يا معذبي ، … في الهوى ، وجهك الحسن\nكنت خلوا من الهوى ؛ … فأنا اليوم مرتهن\nكان سري مكتما ؛ … وهو الآن قد علن\nليس لي عنك مذهب ؛ … فكما شئت لي فكن"},{"id":"diwan-zaydun:6","bookId":"diwan-zaydun","type":"poem","seq":6,"chapter":"البحر: طويل","title":"خليلي ، لا فطر يسر ولا أضحى ،","page":"","text":"خليلي ، لا فطر يسر ولا أضحى ، … فما حال من أمسى مشوقا كما أضحى ؟\nلئن شاقني شرق العقاب فلم أزل … أخص بمحوض الهوى ذلك السفحا\nوما انفك جوفي الرصافة مشعري … دواعي ذكرى تعقب الأسف البرحا\nويهتاج قصر الفارسي صبابة ، … لقلبي ، لا تألوا زناد الأسى قدحا\nوليس ذميما عهد مجلس ناصح ، … فأقبل في فرط الولوع به نصحا\nكأني لم أشهد لدى عين شهدة … نزال عتاب كان آخره الفتحا\nوقائع جانيها التجني ، فإن مشى … سفير خضوع بيننا أكد الصلحا\nوأيام وصل بالعقيق اقتضيته ، … فإلا يكن ميعاده العيد فالفصحا\nوآصال لهو في مسناة مالك ، … معاطاة ندمان إذا شئت أو سبحا\nلدى راكد يصبيك ، من صفحاته ، … قوارير خضر خلتها مردت صرحا\nمعاهد لذات ، وأوطان صبوة ، … أجلت المعلى في الأماني بها قدحا\nألا هل إلى الزهراء أوبة نازح … تقضى تنائيها مدامعه نزحا\nمقاصير ملك أشرقت جنباتها ، … فخلنا العشاء الجون أثناء صبحا\nيمثل قرطيها لي الوهم جهرة ، … فقبتها فالكوكب الرحب فالسطحا\nمحل ارتياح يذكر الخلد طيبه … إذا عز أن يصدى الفتى فيه أو يضحى\nهناك الجمام الزرق تندي حفافها … ظلال عهدت الدهر فيها فتى سمحا\nتعوضت ، من شدو القيان خلالها ، … صدى فلوات قد أطار الكرى ضبحا\nومن حملي الكأس المفدى مديرها … تقحم أهوال حملت لها الرمحا\nأجل ! إن ليلي ، فوق شاطئ نيطة ، … لأقصر من ليلي بآنة فالبطحا"},{"id":"diwan-zaydun:7","bookId":"diwan-zaydun","type":"poem","seq":7,"chapter":"البحر: سريع","title":"ما ضر لو أنك لي راحم ؛","page":"","text":"ما ضر لو أنك لي راحم ؛ … وعلتي أنت بها عالم\nيهنيك ، يا سؤلي ويا بغيتي ، … أنك مما أشتكي سالم\nتضحك في الحب ، وأبكي أنا ، … ألله ، فيما بيننا ، حاكم\nأقول لما طار عني الكرى … قول معنى ، قلبه هائم :\nيا نائما أيقظني حبه ، … هب لي رقادا أيها النائم !"},{"id":"diwan-zaydun:8","bookId":"diwan-zaydun","type":"poem","seq":8,"chapter":"البحر: وافر تام","title":"أحين علمت حظك من ودادي ؛","page":"","text":"أحين علمت حظك من ودادي ؛ … ولم تجهل محلك من فؤادي\nوقادني الهوى ، فانقدت طوعا ، … وما مكنت غيرك من قيادي\nرضيت لي السقام لباس جسم ، … كحلت الطرف منه بالسهاد\nأجل عينيك في أسطار كتبي ، … تجد دمعي مزاجا للمداد\nفديتك ! إنني قد ذاب قلبي … من الشكوى إلى قلب جماد"},{"id":"diwan-zaydun:9","bookId":"diwan-zaydun","type":"poem","seq":9,"chapter":"البحر: بسيط تام","title":"يا مخجل الغصن الفينان إن خطرا ؛","page":"","text":"يا مخجل الغصن الفينان إن خطرا ؛ … وفاضح الرشإ الوسنان إن نظرا\nيفديك مي محب ، شأنه عجب ، … ما جئت بالذنب إلا جاء معتذرا\nلم ينجني منك ما استشعرت من حذر ؛ … هيهات كيد الهوى يستهلك الحذرا\nما كان حبك إلا فتنة قدرت ؛ … هل يستطيع الفتى أن يدفع القدرا ؟"},{"id":"diwan-zaydun:10","bookId":"diwan-zaydun","type":"poem","seq":10,"chapter":"البحر: وافر تام","title":"أيوحشني الزمان ، وأنت أنسي ،","page":"","text":"أيوحشني الزمان ، وأنت أنسي ، … ويظلم لي النهار وأنت شمسي ؟\nوأغرس في محبتك الأماني ، … فأجني الموت من ثمرات غرسي\nلقد جازيت غدرا عن وفائي ؛ … وبعت مودتي ، ظلما ، ببخس\nولو أن الزمان أطاع حكمي … فديتك ، من مكارهه ، بنفسي"},{"id":"diwan-zaydun:11","bookId":"diwan-zaydun","type":"poem","seq":11,"chapter":"البحر: بسيط تام","title":"هل راكب ، ذاهب عنهم ، يحييني ،","page":"","text":"هل راكب ، ذاهب عنهم ، يحييني ، … إذ لا كتاب يوافيني ، فيحييني ؟\nقد مت ، إلا ذماء في يمسكه … أن الفؤاد ، بلقياهم ، يرجيني\nما سرح الدمع من عيني ، وأطلقه ، … إلا اعتياد أسى ، في القلب ، مسجون\nصبرا ! لعل الذي بالبعد أمرضني ، … بالقرب يوما يداويني ، فيشفيني !\nكيف اصطباري وفي كانون فارقني … قلبي ، وها نحن في أعقاب تشرين ؟\nشخص ، يذكرني ، فاه وغرته ، … شمس النهار ، وأنفاس الرياحين\nلئن عطشت إلى ذاك الرضاب لكم … قد بات منه يسقيني ، فيرويني !\nوإن أفاض دموعي نوح باكية ، … فكم أراه يغنيني ، فيشجيني !\nوإن بعدت ، وأضنتني الهموم ، لقد … عهدته ، وهو يدنيني ، فيسليني\nأو حل عقد عزائي نأيه ، فلكم … حللت ، عن خصره ، عقد الثمانين\nيا حسن إشراق ساعات الدنو بدت … كواكبا في ليالي بعده الجون\nوالله ما فارقوني باختيارهم ؛ … وإنما الدهر ، بالمكروه ، يرميني\nوما تبدلت حبا غير حبهم ، … إذا تبدلت دين الكفر من ديني\nأفدي الحبيب الذي لو كان مقتدرا … لكان بالنفس والأهلين ، يفديني\nيا رب قرب ، على خير ، تلاقينا ، … بالطالع السعد والطير الميامين"},{"id":"diwan-zaydun:12","bookId":"diwan-zaydun","type":"poem","seq":12,"chapter":"البحر: بسيط تام","title":"كما تشاء ، فقل لي ، لست منتقلا ،","page":"","text":"كما تشاء ، فقل لي ، لست منتقلا ، … لا تخش مني نسيانا ، ولا بدلا\nوكيف ينساك من لم يدر بعدك ما … طعم الحياة ، ولا بالبعد عنك سلا ؟\nأتلفتني كلفا ، أبليتني أسفا ، … قطعتني شغفا ، أورثتني عللا\nإن كنت خنت وأضمرت السلو ، فلا … بلغت يا أملي ، من قربك ، الأملا\nوالله ! لا علقت نفسي بغيركم ؛ … ولا اتخذت سواكم منكم بدلا"},{"id":"diwan-zaydun:13","bookId":"diwan-zaydun","type":"poem","seq":13,"chapter":"البحر: طويل","title":"ورامشة يشفي العليل نسيمها ،","page":"","text":"ورامشة يشفي العليل نسيمها ، … مضمخة الأنفاس ، طيبة النشر\nأشار بها نحوي بنان منعم ، … لأغيد مكحول المدامع بالسحر\nسرت نضرة ، من عهدها ، في غصونها ، … وعلت بمسك ، من شمائله الزهر\nإذا هو أهدى الياسمين بكفه ، … أخذت النجوم الزهر من راحة البدر\nله خلق عذب وخلق محسن ، … وظرف كعرف الطيب أو نشوة الخمر\nيعلل نفسي من حديث تلذه ، … كمثل المنى والوصل في عقب الهجر"},{"id":"diwan-zaydun:14","bookId":"diwan-zaydun","type":"poem","seq":14,"chapter":"البحر: متقارب تام","title":"لئن قصر اليأس منك الأمل ؛","page":"","text":"لئن قصر اليأس منك الأمل ؛ … وحال تجنيك دون الحيل\nوناجاك ، بالإفك ، في الحسود ، … فأعطيته ، جهرة ، ما سأل\nوراقك سحر العدا المفترى ؛ … وغرك زورهم المفتعل\nوأقبلتهم في وجه القبول ؛ … وقابلهم بشرك المقتبل\nفإن ذمام الهوى ، لم أزل … أبقيه ، حفظا ، كما لم أزل\nفديتك ، إن تعجلي بالجفا ؛ … فقد يهب الريث بعض العجل\nعلام أطبتك دواعي القلى ؟ … وفيم ثنتك نواهي العذل ؟\nألم ألزم الصبر كيما أخف ؟ … ألم أكثر الهجر كي لا أمل ؟\nألم أرض منك بغير الرضى ؛ … وأبدي السرور بما لم أنل ؟\nألم أغتفر موبقات الذنوب ، … عمدا أتيت بها زلل ؟\nوما ساء ظني في أن يسيء ، … بي الفعل ، حسنك ، حتى فعل\nعلى حين أصبحت حسب الضمير … ولم تبغ منك الأماني بدل\nوصانك ، مني ، وفي أبي … لعلق العلاقة أن يبتذل\nسعيت لتكدير عهد صفا ، … وحاولت نقص وداد كمل\nفما عوفيت مقتي من أذى ؛ … ولا أعفيت ثقتي من خجل\nومهما هززت إليك العتاب ، … ظاهرت بين ضروب العلل\nكأنك ناظرت أهل الكلام ، … وأوتيت فهما بعلم الجدل\nولو شئت راجعت حر الفعال ، … وعدت لتلك السجايا الأول\nفلم يك حظي منك الأخس ؛ … ولا عد سهمي فيك الأقل\nعليك السلام ، سلام الوداع ، … وداع هوى مات قبل الأجل\nوما باختيار تسليت عنك ، … ولكنني : مكره لا بطل\nولم يدر قلبي كيف النزوع ، … إلى أن رأى سيرة ، فامتثل\nوليت الذي قاد ، عفوا إليك ، … أبي الهوى في عنان الغزل\nيحيل عذوبة ذاك اللمى ؛ … ويشفي من السقم تلك المقل"},{"id":"diwan-zaydun:15","bookId":"diwan-zaydun","type":"poem","seq":15,"chapter":"البحر: بسيط تام","title":"يا ظبية لطفت مني منازلها ،","page":"","text":"يا ظبية لطفت مني منازلها ، … فالقلب منهن ، والأحداق والكبد\nحبي لك ، الناس طرا يشهدون به ؛ … وأنت شاهدة إن يثنهم حسد\nلم يعزب الوصل فيما بيننا أبدا ، … لو كنت واجدة مثل الذي أجد"},{"id":"diwan-zaydun:16","bookId":"diwan-zaydun","type":"poem","seq":16,"chapter":"البحر: طويل","title":"لعمري ، لئن قلت إليك رسائلي ،","page":"","text":"لعمري ، لئن قلت إليك رسائلي ، … لأنت الذي نفسي عليه تذوب\nفلا تحسبوا أني تبدلت غيركم ، … ولا أن قلبي ، من هواك ، يتوب"},{"id":"diwan-zaydun:17","bookId":"diwan-zaydun","type":"poem","seq":17,"chapter":"البحر: طويل","title":"ألا ليت شعري هل أصادف خلوة","page":"","text":"ألا ليت شعري هل أصادف خلوة … لديك ، فأشكو بعض ما أنا واجد ؟\nرعى الله يوما فيه أشكو صبابتي ، … وأجفان عيني ، بالدموع ، شواهد"},{"id":"diwan-zaydun:18","bookId":"diwan-zaydun","type":"poem","seq":18,"chapter":"البحر: بسيط تام","title":"إني ذكرتك ، بالزهراء ، مشتاقا ،","page":"","text":"إني ذكرتك ، بالزهراء ، مشتاقا ، … والأفق طلق ومرأى الأرض قد راقا\nوللنسيم اعتلال ، في أصائله ، … كأننه رق لي ، فاعتل إشفاقا\nوالروض ، عن مائه الفضي ، مبتسم ، … كما شققت ، عن اللبات ، أطواقا\nيوم ، كأيام لذات لنا انصرمت ، … بتنا لها ، حين نام الدهر ، سراقا\nنلهو بما يستميل العين من زهر … جال الندى فيه ، حتى مال أعناقا\nكأن أعينه ، إذ عاينت أرقى ، … بكت لما بي ، فجال الدمع رقراقا\nورد تألق ، في ضاحي منابته ، … فازداد منه الضحى ، في العين ، إشراقا\nسرى ينافحه نيلوفر عبق ، … وسنان نبه منه الصبح أحداقا\nكل يهيج لنا ذكرى تشوقنا … إليك ، لم يعد عنها الصدر أن ضاقا\nلا سكن الله قلبا عق ذكركم … فلم يطر ، بجناح الشوق ، خفاقا\nلو شاء حملي نسيم الصبح حين سرى … وافاكم بفتى أضناه ما لاقى\nلو كان وفى المنى ، في جمعنا بكم ، … لكان من أكرم الأيام أخلاقا\nيا علقي الأخطر ، الأسنى ، الحبيب إلى … نفسي ، إذا ما اقتنى الأحباب أعلاقا\nكان التجاري بمحض الود ، مذ زمن ، … ميدان أنس ، جرينا فيه أطلاقا\nفالآن ، أحمد ما كنا لعهدكم ، … سلوتم ، وبقينا نحن عشاقا !"},{"id":"diwan-zaydun:19","bookId":"diwan-zaydun","type":"poem","seq":19,"chapter":"البحر: بسيط تام","title":"يا نازحا ، وضمير القلب مثواه ،","page":"","text":"يا نازحا ، وضمير القلب مثواه ، … أنستك دنياك عبدا ، أنت مولاه\nألهتك عنه فكاهات ، تلذ بها ، … فليس يجري ، ببال منك ، ذكراه\nعل الليالي تبقيني إلى أمل … الدهر يعلم والأيام معناه"},{"id":"diwan-zaydun:20","bookId":"diwan-zaydun","type":"poem","seq":20,"chapter":"البحر: وافر تام","title":"إليك ، من الأنام ، غدا ارتياحي ،","page":"","text":"إليك ، من الأنام ، غدا ارتياحي ، … وأنت ، على الزمان ، مدى اقتراحي\nوما اعترضت هموم النفس إلا ، … ومن ذكراك ، ريحاني وراحي\nفديتك ، إن صبري عنك صبري ، … لدى عطشي ، على الماء القراح\nولي أمل ، لو الواشون كفوا ، … لأطلع غرسه ثمر النجاح\nوأعجب كيف يغلبني عدو ، … رضاك عليه من أمضى سلاح !\nولما أن جلتك لي ، اختلاسا ، … أكف الدهر للحين المتاح\nرأيت الشمس تطلع من نقاب ، … وغصن البان يرفل في وشاح\nفلو أستطيع طرت إليك شوقا ، … وكيف يطير مقصوص الجناح ؟\nعلى حالي وصال واجتناب ؛ … وفي يومي دنو وانتزاح\nوحسبي أن تطالعك الأماني … بأفقك ، في مساء أو صباح\nفؤادي ، من أسى بك ، غير خال ، … وقلبي ، عن هوى لك ، غير صاح\nوأن تهدي السلام إلي غبا ، … ولو في بعض أنفاس الرياح"},{"id":"diwan-zaydun:21","bookId":"diwan-zaydun","type":"poem","seq":21,"chapter":"البحر: مجتث","title":"متى أبثك ما بي ،","page":"","text":"متى أبثك ما بي ، … يا راحتي وعذابي ؟\nمتى ينوب لساني ، … في شرحه ، عن كتابي ؟\nالله يعلم أني … أصبحت فيك لما بي\nفلا يطيب طعامي ؛ … ولا يسوغ شرابي\nيا فتنة المتقري ، … وحجة المتصابي\nالشمس أنت ، توارت ، … عن ناظري ، بالحجاب\nما البدر ، شف سناه … على رقيق السحاب ،\nإلا كوجهك ، لما … أضاء تحت النقاب"},{"id":"diwan-zaydun:22","bookId":"diwan-zaydun","type":"poem","seq":22,"chapter":"البحر: مجزوء الكامل","title":"كم ذا أريد ولا أراد ؟","page":"","text":"كم ذا أريد ولا أراد ؟ … يا سوء ما لقي الفؤاد\nأصفي الودادي مدللا ، … لم يصف لي منه الوداد\nيقضي علي دلاله ، … في كل حين ، أو يكاد\nكيف السلو عن الذي … مثواه من قلبي السواد ؟\nملك القلوب بحسنه ، … فلها ، إذا أمر ، انقياد\nيا هاجري كم أستفيد … الصبر عنك ، فلا أفاد\nألا رثيت لمن يبيت ، … وحشو مقلته السهاد ؟\nإن أجن ذنبا في الهوى ، … خطأ ، فقد يكبو الجواد\nكان الرضى ، وأعيذه … أن يعقب الكون الفساد"},{"id":"diwan-zaydun:23","bookId":"diwan-zaydun","type":"poem","seq":23,"chapter":"البحر: بسيط تام","title":"أستودع الله من أصفي الوداد له","page":"","text":"أستودع الله من أصفي الوداد له … محضا ، ولام به الواشي ، فلم أطع\nإلف ، ألذ غرور الوعد يصفح لي … عنه ، ويقنعني التعليل بالخدع\nتجلو المنى شخصه لي ، وهو محتجب … عني ، فما شئت من مرأى ومستمع\nيا بدر تم بدا في أفق مملكة ، … فراق مطلعا من خير مطلع\nأفدي بدائع شكل منك ، مضمرة ، … لقتل نفسي عمدا ، أشنع البدع\nتالله ، أكرم ما أمضى اليمين به ، … من دان في حبه بالصدق والورع\nما لذ لي قرب أنس أنت نازحة … عنه ، ولا ساغ عيش لست فيه معي"},{"id":"diwan-zaydun:24","bookId":"diwan-zaydun","type":"poem","seq":24,"chapter":"البحر: سريع","title":"يا قمرا مطلعه المغرب ،","page":"","text":"يا قمرا مطلعه المغرب ، … قد ضاق بي ، في حبك ، المذهب\nأعتب ، من ظلمك لي جاهدا ، … ويغلب الشوق ، فأستعتب\nألزمتني الذنب الذي جئته ، … صدقت ، فاصفح أيها المذنب"},{"id":"diwan-zaydun:25","bookId":"diwan-zaydun","type":"poem","seq":25,"chapter":"البحر: مجزوء الكامل","title":"يا مستخفا بعاشقيه ،","page":"","text":"يا مستخفا بعاشقيه ، … ومستغشا لناصحيه\nومن أطاع الوشاة فينا ، … حتى أطعنا السلو فيه\nالحمد لله ، إذ أراني … تكذيب ما كنت تدعيه\nمن قبل أن يهزم التسلي ؛ … ويغلب الشوق ما يليه"},{"id":"diwan-zaydun:26","bookId":"diwan-zaydun","type":"poem","seq":26,"chapter":"البحر: وافر تام","title":"أأسلب ، من وصالك ، ما كسيت ؟","page":"","text":"أأسلب ، من وصالك ، ما كسيت ؟ … وأعزل ، عن رضاك ، وقد وليت ؟\nوكيف ، وفي سبيل هواك طوعا ، … لقيت من المكاره ما لقيت !\nأسر عليك عتبا ليس يبقى ، … وأضمر فيك غيظا لا يبيت\nوما ردي على الواشين ، إلا : … رضيت بجور مالكتي رضيت"},{"id":"diwan-zaydun:27","bookId":"diwan-zaydun","type":"poem","seq":27,"chapter":"البحر: خفيف تام","title":"قال لي : اعتل من هويت ، حسود ؛","page":"","text":"قال لي : اعتل من هويت ، حسود ؛ … قلت : أنت العليل ويحك لا هو\nما الذي أنكروه من بثرات ، … ضاعفت حسنه وزادت حلاه\nجسمه ، في الصفاء والرقة ، الماء ، … فلا غرو أن حباب علاه"},{"id":"diwan-zaydun:28","bookId":"diwan-zaydun","type":"poem","seq":28,"chapter":"البحر: مجتث","title":"أنى أضيع عهدك ؟","page":"","text":"أنى أضيع عهدك ؟ … أم كيف أخلف وعدك\nوقد رأتك الأماني … رضى ، فلم تتعدك\nيا ليت ما لك عندي … من الهوى ، لي عندك\nفطال ليلك بعدي ، … كطول ليلي بعدك\nسلني حياتي أهبها ، … فلست أملك ردك\nالدهر عبدي ، لما … أصبحت ، في الحب ، عبدك\nعاودت ذكرى الهوى من بعد نسيان ، … واستحدث القلب شوقا بعد سلوان\nمن حب جارية ، يبدو بها صنم … من اللجين ، عليه تاج عقيان\nغريرة ، لم تفارقها تمائمها ، … تسبي العقول بساجي الطرف وسنان\nلأستجدن ، في عشقي لها ، زمنا … ينسي سوالف أيامي وأزماني\nحتى تكون لمن أحببت خاتمة ، … نسخت ، في حبها ، كفرا بإيمان"},{"id":"diwan-zaydun:29","bookId":"diwan-zaydun","type":"poem","seq":29,"chapter":"البحر: رمل تام","title":"إن تكن نالتك ، بالضرب ، يدي ؛","page":"","text":"إن تكن نالتك ، بالضرب ، يدي ؛ … وأصابتك بما لم أرد\nفلقد كنت ، لعمري ، فاديا … لك بالمال وبعض الولد\nفثقي مني بعهد ثابت ، … وضمير خالص المعتقد\nولئن ساءك يوم ، فاعلمي … أن سيتلوه سرور بغد"},{"id":"diwan-zaydun:30","bookId":"diwan-zaydun","type":"poem","seq":30,"chapter":"البحر: مجزوء الكامل","title":"يا سؤل نفسي إن أحكم ،","page":"","text":"يا سؤل نفسي إن أحكم ، … واختياري إن أخير\nكم لامني فيك الحسود ، … وفند الواشي ، فأكثرد\nقالوا : تغير بالسلو ، … وبالملامة قد تعير\nوتوهموك جنيت ذنبا … بالتجني ، ليس يغفر\nوبزعمهم أن ليس مثلي ، … في الرضى بالدون ، يعذر\nلم يعلموا أن الهوى … رق ، وأن الحسن أحمر"},{"id":"diwan-zaydun:31","bookId":"diwan-zaydun","type":"poem","seq":31,"chapter":"البحر: متقارب تام","title":"لئن كنت ، في السن ، ترب الهلال ،","page":"","text":"لئن كنت ، في السن ، ترب الهلال ، … لقد فقت ، في الحسن ، بدر الكمال\nأما والذي نكد الحظ في ، … دنو المكان ببعد المنال\nلقد بلغتني دواعي هواك … إلى غاية ، ما جرت لي ببال\nفقل للهوى : يجر ملء العنان ، … فميدان قلبي رحيب المجال"},{"id":"diwan-zaydun:32","bookId":"diwan-zaydun","type":"poem","seq":32,"chapter":"البحر: مجزوء الرمل","title":"أيها البدر الذي","page":"","text":"أيها البدر الذي … يملأ عيني من تأمل\nحمل القلب تباريح ال … تجني ، فتحمل\nليس لي صبر جميل ، … غير أني أتجمل\nثم لا يأس ، فكم قد … نيل أمر لم يؤمل"},{"id":"diwan-zaydun:33","bookId":"diwan-zaydun","type":"poem","seq":33,"chapter":"البحر: طويل","title":"أأجفى بلا جرم ، وأقصى بلا ذنب ،","page":"","text":"أأجفى بلا جرم ، وأقصى بلا ذنب ، … سوى أنني محض الهوى ، صادق الحب\nأغاديك بالشكوى ، فأضحي على القلى ، … وأرجوك للعتبى ، فأظفر بالعتب\nفديتك ، ما للماء ، عذبا على الصدى ، … وإن سمتني خسفا ، محلك من قلبي\nولولاك ، ما ضاقت حشاي ، صبابة ، … جعلت قراها الدمع سكبا على سكب"},{"id":"diwan-zaydun:34","bookId":"diwan-zaydun","type":"poem","seq":34,"chapter":"البحر: كامل تام","title":"باعدت ، بالإعراض ، غير مباعد ،","page":"","text":"باعدت ، بالإعراض ، غير مباعد ، … زهدت فيمن ليس فيك بزاهد\nوسقيتني ، من ماء هجرك ، ما له … أصبحت أشرق بالزلال البارد\nهلا جعلت ، فدتك نفسي ، غاية … للعتب ، أبلغها بجهد الجاهد\nلا تفسدن ، ما قد تأكد بينا … من صالح ، خطرات ظن فاسد\nحاشاك من تضييع ألف وسيلة ، … شجي العدو لها ، بذنب واحد\nإن أجنه خطأ ، فقد عاقبتني ، … ظلما ، بأبلغ من عقاب العامد\nعودي لما أصفيتنيه من الهوى … بدءا ، فلست لما كرهت بعائد\nوضعي قناع السخط عن وجه الرضا … كيما أخر إليه أول ساجد"},{"id":"diwan-zaydun:35","bookId":"diwan-zaydun","type":"poem","seq":35,"chapter":"البحر: وافر تام","title":"ثقي بي ، يا معذبتي ، فإني","page":"","text":"ثقي بي ، يا معذبتي ، فإني … سأحفظ فيك ما ضيعت مني\nوإن أصبحت ، قد أرضيت قوما … بسخطي ، لم يكن ذا فيك ظني\nوهل قلب كقلبك في ضلوعي ، … فأسلو عنك ، حين سلوت عني ؟\nتمنت ، أن تنال رضاك ، نفسي ، … فكان ، منية ، ذاك التمني\nولم أجن الذنوب فتحقديها ، … ولكن عادة منك التجني"},{"id":"diwan-zaydun:36","bookId":"diwan-zaydun","type":"poem","seq":36,"chapter":"البحر: خفيف تام","title":"أنت معنى الضنى ، وسر الدموع ،","page":"","text":"أنت معنى الضنى ، وسر الدموع ، … وسبيل الهوى ، وقصد الولوع\nأنت والشمس ضرتان ، ولكن … لك ، عند الغروب ، فضل الطلوع\nليس بالمؤيسي تكلفك العتب ، … دلالا ، من الرضى المطبوع\nإنما أنت ، والحسود معنى ، … كوكب يستقيم بعد الرجوع"},{"id":"diwan-zaydun:37","bookId":"diwan-zaydun","type":"poem","seq":37,"chapter":"البحر: كامل تام","title":"أهدي إلي بقية المسواك ،","page":"","text":"أهدي إلي بقية المسواك ، … لا تظهري بخلا بعود أراك\nفلعل نفسي ، أن ينفس ساعة … عنها ، بتقبيل المقبل فاك\nيا كوكبا ، بارى سناه سناءه ، … تزهى القصور به على الأفلاك\nقرت وفازت ، بالخطير من المنى ، … عين تقلب لحظها ، فتراك"},{"id":"diwan-zaydun:38","bookId":"diwan-zaydun","type":"poem","seq":38,"chapter":"البحر: كامل تام","title":"إن ساء فعلك بي ، فما ذنبي أنا ؟","page":"","text":"إن ساء فعلك بي ، فما ذنبي أنا ؟ … حسب المتيم أنه قد أحسنا\nلم أسل حتى كان عذرك ، في الذي … أبديته ، أخفى ، وعذري أبينا\nولقد شكوتك ، بالضمير ، إلى الهوى ، … ودعوت ، من حنق ، عليك فأمنا\nمنيت نفسي ، من وفائك ، ضلة ، … ولقد تغر المرء بارقة المنى"},{"id":"diwan-zaydun:39","bookId":"diwan-zaydun","type":"poem","seq":39,"chapter":"البحر: طويل","title":"أغائبة عني ، وحاضرة معي !","page":"","text":"أغائبة عني ، وحاضرة معي ! … أناديك ، لما عيل صبري ، فاسمعي\nأفي الحق أن أشقى بحبك ، أو أرى … حريقا بأنفاسي ، غريقا بأدمعي ؟\nألا عطفة تحيا بها نفس عاشق … جعلت الردى منه بمرأى ومسمع ؟\nصليني ، بعض الوصل ، حتى تبيني … حقيقة حالي ، ثم ما شئت فاصنعي"},{"id":"diwan-zaydun:40","bookId":"diwan-zaydun","type":"poem","seq":40,"chapter":"البحر: كامل تام","title":"سأحب أعدائي لأنك منهم ،","page":"","text":"سأحب أعدائي لأنك منهم ، … يا من يصح ، بمقلتيه ، ويسقم\nأصبحت تسخطني ، فأمنحك الرضى … محضا ، وتظلمني ، فلا أتظلم\nيا من تآلف ليله ونهاره ، … فالحسن بينهما مضيء ، مظلم\nقد كان ، في شكوى الصبابة ، راحة ، … لو أنني أشكو إلى من يرحم"},{"id":"diwan-zaydun:41","bookId":"diwan-zaydun","type":"poem","seq":41,"chapter":"البحر: بسيط تام","title":"لما اتصلت اتصال الخلب بالكبد ،","page":"","text":"لما اتصلت اتصال الخلب بالكبد ، … ثم امتزجت امتزاج الروح بالجسد\nساء الوشاة مكاني منك ، واتقدت ، … في صدر كل عدو ، جمرة الحسد\nفليسخط الناس ، لا أهد الرضى لهم ، … ولا يضع لك عهد ، آخر الأبد\nلو استطعت ، إذا ما كنت غائبة ، … غضضت طرفي ، فلم أنظر إلى أحد"},{"id":"diwan-zaydun:42","bookId":"diwan-zaydun","type":"poem","seq":42,"chapter":"البحر: مجزوء الكامل","title":"يا ليل طل ، لا أشتهي ،","page":"","text":"يا ليل طل ، لا أشتهي ، … إلا بوصل ، قصرك\nلو بات عندي قمري ، … ما بت أرعى قمرك\nيا ليل خبر : أنني … ألتذ عنه خبرك\nبالله قل لي : هل وفى ؟ … فقال : لا ، بل غدرك !"},{"id":"diwan-zaydun:43","bookId":"diwan-zaydun","type":"poem","seq":43,"chapter":"البحر: متقارب تام","title":"لئن فاتني منك حظ النظر ،","page":"","text":"لئن فاتني منك حظ النظر ، … لأكتفين بسماع الحبر\nوإن عرضت غفلة للرقيب ، … فحسبي تسليمة تختصر\nأحاذر أن تتظنى الوشاة ، … وقد يستدام الهوى بالحذر\nوأصبر مستيقنا أنه … سيحظى ، بنيل المنى ، من صبر"},{"id":"diwan-zaydun:44","bookId":"diwan-zaydun","type":"poem","seq":44,"chapter":"البحر: متقارب تام","title":"سأقنع منك بلحظ البصر ،","page":"","text":"سأقنع منك بلحظ البصر ، … وأرضى بتسليمك المختصر\nولا أتخطى التماس المنى ، … ولا أتعدى اختلاس النظر\nأصونك من لحظات الظنون ، … وأعليك عن خطرات الفكر\nوأحذر من لحظات الرقيب ، … وقد يستدام الهوى بالحذر"},{"id":"diwan-zaydun:45","bookId":"diwan-zaydun","type":"poem","seq":45,"chapter":"البحر: مجزوء الرمل","title":"هل لداعيك مجيب ؟","page":"","text":"هل لداعيك مجيب ؟ … أم لشاكيك طبيب ؟\nيا قريبا ، حين ينأى ، … حاضرا ، حين يغيب !\nكيف يسلوك محب ، … زانه منك حبيب !\nإنما أنت نسيم ، … تتلقاه القلوب\nقد علمنا علم ظن ، … هو ، لا شك ، مصيب\nأن سر الحسن مما … أضمرت تلك الجيوب"},{"id":"diwan-zaydun:46","bookId":"diwan-zaydun","type":"poem","seq":46,"chapter":"البحر: بسيط تام","title":"يا ناسيا لي ، على عرفانه ، تلفي ،","page":"","text":"يا ناسيا لي ، على عرفانه ، تلفي ، … ذكرك مني ، بالأنفاس ، موصول\nوقاطعا صلتي ، من غير ما سبب ، … تالله ! إنك ، عن روحي ، لمسؤول\nما شئت فاصنعه ، كل منك محتمل ، … والذنب مغتفر ، والعذر مقبول\nلو كنت حظي ، لم أطلب به بدلا ، … أو نلت منك الرضا ، لم يبق مأمول"},{"id":"diwan-zaydun:47","bookId":"diwan-zaydun","type":"poem","seq":47,"chapter":"البحر: كامل تام","title":"أرخصتني ، من بعد ما أغليتني ،","page":"","text":"أرخصتني ، من بعد ما أغليتني ، … وحططتني ، ولطالما أعليتني\nبادرتني بالعزل عن خطط الرضى ، … ولقد محضت النصح ، إذ وليتني\nهلا ، وقد أعلقتني شرك الهوى … عللتني بالوصل ، أو سليتني ؟\nالصبر شهد ، عندما جرعتني ، … والنار برد ، عندما أصليتني\nكنت المنى ، فأذقتني غصص الأذى ، … يا ليتني ما فهت فيك بليتني"},{"id":"diwan-zaydun:48","bookId":"diwan-zaydun","type":"poem","seq":48,"chapter":"البحر: مجتث","title":"يا قاطعا حبل ودي ،","page":"","text":"يا قاطعا حبل ودي ، … وواصلا حبل صدي\nوساليا ، ليس يدري … بطول بثي ووجدي\nلو كان ، عندك ، مني … مثل الذي منك عندي\nلبت ، بعدي ، مثلي ، … وبت مثلك بعدي"},{"id":"diwan-zaydun:49","bookId":"diwan-zaydun","type":"poem","seq":49,"chapter":"البحر: بسيط تام","title":"جازيتني عن تمادي الوصل هجرانا ،","page":"","text":"جازيتني عن تمادي الوصل هجرانا ، … وعن تمادي الأسى والشوق سلوانا\nبالله هل كان قتلي في الهوى خطأ ، … أم جئته عامدا ظلما وعدوانا ؟\nعهدي كعهدك ، ما الدنيا تغيره ، … وإن تغير منك العهد ألوانا\nما صح ودي ، إلا اعتل ودك لي ، … ولا أطعتك ، إلا زدت عصيانا\nيا ألين الناس أعطافا ، وأفتنهم … لحظا ، وأعطر أنفاسا وأردانا\nحسنت خلقا فأحسن لا تسؤ خلقا ، … ما خير ذي الحسن إن لم يول إحسانا"},{"id":"diwan-zaydun:50","bookId":"diwan-zaydun","type":"poem","seq":50,"chapter":"البحر: خفيف تام","title":"لو تركنا بأن نعودك عدنا ،","page":"","text":"لو تركنا بأن نعودك عدنا ، … وقضينا الذي علينا ، وزدنا\nغير أن الهوى استطار حديثا ، … فانتحتنا العيون لما حسدنا\nفلو أن النفوس تقبل منا ، … لسمحنا بها ، فداء ، وجدنا"},{"id":"diwan-zaydun:51","bookId":"diwan-zaydun","type":"poem","seq":51,"chapter":"البحر: مجزوء الكامل","title":"أشمت ، بي فيك ، العدا ؛","page":"","text":"أشمت ، بي فيك ، العدا ؛ … وبلغت ، من ظلمي ، المدى\nلو كان يملك فدية ، … من حبك ، القلب افتدى\nكنت الحياة لعاشق ، … مذ حلت ، أيقن بالردى\nلم يسل عنك ، ولو سلا … لعذرته ، فبك افتدى\nضيعت عهد محبة ، … كالورد سامره الندى\nأين ادعاؤك للوفاء ، … وما عدا مما بدا ؟"},{"id":"diwan-zaydun:52","bookId":"diwan-zaydun","type":"poem","seq":52,"chapter":"البحر: بسيط تام","title":"بيني وبينك ما لو شئت لم يضع","page":"","text":"بيني وبينك ما لو شئت لم يضع … سر ، إذا ذاعت الأسرار ، لم يذع\nيا بائعا حظه مني ، ولو بذلت … لي الحياة ، بحظي منه ، لم أبع\nيكفيك أنك ، إن حملت قلبي ما … لم تستطعه قلوب الناس يستطع\nته أحتمل واستطل أصبر وعز أهن … وول أقبل وقل أسمع ومر أطع"},{"id":"diwan-zaydun:53","bookId":"diwan-zaydun","type":"poem","seq":53,"chapter":"البحر: بسيط تام","title":"لو كان قولك : مت ، ما كان ردي لا ،","page":"","text":"لو كان قولك : مت ، ما كان ردي لا ، … يا جائر الحكم ، أفديه بمن عدلا\nأبديت لي ، من أفانين القلى ، عبرا … أرسلتني ، في أحاديث الهوى ، مثلا\nلم تبق جارحة بالهجر من جسدي ، … إلا خلعت عليها ، بالضنى ، حللا\nفليغن كفك أني بعض من ملكت ، … وليكف طرفك أني بعض من قتلا\nولتقض ما شئت من هجر ومن صلة … لا أقض ما عشت سلوانا ، ولا مللا\nسقيا لعهدك ، والأيام تقبلني … وجه السرور به ، جذلان ، مقتبلا\nإذ الزمان بليغ في مساعدتي ، … يهدي إلي ، تفاريق المنى ، جملا\nإن كان لي أمل ، إلا رضاك ، فلا … بلغت ، يا أملي ، من دهري الأملا"},{"id":"diwan-zaydun:54","bookId":"diwan-zaydun","type":"poem","seq":54,"chapter":"البحر: بسيط تام","title":"من مبلغ عني البدر الذي كملا","page":"","text":"من مبلغ عني البدر الذي كملا … في مطلع الحسن ، والغصن الذي اعتدلا\nأن الزمان ، الذي أهدى مودته … إلي ، مرتهن شكري بما فعلا\nأما الحبيب الذي أبدى الجفاء لنا ، … فما رأينا قلاه حادثا جللا\nولم نزد أن ظفرنا ملء أعيننا … بالمشتري ، فتجنبنا له زحلا\nأنت الحبيب ، الذي ما زلت ألحفه … ظل الهوى ، وأسقيه الرضا عللا\nهذي الحقيقة ، لا قولي مخادعة ، … لو كان قولك : مت ، ما كان ردي : لا !"},{"id":"diwan-zaydun:55","bookId":"diwan-zaydun","type":"poem","seq":55,"chapter":"البحر: بسيط تام","title":"قد نالني منك ما حسبي به وكفى ،","page":"","text":"قد نالني منك ما حسبي به وكفى ، … يا من تناهيت في إلطافه ، فجفا\nعللتني بالمنى ، حتى إذا علقت … بالنفس لم أعط من أسبابها طرفا\nغيرت عن خلق ، قد لان لي زمنا … لين النسيم ، فلما لذ لي عصفا\nلا يحبطن عمل ، أرضاك صالحه ، … ففي سبيلك أنفقت الهوى سرفا"},{"id":"diwan-zaydun:56","bookId":"diwan-zaydun","type":"poem","seq":56,"chapter":"البحر: طويل","title":"على الثغب الشهدي مني تحية ،","page":"","text":"على الثغب الشهدي مني تحية ، … زكت ، وعلى وادي العقيق سلام\nولا زال نور في الرصافة ، ضاحك … بأرجائها ، يبكي عليه غمام\nمعاهد لهو لم تزل في ظلالها … تدار علينا ، للمجون ، مدام\nزمان ، رياض العيش خضر نواصر … ترف ، وأمواه السرور جمام\nفإن بان مني عهدها ، فبلوعة … يشب لها ، بين الضلوع ، ضرام\nتذكرت أيامي بها ، فتبادرت … دموع ، كما خان الفريد نظام\nوصحبة قوم كالمصابيح ، كلهم … إذ هز ، للخطب الملم ، حسام\nإذا طاف بالراح المدير عليهم ، … أطاف به بيض الوجوه ، كرام\nوأحور ساجي الطرف حشو جفونه … سقام ، برى ، الأجسام ، منه سقام\nتخال قضيب البان في طي برده ، … إذا اهتز منه معطف وقوام\nيدير على رغم العدا ، من وداده … سلافا ، كأن المسك منه ختام\nفمن أجله أدعو لقرطبة المنى … بسقيا ضعيف الطل ، وهو رهام\nمحل غنينا بالتصابي خلاله ، … فأسعدنا ، والحادثات نيام\nفما لحقت تلك الليالي ملامة ، … ولا ذم ، من ذاك الحبيب ، ذمام"},{"id":"diwan-zaydun:57","bookId":"diwan-zaydun","type":"poem","seq":57,"chapter":"البحر: رمل تام","title":"لم يكن هجر حبيبي عن قلى ،","page":"","text":"لم يكن هجر حبيبي عن قلى ، … لا ولا ذاك التجني مللا\nسره شكري ، إذ عافى ، ولم … يدر ما غاية صبري فابتلى\nأنا راض بالذي يرضى به … لي من لو قال : مت ، ما قلت : لا\nمثل في كل حسن ، مثل ما … صار ذلي ، في هواه ، مثلا\nيا فتيت المسك ، يا شمس الضحى ، … يا قضيب اللبان ، يا ريم الفلا\nإن يكن لي أمل ، غير الرضا ، … منك ، لا بلغت ذاك الأملا"},{"id":"diwan-zaydun:58","bookId":"diwan-zaydun","type":"poem","seq":58,"chapter":"البحر: طويل","title":"أجد ، ومن أهواه ، في الحب ، عابث ؛","page":"","text":"أجد ، ومن أهواه ، في الحب ، عابث ؛ … وأوفي له بالعهد ، إذ هو ناكث\nحبيب نأى عني ، مع القرب والأسى ، … مقيم له ، في مضمر القلب ، ماكث\nجفاني بإلطاف العدا ، وأزاله ، … عن الوصل ، رأي في القطيعة حادث\nتغيرت عن عهدي ، وما زلت واثقا … بعهدك ، لكن غيرتك الحوادث\nوما كنت ، إذ ملكتك القلب ، عالما … بأني ، عن حتفي ، بكفي باحث\nفديتك ، إن الشوق لي مذ هجرتني … مميت فهل لي من وصالك باعث ؟\nستبلى الليالي ، والوداد بحاله … جديد وتفنى وهو للأرض وارث\nولو أنني أقسمت : أنك قاتلي ، … وأني مقتول ، لما قيل : حانث"},{"id":"diwan-zaydun:59","bookId":"diwan-zaydun","type":"poem","seq":59,"chapter":"البحر: مجزوء الرمل","title":"يا غزالا جمعت فيه ،","page":"","text":"يا غزالا جمعت فيه ، … من الحسن ، فنون\nأنت في القرب ، وفي البعد ، … من النفس ، مكين\nبهواك ، الدهر ، ألهو ، … وبحبيك أدين\nمنية الصب أغثني ، … قد دنت مني المنون\nواحفظ العهد ، فإني … لست ، والله ، أخون\nوارحمن صبا شجيا ، … قد أذابته الشجون\nليله هم وغم ، … وسقام ، وأنين\nشفه الحب ، فأمسى ، … سقما ، لا يستبين\nصار ، للأشواق ، نهبا ، … فنبت عنه العيون"},{"id":"diwan-zaydun:60","bookId":"diwan-zaydun","type":"poem","seq":60,"chapter":"البحر: بسيط تام","title":"يا معطشي ، من وصال كنت وارده ،","page":"","text":"يا معطشي ، من وصال كنت وارده ، … هل منك لي غلة إن صحت : واعطشي\nكسوتني ، من ثياب السقم ، أسبغها … ظلما وصيرت من لحف الضنى فرشي\nإني بصرت الهوى ، عن مقلة كحلت … بالسحر منك ، وخد بالجمال وشي\nلما بدا الصدغ مسودا بأحمره … أرى التسالم بين الروم والحبش\nأوفى إلى الخد ، ثم انصاع منعطفا … كالعقربان انثنى من خوف محترش\nلو شئت زرت وسلك النجم منتظم ، … والأفق يختال في ثوب من الغبش\nصبا ، إذا التذت الأجفان طعم كرى ، … جفا المنام ، وصاح الليل : يا قرشي\nهذا وإن تلفت نفسي فلا عجب ، … قد كان موتي من تلك الجفون خشي"},{"id":"diwan-zaydun:61","bookId":"diwan-zaydun","type":"poem","seq":61,"chapter":"البحر: وافر تام","title":"أتهجرني وتغصبني كتابي ؟","page":"","text":"أتهجرني وتغصبني كتابي ؟ … وما في الحق غصبي واجتنابي\nأيجمل أن أبيحك محض ودي … وأنت تسومني سوء العذاب\nفديتك ، كم تغض الطرف دوني ؛ … وكم أدعوك من خلف الحجاب\nوكم لي من فؤادك ، بعد قرب ، … مكان الشيب في نفس الكعاب\nأعد ، في عبدك المظلوم ، رأيا … تنال به الجزيل من الثواب\nوإن تبخل عليه ، فرب دهر … وهبت له رضاك بلا حساب"},{"id":"diwan-zaydun:62","bookId":"diwan-zaydun","type":"poem","seq":62,"chapter":"البحر: بسيط تام","title":"أذكرتني سالف العيش ، الذي طابا ،","page":"","text":"أذكرتني سالف العيش ، الذي طابا ، … يا ليت غائب ذاك العهد قد آبا\nإذ نحن في روضة ، للوصل ، نعمها ، … من السرور ، غمام ، فوقها صابا\nإني لأعجب من شوق يطاولني ، … فكلما قيل فيه : قد قضى ، ثابا\nكم نظرة لك في عيني علمت بها ، … يوم الزيارة ، أن القلب قد ذابا\nقلب يطيل مقاماتي لطاعتكم ، … فإن أكلفه عنكم سلوة يابى\nما توبتي بنصوح ، من محبتكم ، … لا عذب الله ، إلا عاشقا تابا"},{"id":"diwan-zaydun:63","bookId":"diwan-zaydun","type":"poem","seq":63,"chapter":"البحر: بسيط تام","title":"أما رضاك ، فعلق ما له ثمن ،","page":"","text":"أما رضاك ، فعلق ما له ثمن ، … لو كان سامحني ، في وصله ، الزمن\nتبكي فراقك عين ، أنت ناظرها ، … قد لج في هجرها عن هجرك الوسن\nإن الزمان الذي عهدي به حسن ، … قد حال مذ غاب عني وجهك الحسن\nأنت الحياة ، فإن يقدر فراقك لي ، … فليحفر القبر ، أو فليحضر الكفن\nوالله ما ساءني أني جفيت ضنى ، … بل ساءني أن سري ، بالضنى ، علن\nلو كان أمري ، في كتم الهوى ، بيدي … ما كان يعلم ، ما في قلبي ، البدن"},{"id":"diwan-zaydun:64","bookId":"diwan-zaydun","type":"poem","seq":64,"chapter":"البحر: سريع","title":"سري وجهري أنني هائم ،","page":"","text":"سري وجهري أنني هائم ، … قام بك العذر ، فلا لائم\nلا ينم الواشي ، الذي غرني ، … ها أنا ، في ظل الرضى ، نائم\nعدت إلى الوصل كما أشتهي ، … فالهجر باك ، والرضى باسم\nحسبي ، أنا المظلوم ، فيما جرى ، … وإن تشأ قلت : أنا الظالم !\nيا سائلا عما بنفسي له ، … تجنبا ، وهو به عالم\nمعنى الهوى أنت وشخص المنى ، … دعني مما يزعم الزاعم"},{"id":"diwan-zaydun:65","bookId":"diwan-zaydun","type":"poem","seq":65,"chapter":"البحر: وافر تام","title":"عذيري من خليل يستطيل ،","page":"","text":"عذيري من خليل يستطيل ، … يميل ، مع الزمان ، كما يميل\nويرضى أن تضيع سدى حقوقي ، … وباعي ، في الهوى ، باع طويل\nأشمسا أشرقت من عبد شمس ! … أما لك ، في سوى قلبي ، أفول ؟\nأما يمحى عتابك كل يوم ؟ … أما يرجى ، إلى وصل ، وصول ؟\nولو أجد السبيل لطرت وجدا ، … ولكن ما إلى هذا سبيل\nكتابي ، عن ودادك ، لا يزول ، … وعهدي ، مثل عهدك ، لا يحول"},{"id":"diwan-zaydun:66","bookId":"diwan-zaydun","type":"poem","seq":66,"chapter":"البحر: مجزوء الرمل","title":"شكوى وعتابما على ظني باس ،","page":"","text":"شكوى وعتابما على ظني باس ، … يجرح الدهر وياسو\nربما أشرف بالمر … ء ، على الآمال ، ياس\nولقد ينجيك إغفا … ل ويرديك احتراس\nوالمحاذير سهام ؛ … والمقادير قياس\nولكم أجدى قعود ؛ … ولكم أكدى التماس\nوكذا الدهر إذا ما … عز ناس ، ذل ناس\nوبنو الأيام أخيا … ف : سراة وخساس\nنلبس الدنيا ، ولكن … متعة ذاك اللباس\nيا أبا حفص ، وما ساواك ، … في فهم ، إياس\nمن سنا رأيك لي ، في … غسق الحطب ، اقتباس\nوودادي لك نص ، … لم يخالفه قياس\nأنا حيران ، وللأمر … وضوح والتباس\nما ترى في معشر حالوا … عن العهد ، وخاسوا\nورأوني سامريا … يتقى منه المساس\nأذؤب هامت بلحمي ، … فانتهاش وانتهاس\nكلهم يسأل عن حالي … وللذئب اعتساس\nإن قسا الدهر فللماء … من الصخر انبجاس\nولئن أمسيت محبوسا ، … فللغيث احتباس\nيلبد الورد السبنتى ، … وله بعد افتراس\nفتأمل ! كيف يغشى … مقلة المجد النعاس ؟\nويفت المسك في الترب ، … فيوطا ويداس ؟\nلا يكن عهدكي وردا ! … إن عهدي لك آس\nوأدر ذكري كأسا ، … ما امتطت كفك كاس\nواغتنم صفو الليالي ؛ … إنما العيش اختلاس\nوعسى أن يسمح الدهر ، … فقد طال الشماس"},{"id":"diwan-zaydun:67","bookId":"diwan-zaydun","type":"poem","seq":67,"chapter":"البحر: طويل","title":"شحطنا وما بالدار نأي ولا شحط ،","page":"","text":"شحطنا وما بالدار نأي ولا شحط ، … وشط بمن نهوى المزار وما شطوا\nأأحبابنا ! ألوت بحادث عهدنا … حوادث ، لا عقد عليها ولا شرط\nلعمركم إن الزمان ، الذي قضى … بشت جميع الشمل منا ، لمشتط\nوأما الكرى مذ لم أزركم ، فهاجر ، … زيارته غب ، وإلمامه فرط\nوما شوق مقتول الجوانح بالصدى … إلى نطفة زرقاء ، أضمرها وقط\nبأبرح من شوقي إليكم ، ودون ما … أدير المنى عنه القتادة والخرط\nوفي الربرب الإنسي أحوى ، كناسه … نواحي ضميري لا الكثيب ولا السقط\nغريب فنون الحسن ، يرتاح درعه … متى ضاق ذرعا بالذي حازه المرط\nكأن فؤادي ، يوم أهوى مودعا ، … هوى خافقا منه بحيث هوى القرط\nإذا ما كتاب الوجد أشكل سطره ، … فمن زفرتي شكل ومن عبرتي نقط\nألا هل أتى الفتيان أن فتاهم … فريسة من يعدو ، ونهزة من يسطو\nوأن الجواد الفائت الشأو صافن ، … تخونه شكل ، وأزرى به ربط\nوأن الحسام العضب ثاو بجفنه ، … وما ذم من غربيه قد ولا قط\nعليك أبا بكر بكرت بهمة ، … لها الخطر العالي ، وإن نالها حط\nأبي ، بعدما هيل التراب على أبي ، … ورهطي فذا ، حين لم يبق لي رهط\nلك النعمة الخضراء ، تندى ظلالها … علي ، ولا جحد لدي ، ولا غمط\nولولاك لم تثقب زناد قريحتي ، … فينتهب الظلماء من نارها سقط\nولا ألفت أيدي الربيع بدائعي ، … فمن خاطري نثر ومن زهره لقط\nهرمت ، وما للشيب وخط بمفرقي ، … وكائن لشيب الهم في كبدي وخط\nوطاول سوء الحال نفسي ، فأذكرت … من الروضة الغناء ، طاولها القحط\nمئون من الأيام خمس قطعتها … أسيرا ، وإن لم يبد شد ولا قمط\nأتت بي ، كما ميص الإناء من الأذى ، … وأذهب ما بالثوب من درن مسط\nأتدنو قطوف الجنتين لمعشر ، … وغايتي السدر القليل أو الخمط\nوما كان ظني أن تغرني المنى ، … وللعز في العشواء من ظنه خبط\nأما ، وأرتني النجم موطئ أخمصي ، … لقد أوطأت خدي لأخمص من يخطو\nومستبطإ العتبى ، إذا قلت قد أنى … رضاه ، تمادى العتب واتصل السخط\nوما زال يدنيني وينئي قبوله … هوى سرف منه ، وصاغية فرط\nونظم ثناء في نظام ولاية ، … تحلت به الدنيا ، لآلئه وسط\nعلى خصرها منه وشاح مفصل ؛ … وفي رأسها تاج ؛ وفي جيدها سمط\nعدا سمعه عني ، وأصغى إلى عدى … لهم في أديمي كلما استمكنوا عط\nبلغت المدى ، إذ قصروا ، فقلوبهم … مكامن أضغان أساودها رقط\nيولونني عرض الكراهة والقلى ، … وما دهرهم إلا النفاسة والغمط\nوقد وسموني بالتي لست أهلها ، … ولم يمن أمثالي بأمثالها قط\nفررت ، فإن قالوا الفرار إرابة ، … فقد فر موسى حين هم به القبط\nوإني لراج أن تعود ، كبدئها ، … لي الشيمة الزهراء والحلق السبط\nوحلم امرىء تعفو الذنوب لعفوه … وتمحى الخطايا مثلما محي الخط\nفما لك لا تختضني بشفاعة ، … يلوح على دهري لميسمها علط\nيفي بنسيم العنبر الورد نفحها ، … إذا شعشع المسك الأحم به خلط\nفإن يسعف المولى فنعمى هنيئة ، … تنفس عن نفس ألظ بها ضغط\nوإن يأب إلا قبض مبسوط فضله ، … ففي يد مولى فوقه القبض والبسط"},{"id":"diwan-zaydun:68","bookId":"diwan-zaydun","type":"poem","seq":68,"chapter":"البحر: طويل","title":"بنيت فلا تهدم ، ورشت فلا تبر ؛","page":"","text":"بنيت فلا تهدم ، ورشت فلا تبر ؛ … وأمرضت حسادي وحاشاك أن تبري\nأرى نبوة ، لم أدر سر اعتراضها ؛ … وقد كان يجلو عارض الهم أن أدري\nجفاء ، هو الليل ادلهم ظلامه ، … فلا كوكب للعذر في أفقه يسري\nهب العزل أضحى للولاية غاية ؛ … فما غاية الموفي من الظل أن يكري\nففيم أرى رد السلام إشارة ، … تسوغ بي ازراء من شاء أن يزري\nأناس هم أخشى للذعة مقولي ، … إذا لم يكن مما فعلت لهم مضر\nفإن عاقت الأقدار ، فالنفس حرة ؛ … وإن تكن العتبى ، فأحر بها أحر !"},{"id":"diwan-zaydun:69","bookId":"diwan-zaydun","type":"poem","seq":69,"chapter":"البحر: متقارب تام","title":"أثرت هزبر الشرى ، إذ ربض ،","page":"","text":"أثرت هزبر الشرى ، إذ ربض ، … ونبهته ، إذ هدا فاغتمض\nوما زلت تبسط ، مسترسلا ، … إليه يد البغي ، لما انقبض\nحذار حذار ، فإن الكريم ، … إذا سيم خسفا ، أبى ، فامتعض\nفإن سكون الشجاع النهوس ، … ليس بمانعه أن يعض\nوإن الكواكب لا تستزل ؛ … وإن المقادير لا تعترض\nإذا ريغ ، فليقتصد مسرف ، … مساع يقصر عنها الحفض\nوهل وارد الغمر ، من عده ، … يقاس به مستشف البرض ؟\nإذا الشمس قابلتها أرمدا ، … فحظ جفونك في أن تغض\nأرى كل مجر ، أبا عامر ، … يسر إذا في خلاء ركض\nأعيذك من أن ترى منزعي ، … إذا وتري ، بالمنايا ، انقبض\nفإني ألين لمن لان لي ، … وأترك من رام قسري حرض\nوكم حرك العجب من حائن ، … فغادرته ، ما به من حبض\nأبا عامر ، أين ذاك الوفاء ، … إذ الدهر وسنان ، والعيش غض ؟\nوأين الذي كنت تعتد ، من … مصادقتي ، الواجب المفترض ؟\nتشوب وأمحض ، مستبقيا ؛ … وهيهات من شاب ممن محض !\nأبن لي ، ألم أضطلع ، ناهضا ، … بأعباء برك ، فيمن نهض ؟\nألم تنش ، من أدبي ، نفحة ، … حسبت بها المسك طيبا يفض ؟\nألم تك ، من شيمتي ، غاديا … إلى ترع ، ضاحكتها فرض ؟\nولولا اختصاصك لم ألتفت … لحاليك : من صحة أو مرض\nولا عادني ، من وفاء ، سرور ؛ … ولا نالني ، لجفاء ، مضض\nيعز اعتصار الفتى ، واردا ، … إذا البارد العذب أهدى الجرض\nعمدت لشعري ، ولم تتئب ، … تعارض جوهره ، بالعرض\nأضاقت أساليب هذا القريض ؟ … أم قد عفا رسمه فانقرض ؟\nلعمري ، لفوقت سهم النضال … وأرسلته ، لو أصبت الغرض\nوشمرت للخوض في لجة ، … هي\nوغرك ، من عهد ولادة ، … سراب تراءى ، وبرق ومض\nتظن الوفاء بها ، والظنون … فيها تقول على من فرض :\nهي الماء يأبى على قابض ، … ويمنع زبدته من مخض\nونبئتها ، بعدي ، استحمدت … بسري إليك لمعنى غمض\nأبا عامر ! عثرة فاستقل ، … لتبرم ، من ودنا ، ما انتقض\nولا تعتصم ، ضلة ، بالحجاج ؛ … وسيم ، فرب احتجاج دحض\nوإلا انتحتك جيوش العتاب ، … مناجزة ، في قضيض وقض\nوأنذر خليلك ، من ماهر … بطب الجنون ، إذا ما عرض\nكفيل ببط خراج عسا ؛ … جريء على شق عرق نبض\nيبادر بالكي ، قبل الضماد ، … ويسعط بالسم لا بالحضض\nوأشعره أني انتخبت البديل ؛ … وأعلمه أني استجدت العوض\nفلا مشربي ، لقلاه ، أمر ؛ … ولا مضجعي ، لنواه ، أقض\nوإن يد البين مشكورة … لعار أماط ، ووصم رحض\nوحسبي أني أطبت الجنى … لإبانه ، وأبحت النفض\nويهنيك أنك ، يا سيدي ، … غدوت مقارن ذاك الربض"},{"id":"diwan-zaydun:70","bookId":"diwan-zaydun","type":"poem","seq":70,"chapter":"البحر: رمل تام","title":"ودع الصبر محب ودعك ،","page":"","text":"ودع الصبر محب ودعك ، … ذائع من سره ما استودعك\nيقرع السن على أن لم يكن … زاد في تلك الحطا ، إذ شيعك\nيا أخا البدر سناء وسنا ؛ … حفظ الله زمانا أطلعك\nإن يطل ، بعدك ، ليلي ، فلكم … بت أشكو قصر الليل معك !"},{"id":"diwan-zaydun:71","bookId":"diwan-zaydun","type":"poem","seq":71,"chapter":"البحر: كامل تام","title":"ما للمدام تديرها عيناك ،","page":"","text":"ما للمدام تديرها عيناك ، … فيميل في سكر الصبا عطفاك ؟\nهلا مزجت لعاشقيك سلافها … ببرود ظلمك أو بعذب لماك ؟\nبل ما عليك ، وقد محضت لك الهوى ، … في أن أفوز بحظوة المسواك ؟\nناهيك ظلما أن أضر بي الصدى … برحا ، ونال البرء عود أراك\nواها لعطفك ، والزمان كأنما … صبغت غضارته ببرد صباك\nوالليل ، مهما طال ، قصر طوله … هاتي ، وقد غفل الرقيب ، وهاك\nولطالما اعتل النسيم ، فخلته … شكواي رقت فاقتضت شكواك\nإن تألفي سنة النؤوم خلية ، … فلطالما نافرت في كراك\nأو تحتبي بالهجر في نادي القلى ، … فلكم حللت إلى الوصال حباك\nأما منى نفسي ، فأنت جميعها ؛ … يا ليتني أصبحت بعض مناك\nيدنو بوصلك ، حين شط مزاره ، … وهم ، أكاد به أقبل فاك\nولئن تجنبت الرشاد بغدرة … لم يهو بي ، في الغي ، غير هواك\nللجهوري ، أبي الوليد ، خلائق … كالروض ، أضحكه الغمام الباكي\nملك يسوس الدهر منه مهذب ، … تدبيره للملك خير ملاك\nجارى أباه ، بعد ما فات المدى ، … فتلاه بين الفوت والإدراك\nشمس النهار وبدره ونجومه … أبناؤه ، من فرقد وسماك\nيستوضح السارون زهر كواكب … منهم تنير غياهب الأحلاك\nبشراك يا دنيا ، وبشرانا معا ، … هذا الوزير أبو الوليد فتاك\nتلفى السيادة ثم إن أضللتها ، … ومتى فقدت السرو ، فهو هناك\nوإذا سمعت بواحد جمعت له … فرق المحاسن في الأنام ، فذاك\nصمصام بادرة ، وطود سكينة ، … وجواد غايات ، وجذل حكاك\nطلق يفند في السماح ، وجاهل … من يستشف النار بالمحراك\nصنع الضمير ، إذا أجال بمهرق … يمناه ، في مهل ، وفي إيشاك\nنظم البلاغة ، في خلال سطوره ، … نظم اللآلي التوم في الأسلاك\nنادى مساعيه الزمان منافسا ؛ … أحرزت كل فضيلة ، فكفاك\nما الورد ، في مجناه ، سامره الندى … متحليا ، إلا ببعض حلاك\nكلا ولا المسك ، النموم أريجه ، … متعطرا ، إلا بوسم ثناك\nاللهو ذكرك ، لا غناء مرجع ، … يفتن في الإطلاق والإمساك\nطارت إليك بأوليائك هزة ، … تهفو لها أسفا قلوب عداك\nيا أيها القمر ، الذي لسنائه … وسناه تعنو السبع في الأفلاك\nفرح الرياسة ، إذ ملكت عنانها ، … فرح العروس بصحة الإملاك\nمن قال إنك لست أوحد في النهى … والصالحات ، فدان بالإشراك\nقلدني الرأي الجميل ، فإنه … حسبي ليومي زينة وعراك\nوغذا تحدثت الحوادث بالرنا … شزرا إلي ، فقل لها : إياك\nهو في ضمان العزم ، يعبس وجهه … للخطب ، والخلق الندي الضحاك\nوأحم داري ، تضاعف عزه ، … لما أهين بمسحق ومداك\nوالدجن ، للشمس المنيرة ، حاجب ، … والجفن مثوى الصارم الفتاك\nهنأتك صحتك ، التي ، لو أنها … شخص أحاوره ، لقلت هناك\nدامت حياتك ما استدمت فلم تزل … تحيا بك الأخطار بعد هلاك"},{"id":"diwan-zaydun:72","bookId":"diwan-zaydun","type":"poem","seq":72,"chapter":"البحر: طويل","title":"أما في نسيم الريح عرف معرف","page":"","text":"أما في نسيم الريح عرف معرف … لنا هل لذات الوقف بالجزع موقف\nفنقضي أوطار المنى من زيارة ، … لنا كلف منها بما نتكلف\nضمان علينا أن تزار ، ودونها … رقاق الظبى والسمهري المثقف\nغيارى يعدون الغرام جريرة … بها ، والهوى ظلما يغيظ ويؤسف\nيودون لو يثني الوعيد زماعنا ؛ … وهيهات ريح الشوق من ذاك أعصف\nيسير لدى المشتاق ، في جانب الهوى ، … نوى غربة أو مجهل متعسف\nهل الروع إلا غمرة ثم تنجلي ؛ … أم الهول إلا غمة ثم تكشف ؟\nوفي السيراء الرقم ، وسط قبابهم ، … بعيد مناط القرط أحور أوطف\nتباين خلقاه ، فعبل منعم ، … تأود ، في أعلاه ، لدن مهفهف\nفللعانك المرتج ما حاز مئزر ؛ … وللغصن المهتز ما ضم مطرف\nحبيب إليه أن نسر بوصله ، … إذا نحن زرناه ، ونهنا ونسعف\nوليلة وافينا الكثيب لموعد ، … سرى الأيم لم يعلم لمسراه مزحف\nتهادى أناة الحطو ، مرتاعة الحشا ، … كما ريع يعفور الفلا المتشوف\nفما الشمس رق الغيم دون إياتها ، … سوى ما أرى ذاك الجبين المنصف\nفديتك ! أنى زرت نورك واضح ، … وعطرك نمام وحليك مرجف\nهبيك اعتررت الحي ، واشيك هاجع ، … وفرعك غربيب ، وليلك أغضف\nفأنى اعتسفت الهول خطوك مدمج … وردفك رجراج وخصرك مخطف\nلجاج ، تمادي الحب في المعشر العدا ، … وأم الهوى الأفق الذي فيه نشنف\nوأن نتلقى السخط عانين بالرضى … لغيران أجفى ما يرى حين يلطف\nسجايا ، لمن والاه ، كالأرى تجنى ، … فيومىء طرف ، أو بنان مطرف\nخليلي ! مهلا لا تلوما ، فإنني ، … فؤادي أليف البث ، والجسم مدنف\nفأعنف ما يلقى المحب لحاجة … على نفسه في الحب ، حين يعنف\nوإني ليستهويني البرق صبوة ، … إلى برق ثغر إن بدا كاد يخطف\nوما ولعي بالراح إلا توهم … لظلم ، به كالراح ، لو يترشف\nوتذكرني العقد ، المرن جمانه ، … مرنات ورق في ذرى الأيك تهتف\nفما قيل من أهوى طوى البدر هودج … ولا صان ريم القفر خدر مسجف\nولا قبل عباد حوى … ولا حمل الطود المعظم رفرف\nهو الملك الجعد ، الذي في ظلاله … تكف صروف الحادثات وتصرف\nهمام يزين الدهر منه وأهله ؛ … مليك فقيه ، كاتب متفلسف\nيتيه بمرقاه سرير ومنبر ، … ويحمد مسعاه حسام ومصحف\nرويته في الحادث الإد لحظة ؛ … \nيذل له الجبار ، خيفة بأسه ، … ويعنو إليه الأبلج المتغطرف\nحذارك ، إذ تبغي عليه ، من الردى ، … ودونك فاستوف المنى حين تنصف\nستعتامهم في البر و … كتائب تزجى ، أو سفائن تجدف\nأغر ، متى ندرس دواوين مجده … يرقنا غريب مجمل أو مصنف\nإذا نحن قرطناه قصر مطنب ، … ولم يتجاوز غاية القصد مسرف\nوأروع ؛ لا الباغي أخاه مبلغ … مناه ، ولا الراجي نداه مسوف\nممر القوى ، لا يملأ الخطب صدره ، … وليس لأمر فائت يتلهف\nله ظل نعمى ، يذكر الهم عنده … ظلال الصبا ، بل ذاك أندى وأورف\nجحيم لعاصيه ، يشب وقوده ، … وجنة عدن للمطيعين تزلف\nمحاسن ، غرب الذم عنها مفلل … كهام ، وشمل المجد فيها مؤلف\nتناهت ، فعقد المجد منها مفصل … سناء ، وبرد الفخر منها مفوف\nطلاقة وجه ، في مضاء ، كمثل ما … يروق فرند السيف والحد مرهف\nعلى السيف من تلك الشهامة ميسم ، … وفي الروض من تلك الطلاقة زخرف\n … تعود لمن عاداه كالشري ينقف\nيراقب منه الله معتضد ، به … يد الدهر ، يقسو في رضاه ويرأف\nفقل للملوك الحاسديه : متى ادعى … سباق العتيق الفائت الشأو مقرف\nأليس بنو عباد القبلة التي … عليها لآمال البرية معكف ؟\nملوك يرى أحيائهم فخر دهرهم ، … ويخلف موتاهم ثناء مخلف\nبهم باهت الأرض السماء فأوجه … شموس ، وأيد من حيا المزن أوكف\nأشارح معنى المجد وهو معمس … ومجزل حظ الحمد وهو مسفسف\nلعمر العدا المستدرجيك بزعمهم … إلى غرة كادت لها الشمس تكسف\nلكالوك صاع الغدر ، لؤم سجية ، … وكيل لهم صاع الجزاء المطفف\nلقد حاولوا العظمى التي لا شوى لها ، … فأعجلهم عقد من الهم محصف\nولما رأيت الغدر هب نسيمه ، … تلقاه إعصار لبطشك حرجف\nأظن الأعادي أن حزمك نائم ؟ … لقد تعد الفسل الظنون فتخلف\nدواعي نفاق أنذرتك بأنه … سيشرى ويذوي العضو من حيث يشأف\nتحملت عبء الدهر عنهم ، وكلهم … بنعماك موصول التنعم ، مترف\nفإن يكفروا النعمى فتلك ديارهم … بسيفك قاع صفصف الرسم تنسف\nوطي الثرى مثوى يكون قصارهم ، … وإن طال منهم في الأداهم مرسف\nوبشراك عيد بالسرور مظلل ، … وبالحظ ، في نيل المنى ، متكنف\nبشير بأعياد توافيك بعده ، … كما ينسف النظم الموالي ، ويرصف\nتجرد فيه سيف دولتك ، الذي … دماء العدى دأبا بغربيه تظلف\nهو الصارم العضب الذي العزم حده ، … وحليته بذل الندى والتعفف\nهمام سما للملك ، إذ هو يافع ، … وتمت له آياته ، هو مخلف\nكريم ، يعد الحمد أنفس قينة ، … فيولع بالفعل الجميل ، ويشغف\nغدا بخميس ، يقسم الغيم أنه … لأحفل منها ، مكفهرا ، وأكثف\nهو الغيم من زرق الأسنة برقه ، … وللطبل رعد ، في نواحيه ، يقصف\nفلما قضينا ما عنانا أداؤه ، … وكل بما يرضيك داع ، فملحف\nقرنا بحمد الله حمدك ، إنه … لأوكد ما يحظى لديه ، ويزلف\nوعدنا إلى القصر ، الذي هو كعبة ، … يغاديه منا ناظر ، أو مطرف\nفإذ نحن طالعناه ، والأفق لابس … عجاجته ، والأرضب بالخيل ترجف\nرأيناك في أعلى المصلى ، كأنما … تطلع ، من محراب داود ، يوسف\nولما حضرنا الإذن ، والدهر خادم ، … تشير فيمضي ، والقضاء مصرف\nوصلنا فقبلنا الندى منك في يد ، … بها يتلف المال الجسيم ، ويخلف\nلقد جدت حتى ما بنفس خصاصة ، … وأمنت حتى ما بقلب تخوف\nولولاك لم يسهل من الدهر جانب ؛ … ولا ذل مقتاد ، ولا لان معطف\nلك الخير ، أنى لي بشكرك نهضة ؟ … وكيف أودي فرض ما أنت مسلف ؟\nأفدت بهيم الحال مني غرة ، … يقابلها طرف الجموح فيطرف\nوبوأته دنياك دار مقامة ، … بحيث دنا ظل وذلل مقطف\nوكم نعمة ، ألبستها ، سندسية ، … أسربلها في كل حين وألحف\nمواهب فياض اليدين ، كأنما … من المزن تمرى أو من\nفإن أك عبدا قد تملكت رقه ، … فأرفع أحوالي ، وأسنى وأشرف"},{"id":"diwan-zaydun:73","bookId":"diwan-zaydun","type":"poem","seq":73,"chapter":"البحر: مجزوء الكامل","title":"راحت ، فصح بها السقيم ،","page":"","text":"راحت ، فصح بها السقيم ، … ريح معطرة النسيم\nمقبولة هبت قبولا ، … فهي تعبق في الشميم\nأفضيض مسك أم بلنسية … لرياها نميم\nبلد ، حبيب أفقه ، … لفتى يحل به كريم\nأيها أبا عبد الإله ، … دعاء مغلوب العريم\nإن عيل صبري من فراقك … فالعذاب به أليم\nأو أتبعتك حنينها … نفسي ، فأنت لها قسيم\nذكرى لعهدك كالسهاد … سرى ، فبرح بالسليم\nمهما ذممت ، فما زماني … في ذمامك بالذميم\nزمن ، كمألوف الرضاع ، … يشوق ذكراه الفطيم\nأيامض أعقد ناظري … بذلك المرأى الوسيم\nفأرى الفتوة غضة … في ثوب أواه حليم\nألله يعلم أن حب … ك من فؤادي بالصميم\nولئن تحمل عنك لي … جسم ، فعن قلب مقيم\nقل لي : بأي خلال سروك ، … قبل ، أفتن أو أهيم ؟\nأبمجدك العمم ، الذي … نسق الحديث مع القديم ؟\nأم ظرفك الحلو الجنى ؛ … أم عرضك الصافي الأديم ؟\nأم برك العذب الجمام ، … وبشرك الغض الجميم ؟\nأم بالبدائع كاللآلئ ، … من نثير أو نظيم ؟\nوبلاغة ، إن عد أهلوها ، … فأنت لهم زعيم\nفقر تسوغ بها المدام ، … إذا تكررها النديم\nإن أشمست تلك الطلاقة ، … فالندى منها مقيم\nإن الذي قسم الخظوظ ، … حباك بالخلق العظيم\nلا أستزيد الله نعمى … فيك ، لا بل أستديم\nفلقد أقر العين أنك … غرة الزمن البهيم\nحسبي الثناء لحسن بر … ك ما بدا برق فشيم\nثم الدعاء بأن تهنأ ، … طول عيشك ، في نعيم\nثم السلام تبلغنه ، … فغيب مهديه سليم"},{"id":"diwan-zaydun:74","bookId":"diwan-zaydun","type":"poem","seq":74,"chapter":"البحر: طويل","title":"أما علمت أن الشفيع شباب ،","page":"","text":"أما علمت أن الشفيع شباب ، … فيقصر عن لوم المحب عتاب ؟\nعلام الصبا غض ، يرف رواؤه ، … إذا عن من وصل الحسان ذهاب ؟\nوفيم الهوى محض يشف صفاؤه … إذا لم يكن منهن عنه ثوابي ؟\nومسعفة بالوصل ، إذ مربع الحمى … لها ، كلما قظنا الجناب ، جناب\nتظن النوى تعدو الهوى عن مزارها ؛ … وداعي الهوى نحو البعيد مجاب\nوقل لها نضو برى نحضه السرى ، … وبهماء غفل الصحصحان ، تجاب\nإذا ما أحب الركب وجها مضوا له … فهان عليهم أن تخب ركاب\nعروب ألاحت من أعاريب حلة ، … تجاوب فيها بالصهيل عراب\nغيارى من الطيف المعاود في الكرى ، … مشيحون من رجم الظنون غضاب\nوماذا عليها أن يسني وصلها … طعان ، فإن لم يغنينا ، فضراب\nألم تدر أنا لا نراح لربيبة ، … إذا لم يلمع بالنجيع خضاب\nولا ننشق العطر النموم أريجه ، … إذا لم يشعشع بالعجاج ملاب\nوكم راسل الغيران يهدي وعيده ، … فما راعه إلا الطروق جواب\nولم يثننا أن الرباب عقيلة ، … تساند سعد دونها ورباب\nوأن ركزت حول الخدور أسنة ، … وحفت بقب السابحات قباب\nولو نذر الحيان ، غب السرى ، بنا … لكرت عظالى ، أو لعاد كلاب\nوليلة وافتنا تهادى فنمتري ، … أيسمو حباب ، أو يسيب حباب ؟\nيعذبها عض السوار بمعصم ، … أبان لها أن النعيم عذاب\nلأبرحت من شيحان ، حط لثامه ، … إلى خفر ما حط عنه نقاب\nثوى منهما ثنى النجاد مشيع ، … نجيد ، وميلاء الوشاح كعاب\nيعلل من إغريض ثغر ، يعله … غريض كماء المزن ، وهو رضاب\nإلى أن بدت في دهمة الأفق غرة ، … ونفر ، من جنح الظلام ، غراب\nوقد كادت الجوزاء تهوي فخلتها … ثناها ، من الشعرى العبور ، جناب\nكأن الثريا راية مشرع لها … جبان ، يريد الطعن ، ثم يهاب\nكأن سهيلا ، في رباوة أفقه ، … مسيم نجوم ، حان منه إياب\nكأن السها فاني الحشاشة ، شفه … ضنى ، فخفات مرة ومثاب\nكأن الصباح استقبس الشمس نارها ، … فجاء له ، من مشتريه ، شهاب\nكأن إياة الشمس بشر بن جهور ، … إذا بذل الأموال ، وهي رغاب\nهو البشر ، شمنا منه برق غمامة … لها باللها ، في المعتفين ، مصاب\nجواد متى استعجلت أولى هباته … كفاك من\nغني ، عن الإبساس ، در نواله ، … إذا استنزل الدر البكيء عصاب\nإذا حسب النيل الزهيد منيله ، … فما لعطاياه الحساب حساب\nعطايا ، يصيب الحاسدون بحمده … عليها ، ولم يحبوا بها فيحابوا\nموطأ أكناف السماح ، دنت به … خلائق زهر ، إذ أناف نصاب\nفزره تزر أكناف غناء طلة ، … أربت بها للمكرمات رباب\nزعيم المساعي أن تلين شدائد … يمارسها ، أو أن تلين صعاب\nمهيب يغض الطرف منه لآذن ، … مهابته دون الحجاب حجاب\nلأبلج موفور الجلال ، إذا احتبى ، … علا نظر منه وعز خطاب\nوذي تدرإ ، يعدو العدا عن قرعه ، … غلاب ، فمهما عزه ، فخلاب\nإذا هو أمضى العزم لم يك هفوة ، … يؤثر عنها ، في الأنامل ، ناب\nعزائم ينصاع العدا عن ممرها ، … كما رهبت يوم النضال رهاب\nصوائب ، ريش النصر في جنباتها … لؤام ، وريش الطائشات لغاب\nحليم ، تلافى الجاهلين أناته ، … إذ الحلم عن بعض الذنوب عقاب\nإذا عثر الجاني عفا عفو حافظ ، … بنعمى لها في المذنبين ذناب\nشهامة نفس في سلامة مذهب ، … كما الماء للراح الشمول قطاب\nبني جهور ! مهما فخرتم بأول ، … فسر من المجد التليد لباب\nحططتم بحيث اسلنطحت ساحة العلا ، … وأوفت لأخطار السناء هضاب\nبكم باهت الأرض السماء ، فأوجه … شموس ، وأيد ، في المحول ، سحاب\nأشارح معنى المجد وهو معمس ، … وعامر مغنى الحمد وهو خراب\nمحياك بدر ، والبدور أهلة ، … ويمناك بحر ، والبحور ثعاب\nرأيتك جاراك الورى ، فغلبتهم ، … لذلك جري المذكيات غلاب\nفقرت بها ، من أوليائك ، أعين … وذلت لها ، من حاسديك ، رقاب\nفتحت المنى ، من بعد إلهامنا بها ، … وقد ضاع إقليد وأبهم باب\nمددت ظلال الأمن ، تخضر تحتها ، … من العيش في أعذى البقاعن شعاب\nحمى ، سالمت فيه البغاث جوارح ، … وكفت ، عن البهم الرتاع ، ذئاب\nفلا زلت تسعى سعي من حظ سعيه … نجاح ، وحظ الشانئيه تباب\nفإنك للدين الشعيب لملأم ؛ … وإنك للملك الثئي لرئاب\nإذا معشر ألهاهم جلساؤهم ، … فلهوك ذكر ، والجليس كتاب\nنعزيك عن شهر الصيام الذي انقضى ، … فإنك مفجوع به فمصاب\nهو الزور لو تعطى المنى وضع العصا … ليزداد ، من حسن الثواب ، مثاب\nشهدت ، لأدى منك واجب فرضه … عليم بما يرضي الإله ، نقاب\nوجاورت بيت الله أنسا بمعشر ، … خشوه ، فخروا ركعا وأنابوا\nلقد جد إخبات ، وحق تبتل ، … وبالغ إخلاص ، وصح متاب\nسيخلد في الدنيا به لك مفخر ، … ويحسن في دار الخلود مآب\nوبشراك أعياد ، سينمي اطرادها ، … كما اطردت في السمهري كعاب\nترى منك سرو الملك في قشف التقى … فيبرقها مرأى هنك عجاب\nفأبل وأخلف ، إنما أنت لابس … لهذي الليالي الغر ، وهي ثياب\nفديتك كم ألقى الفواغر من عدا ، … قراهم ، لنيران الفساد ، ثقاب\nعفا عنهم قدري الرفيع ، فأهجروا ، … وباينهم خلقي الجميل ، فعابوا\nوقد تسمع الليث اجحاش نهيقها ، … وتعلي إلى البدر النباح كلاب\nإذا راق حسن الروض أو فاح طيبه … فما ضره أن طن فيه ذباب\nفلا برحت تلك الضغائن ، إنها … أفاع ، لها ، بين الضلوع ، لصاب\nيقولون شرق ، أو فغرب صريمة … إلى حيث آمال النفوس نهاب\nفأنت الحسام العضب أصدئ متنه … وعطل منه مضرب وذباب\nوما السيف مما يستبان مضاؤه ، … إذا حاز جفن حده ، وقراب\nوإن الذي أملت كدر صفوه ، … فأضحى الرضا بالسخط منه يشاب\nوقد أخلفت مما ظننت مخايل ؛ … وقد صفرت مما رجوت وطاب\nفمن لي بسلطان مبين عليهم ، … إذا لج بالخصم الألد شغاب\nليخزهم إن لم تردني نبوة ، … يساء الفتى من مثلها ويراب\nفقد تتغشى صفحة الماء كدرة ، … ويغطو على ضوء النهار ضباب\nسرور الغنى ، ما لم يكن منك ، حسرة ، … وأري المنى ، ما لم تنل بك ، صاب\nوإن يك في أهل الزمان مؤمل ، … فأنت الشراب العذب ، وهو سراب\nأيعور ، من جار السماكين ، جانب ، … ويمعز ، في ظل الربيع ، جناب ؟\nفأين ثناء يهرم الدهر كبرة ، … وحليته ، في الغابرين ، شباب ؟\nسأبكي على حظي لديك ، كما بكى … ربيعة لما ضل عنه دؤاب\nوأشكو نبو الجنب عن كل مضجع ، … كما يتجافى بالأسير ظراب\nفثق بهزبر الشعر واصفح عن الورى ، … فإنهم ، إلا الأقل ، ذباب\nولا تعدل المثنينبي ، فأنا الذي … إذا حضر العقم الشوارد غابوا\nينوب عن المداح مني واحد ، … جميع الخصال ، ليس عنه مناب\nوردت معين الطبع ، إذ ذيد دونه … أناس ، لهم في حجرتيه لواب\nونجدني علم توالت فنونه ، … كما يتوالى في النظام سخاب\nفعد بيد بيضاء يصدع صدقها ، … فإن أراجيف العداة كذاب\nوحاشاك من أن تستمر مريرة ، … لعهدك ، أو يخفى عليك صواب"},{"id":"diwan-zaydun:75","bookId":"diwan-zaydun","type":"poem","seq":75,"chapter":"البحر: خفيف تام","title":"الهوى في طلوع تلك النجوم ؛","page":"","text":"الهوى في طلوع تلك النجوم ؛ … والمنى في هبوب ذاك النسيم\nسرنا عيشنا الرقيق الحواشي ، … لو يدوم السرور للمستديم\nوطر ما انقضى إلى أن تقضى … زمن ، ما ذمامه بالذميم\nإذ ختام الرضا المسوغ مسك ؛ … ومزاج الوصال من تسنيم\nوغريض اللال غض ، جنى الصبوة ، … نشوان من سلاف النعيم\nطالما نافر الهوى منه غر ، … لم يطل عهد جيده بالتميم\nأيها المؤذني بظلم الليالي ، … ليس يومي بواحد من ظلوم\nقمر الأفق ، إن تأملت ، والشمس … هما يكسفان دون النجوم\nأيها ذا الوزير ! ها أنا أشكو ، … بالمصاب العظيم نحو العظيم\nبوأ الله جهورا شرف السؤدد ، … في السرو ، واللباب الصميم\nواحد ، سلم الجميع له الأمر ، … فكان الخصوص وفق العموم\nقلد الغمر ذا التجارب فيه ؛ … واكتفى جاهل بعلم العليم\nخطر يقتضي الكمال بنوعي … خلق بارع ، وخلق وسيم\nأيها الوزير ! ها أنا أشكو ، … والعصا بدء قرعها للحليم\nما عنانا أن يأنف السابق المربط … في العتق منه والتطهيم\nوبقاء الحسام في الجفن يثني … منه بعد المضاء ، والتصميم\nأفصبر مئين خمسا من الأيام ، … ناهيك من عذاب أليم !\nومعنى من الضنى بهنات ، … نكأت بالكلوم قرح الكلوم\nسقم لا أعاد فيه وفي العائد … أنس يفي ببرء السقيم\nنار بغي سرى إلى جنة الأمن … لظاها ، فأصبحت كالصريم\nبأبي أنت ، إن تشأ ، تك بردا … وسلاما ، كنار إبراهيم\nللشفيع الثناء ، والحمد في صوب … الحيا للرياح ، لا للغيوم\nوزعيم ، بأن يذلل لي الصعب ، … مثابي إلى الهمام الزعيم\nووداد ، يغير الدهر ما شاء … ويبقى بقاء عهد الكريم\nوثناء ، أرسلته سلوة الظاعن … عن شوقه ، ولهو المقيم\nفهو ريحانة الجليس ، ولا فخر ، … وفيه مزاج كأس النديم\nلم يزل مغضيا على هفوة الجاني ، … مصيخا إلى اعتذار الكريم\nومتى يبدإ الصنيعة يولعك … تمام الخصال بالتتميم"},{"id":"diwan-zaydun:76","bookId":"diwan-zaydun","type":"poem","seq":76,"chapter":"البحر: رمل تام","title":"هل عهدنا الشمس يعتاد الكلل ؛","page":"","text":"هل عهدنا الشمس يعتاد الكلل ؛ … أم شهدنا البدر يجتاب الحلل\nأم قضيب البان ، يعنيه الهوى ، … أم غزال الفقر ، يصبه الغزل ؟\nخرق العادات مبدي صورة ، … حشد الحسن عليها ، فاحتفل\nمشرب الصفحة من ماء الصبا ؛ … مشبع الوجنة من صبغ الخجل\nمن عذيري منه ، إن أغببته … نسي العهد ، وإن عاودت مل\nقاتل لي بالتجني ، ما له ، … ليت شعري ، أحلال ما استحل ؟\nأيها المختال في زينته ! … أنت أولى الناس بالخال ، فخل\nلك ، إن أدللت ، عذر واضح ؛ … كل من ساعفه الحسن أدل\nسبب السقم ، الذي برح بي ، … صحة كالسقم في تلك المقل\nإن من أضحى أباه جهور ، … قالت الآمال عنه ، ففعل\nملك لذ جنى العيش به ، … حيث ورد الأمن للصادي علل\nأحسن المحسن منا فجزى ، … مثلما لج مسيء ، فاحتمل\nسعيه في كل بر مثل ، … إذ مساعي من يناويه مثل\nلا يزل من حاسديه مكثر ، … أو مقل ، سبق السيف العذل\nيا بني جهور الدنيا بكم … حليت أيامها ، بعد العطل\nإنما دولتكم واسطة ، … أهدت الحسن إلى عقد الدول\nنحن من نعمائكم في زهرة ، … جددت عهد الربيع المقتبل\nطاب كانون لنا أثناءها ؛ … فكأن اللشمس حلت بالحمل\nزهرت أخلاقكم ، فابتسمت … كابتسام الورد عن لؤلؤ طل\nأيها … بالندى يمناه ، ف\nمن لنا فيك بعيب واحد ، … تحذر العين ، إذا الفضل كمل\nشرف تغنى عن المدح به ، … مثلما يغنى عن الكحل الكحل\nأنا غرس في ثرى العلياء ، لو … أبطأت سقياك عنه لذبل\nلي ذكر ، بالذي أسديته ، … نابه ، ود حسود لو خمل\nفليمت بالداء من حال فتى … أدبته سير الناس الأول\nفوعى الحكمة عن قائلهم : … الزم الصحة يلزمك العمل\nأقبلت نعماك تهدي نفسها ، … لم أرغ حظي منها بالحيل\nفقبلت اليد من بطن يد … ظهرها ، الدهر ، محل للقبل\nكلنا بلغ ما أمله … فابلغ الغاية من كل أمل\nوإذا ما رامك الدهر ، ففت ؛ … وإذا رمت الأماني ، فنل"},{"id":"diwan-zaydun:77","bookId":"diwan-zaydun","type":"poem","seq":77,"chapter":"البحر: كامل تام","title":"هذا الصباح ، على سراك ، رقيبا ،","page":"","text":"هذا الصباح ، على سراك ، رقيبا ، … فصلي بفرعك ليلك الغربيبا\nولديك ، أمثال النجوم ، قلائد ، … ألفت سماءك لبة وتريبا\nلينب عن الجوزاء قرطك كلما … جنحت ، تحث جناحها تغريبا\nوإذا الوشاح تعرضت أثناؤه ، … طلعت ثريا لم تكن لتغيبا\nولطالما أبديت ، إذ حييتنا ، … كفا ، هي الكف الخضيب ، خضيبا\nأظنينة ! دعوى البراءة شأنها ، … أنت العدو ، فلم دعيت حبيبا ؟\nما بال خدك لا يزال مضرجا … بدم ، ولحظك لا يزال مريبا ؟\nلو شئت ، ما عذبت مهجة عاشق … مستعذب ، في حبك ، التعذيبا\nولزرته ، بل عدته ، إن الهوى … مرض ، يكون له الوصال طبيبا\nما الهجر إلا البين ، لولا أنه … لم يشح فاه به الغراب نعيبا\nولقد قضى فيك التجلد نحبه ، … فثوى وأعقب زفرة ونحيبا\nوأرى دموع العين ليس لفيضها … غيض ، إذا ما القلب كان قليبا\nما لي وللأيام ، لج مع الصبا … عدوانها ، فكسا العذار مشيبا\nمحقت هلال السن ، قبل تمامه ؛ … وذوى بها غصن الشباب رطيبا\nلألم بي ما لو ألم بشاهق ، … لانهال جانبه ، فصار كثيبا\nفلئن تسمني الحادثات ، فقد أرى … للجفن ، في العضب الطرير ، ندوبا\nولئن عجبت لأن أضام ، وجهور … نعم النصير ، لقد رأيت عجيبا\nمن لا تعدي النائبات لجاره … زحفا ، ولا تمشي الضراء دبيبا\nملك أطاع الله منه موفق ؛ … ما زال أوابا إليه منيبا\nيأتي رضاه معاديا ومواليا ، … ويكون فيه معاقبا ومثيبا\nمتمرس بالدهر ، يقعد صرفه … إن قام ، في نادي الخطوب ، خطيبا\nلا يوسم الرأي الفطير به ، ولا … يعتاد إرسال الكلام قضيبا\nتأبى ضرائبه الضروب نفاسة … من ان تقيس به النفوس ضريبا\nبسام ثغر البشر ، إن عقد الحبا ، … فرأيت وضاحا ، هناك ، مهيبا\nملأ النواظر صامتا ، ولربما … ملأ المسامع سائلا ومجيبا\nعقد ، تألف في نظام رياسة ، … نسق اللآلىء منجبا ونجيبا\nيغشى التجارب كهلهم ، مستغنيا … بقريحة ، هي حسبه تجريبا\nوإذا دعوت وليدهم لعظيمة ، … لباك رقراق السماح ، أديبا\nهمم تنافسها النجوم ، وقد تلا ، … في سؤدد منها ، العقيب عقيبا\nومحاسن تندى رقائق ذكرها ، … فتكاد توهمك المديح نسيبا\nكالآس أخضر نضرة ، والورد أحمر … بهجة ، والمسك أذفر طيبا\nوإذا تفنن ، في اللسان ، ثناؤه ، … فافتن ، لم يكن المراد غريبا\nغالى بما فيه ، فغير مواقع … سرفا ، ولا متوقع تكذيبا\nكان الوشاة ، وقد منيت بإفكهم ، … أسباط يعقوب ، وكنت الذيبا\nوإذا المنى ، بقبولك الغض الجنى ، … هزت ذوائبها ، فلا تثريبا\nأنا سيفك الصدىء الذي مهما تشأ … تعد الصقال إليه والتذ ريبا\nكم ضاق بي من مذهب في مطلب ، … فثنيته فسح المجال ، رحيبا\nوزها جناب الشكر حين مطرته … بسحائب النعمى ، فرد خصيبا"},{"id":"diwan-zaydun:78","bookId":"diwan-zaydun","type":"poem","seq":78,"chapter":"البحر: مجزوء الرمل","title":"سرك الدهر وساء ،","page":"","text":"سرك الدهر وساء ، … فاقن شكرا وعزاء\nكم أفاد الصبر أجرا ، … واقتضى الشكر نماء\nأنت إن تأس على … المفقود إلفا ، واجتباء\nفاسل عنه غيرة ، … واحتمل الرزء إباء\nأيها المعتضد ، المنصور ، … مليت البقاء\nوتزيدت مع الأيام … عزا ، وعلاء\nإنما يكسبنا الحزن … عناء ، لا غناء\nأنت طب أن داء المو … ت قد أعيا الدواء\nفتأس ! إن ذاك … الخطب غال الأنبياء\nوسيفنى الملأ الأع … لى إذا ما الله شاء\nحبذا هدي عروس ، … دفنها كان الهداء\nعمرت حينا ، وماء ال … مزن شكلين سواء\nثم ولت ، فوجدنا … أرج المسك ثناء\nجمعت تقوى وإخبا … تا وفضلا وذكاء\nستوفى ، من جمام الكو … ثر العذب ، رواء\nحيث تلقى الأتقياء ، الس … عداء ، الشهداء\nهان ما لاقت عليها ، … أن غدت منك فداء\nغنم أحبابك أن تب … قى ، وإن عموا فناء\nفالبس الصنع ملاء ؛ … واسحب السعد رداء\nورث الأعداء أعما … رهم ، والأولياء"},{"id":"diwan-zaydun:79","bookId":"diwan-zaydun","type":"poem","seq":79,"chapter":"البحر: مجزوء الكامل","title":"أحمدت عاقبة الدواء ،","page":"","text":"أحمدت عاقبة الدواء ، … ونلت عافية الشفاء\nوخرجت منه مثلما … خرج الحسام من الجلاء\nوبقيت الدنيا ، فأن … ت دواؤها من كل داء\nوورثت أعمار العدى ، … وقسمتها في الأولياء\nيا خير من ركب الجيا … د ، وسار في ظل اللواء\nواجتال يوم الحرب قد … ما ، واحتبى يوم الحباء\nبشراك عقبى صحة ، … تجري إلى غير انتهاء\nفي دولة تبقى بقا … ء الدهر ، آمنة الفناء\nومسرة يفضي بها … زمن ، كحاشية الرداء\nواشرب فقد لذ النسيم ، … ورق سربال الهواء\nلنرى بك البهو المطل ، … يميس في حلل البهاء\nوبقيت مفديا بنا ؛ … إن نحن جزنا في الفداء"},{"id":"diwan-zaydun:80","bookId":"diwan-zaydun","type":"poem","seq":80,"chapter":"البحر: طويل","title":"ليهنك أن أحمدت عاقبة الفصد ؛","page":"","text":"ليهنك أن أحمدت عاقبة الفصد ؛ … فلله منا أجمل الشكر والحمد\nويا عجبا من أن مبضع فاصد … تلقيته ، لم ينصرف نابي الحد\nومن متولي فصد يمناك ، كيف لم … يهله عباب\nولم تغشه الشمس المنير شعاعها ، … فيخطئ فيما رامه سنن القصد\nسرى دمك المهراق في الأرض فاكتست … أفانين روض مثل حاشية البرد\nفصاد أطاب الدهر كالقطر في الثرى … كما طاب ماء الورد في العنبر الورد\nلقد أوفت الدنيا بعهدك نصرة ؛ … كأنك قد علمتها كرم العهد\nلدى زمن غض ، أنيق فرنده ، … كمثل فرند الورد في خجلة الخد\nتسوغ منه العيش في ظل دولة … مقابلة الأرجاء بالكوكب السعد\nفهب إلى اللذات ، مؤثر راحة ، … تجم النفس النفيسة للكد\nووال بها في لؤلؤ ، من حبابها ، … كجيد الفتاة الرود في لؤلؤ العقد\nوإن تدعنا للأنس ، عن أريحية ، … فقد يأنس المولى ، إذا ارتاح ، بالعبد"},{"id":"diwan-zaydun:81","bookId":"diwan-zaydun","type":"poem","seq":81,"chapter":"البحر: متقارب تام","title":"أدرها ! فقد حسن المجلس ، ؛","page":"","text":"أدرها ! فقد حسن المجلس ، ؛ … وقد آن أن تترع الأكؤس\nولا بأس ، إن كان ولى الربيع ، … إذا لم تجد فقده الأنفس\nفإن خلال أبي عامر ، … بها يحضر الورد والنرجس"},{"id":"diwan-zaydun:82","bookId":"diwan-zaydun","type":"poem","seq":82,"chapter":"البحر: كامل تام","title":"ما طول عذلك للمحب بنافع ؛","page":"","text":"ما طول عذلك للمحب بنافع ؛ … ذهب الفؤاد ، فليس فيه براجع\nفندت حين طمعت في سلوانه ؛ … هيهات لا ظفر هناك لطامع\nفدعيه ، حيث يطول ميدان الصبا ، … كيما يجر به عنان الخالع\nماذا يريبك من فتى ، عز الهوى … فعنا لنخوته بذلة خاضع\nهل غير أن محض الوفاء لغادر ؛ … أو غير أن صدق الوصال لقاطع ؟\nلم يهو من لم يمس قرة عينه … سهر الصبابة ، في خلي هاجع\nواها لأيام خلت ، ما عهدها ، … في حين ضيعت العهود ، بضائع\nزمن كما راق السقيط من الندى ، … يستن في صفحات ورد يانع\nأيام إن عتب الحبيب ، لهفوة ، … شفع الشباب ، فكان أكرم شافع\nما لي وللدنيا ، غررت ، من المنى … فيها ، ببارقة السراب الخادع\nما إن أزال أروم شهدة عاسل ، … أحمى مجاجتها بإبرة لاسع\nمن مبلغ عني البلاد ، إذا نبت ، … أن لست للنفس الألوف بناخع\nأما الهوان ، فصنت عنه صفحة … أغشى بها حد الزمان الشارع\nفليرغم الحظ المولي أنه … ولى ، فلم أتبعه خطوة تابع\nإن الغني لهو القناعة ، لا الذي … يشتف نطفة ماء وجه القانع\nألله جار الجهوري ، فطالما … منيت صفاة الدهر منه بقارع\nملك درى أن المساعي سمعة ، … فسعى ، فطاب حديثه للسامع\nشيم هي الزهر الجني ، تبسمت … عنه الكمائم ، في الضحاء الماتع\nأغرى منافسه ليدرك شأوه ، … فشآه بالباع الطويل الواسع\nثبت السكينة في الندي ، كأنما … تلك الحبا ليثت بهضب متالع\nعذب الجنى للأولياء ، فإن يهج … فالسم يأبى أن يسوغ لجارع\nيا أيها الملك الذي حاط الهدى ، … لولاك كان حمى قليل المانع\nأنس الأنام إليك فيه ، فهم به … من قائم ، أو ساجد ، أو راكع\nمتبوئون جناب عيش مونق ؛ … متفيئون ظلال أمن شائع\nفلتضربن معهم بأوفر شركة … في أجرهم ، من موتر أو شافع\nخير الشهور اخترت ، عند طلوعه ، … خير البقاع له بأسعد طالع"},{"id":"diwan-zaydun:83","bookId":"diwan-zaydun","type":"poem","seq":83,"chapter":"البحر: خفيف تام","title":"غمرتني لك الأيادي البيض ،","page":"","text":"غمرتني لك الأيادي البيض ، … نشب وافر وجاه عريض\nكل يوم يجد منك اهتبال ، … عهد شكري عليه غض غريض\nبوأتني نعماك جنة عدن ، … جال في وصفها ، فضل القريض\nمجتنى مدن ، وظل برود ، … ونسيم ، يشفي النفوس ، مريض\nومياه ، قد أخجل الورد أن عا … رض تذهيبه لها تفضيض\nكلما غنت الحمائم قلنا : … معبد ، إذ شدا ، أجاب الغريض\nجاورت حمة ، مشيدة المب … نى لبرق الرخام فيه وميض\nمرمر ، أوقد الفرند عليه … سلسل ، بحره الزلال يفيض\nوسطها دمية يروق اجتلاء ال … كل منها ، ويفتن التبعيض\nبشر ناصع ، وخد أسيل ، … ومحيا طلق ، وطرف غضيض\nوقوام كما استقام قضيب ال … بان ، إذ عله ثراه الأريض\nوابتسام ، لو أنها استغربت في … ه أراك اتساقه الإغريض\nوالتفات ، كأنما هو بالإي … حاء ، من فرط لطفه ، تعريض\nلمع طلة من العيش ما إن … للهوى ، عن محلها تعويض\nسو غتني نعيمها نفحات ، … للمنى ، من سحابها ، ترويض\nتابعتها يد الهمام ، أبي عم … ر و، فما غمرها لدي مغيض\nملك ذاد عن حمى الدين منه … من إليه ، في نصره ، التفويض\nوسما ناظر من المجد ، في دنيا … ه ، قد كان كفه التغميض\nإن أساء الزمان أحسن دأبا ، … مثلما باين النقيض النقيض\nيا معز الهدى ، الذي ما لمسعا … ه ، إلى غير سمته ، تغريض\nيا محلي يفاع حال ، مكان الن … جم ، مهما يقس إليه ، حضيض\nإن أنل أيسر الرغائب فيه ، … يرض فوز القداح مني مفيض\nلو يفاع المجرة اعتضت منه ، … راح يدعو ثبوره المستعيض\nحظ سن امرىء نأى منك قرع ؛ … وقصارى بناته تعضيض\nحسبي النصح والوداد وشكر ، … عطر الدهر منه ، مسك فضيض\nدم موقى وليك ، الدهر ، مجبو … ر مساعيك ، والعدو مهيض\nفاعتراف الملوك أنك مولا … هم حديث ، ما بينهم ، مستفيض"},{"id":"diwan-zaydun:84","bookId":"diwan-zaydun","type":"poem","seq":84,"chapter":"البحر: رجز تام","title":"أما وألحاظ مراض ، صحاح ،","page":"","text":"أما وألحاظ مراض ، صحاح ، … تصبي ، وأعطاف نشاوى ، صواح\nلفاتن بالحسن ، في خده … ورد ، وأثناء ثناياه راح\nلم أنس ، إذ باتت يدي ، ليلة ، … وشاحه اللاصق دون الوشاح\nألممت بالألطف منه ، ولم … أجنح إلى ما فيه بعض الجناح\nلأصفين المصطفى ، جهورا ، … عهدا ، لروض الحسن عنه انتضاح\nجزاء ما رفه شرب المنى ؛ … وأذن السعي بوشك النجاح\nيسرت آمالي بتأميله ، … فما عداني منه فوز القداح\nلم أشم البرق جهاما ، ولم … أقتدح الصم ببيض الصفاح\nمن مثله ، لا مثل يلفى له ، … إن فسدت حال ، فعز الصلاح\nيا مرشدي ، جهلا ، إلى غيره ، … أغنى ، عن المصباح ، ضوء الصباح\nيهفو به ، نحو الثنا ، ارتياح … يهفو به ، نحو الثناء ، ارتياح\nذو باطن أقبس نور التقى ؛ … وظاهر أشرب ماء السماح\nانظر تر البدر سنا ، واختبر … تجده كالمسك ، إذا ميث فاح\nإيه أبا الحزم ! اهتبل غرة ، … ألسنة الشكر عليها فصاح\nلا طار بي حظ إلى غاية ، … إن لم أكن منك مريش الجناح\nعتباك ، بعد العتب ، أمنية … ما لي ، على الدهر ، سواها اقتراح\nلم يثني ، عن أمل ، ما جرى ، … قد يرقع الخرق وتؤسى الجراح\nفاشحذ ، بحسن الرأي ، عزمي يرع … مني العدا ، أليس شاكي السلاح ؟\nواشفع ، فللشافع نعمى بما … سناه من عقد ، وثيق النواح\nإن سحاب الأفق منها الحيا ؛ … والحمد في تأليفها للرياح\nوقاك ، ما تخشى من الدهر ، من … تعبت ، في تأمينه ، واستراح"},{"id":"diwan-zaydun:85","bookId":"diwan-zaydun","type":"poem","seq":85,"chapter":"البحر: بسيط تام","title":"ما جال بعدك لحظي في سنا القمر ،","page":"","text":"ما جال بعدك لحظي في سنا القمر ، … إلا ذكرتك ذكر العين بالأثر\nولا استطلت ذماء الليل من أسف … إلا على ليلة سرت مع القصر\nناهيك من سهر برح تألفه … شوق إلى ما انقضى من ذلك السمر\nفليت ذاك السواد الجون متصل ، … لو استعار سواد القلب والبصر\nأما الضنى فجنته لحظة عنن … كأنها والردى جاءا على قدر\nفهمت معنى الهوى من وحي طرفك لي … إن الحوار لمفهوم من الحور\nوالصدر ، مذ وردت رفها نواحيه ، … توم القلائد لم تجنح إلى صدر\nحسن أفانين ، لم تستوف أعيننا … غاياته بأفانين من النظر\nواها لثغرك ثغرا بات يكلؤه … غيران ، تسري عواليه إلى الثغر\nيقظان لم يكتحل غمضا مراقبة … لرابط الجأش مقدام على الغرر\nلا لهو أيامه الخالي بمرتجع … ولا نعيم لياليه بمنتظر\nإذ لا التحي ة إيماء مخالسة ؛ … ولا الزيارة إلمام على خطر\nمنى ، كأن لم يكن إلا تذكرها ؛ … إن الغرام لمعتاد مع الذكر\nمن يسأل الناس عن حالي فشاهدها … محض العيان الذي يغني عن الخبر\nلم تطو برد شبابي كبرة وأرى … برق المشيب اعتلى في عارض الشعر\nقبل الثلاثين إذ عهد الصبا كثب … وللشبيبة غصن غير مهتصر\nها إنها لوعة في الصدر قادحة … نار الأسى ، ومشيبي طائر الشرر\nلا يهنىء الشامت ، المرتاح خاطره ، … أني معنى الأماني ضائع الخطر\nهل الرياح بنجم الأرض عاصفة ؟ … أم الكسوف لغير الشمس والقمر ؟\nإن طال في السجن إيداعي فلا عجب ! … قد يودع الجفن حد الصارم الذكر\nوإن يثبت أبا الحزم الرضا قدر … عن كشف ضري فلا عتب على القدر\nما للذنوب ، التي جاني كبائرها … غيري يحملني أوزارها وزري\nمن لم أزل ، من تأنيه ، عى ثقة ؛ … ولم أزل من تجنيه على حذر\nذو الشيمة الرسل إن هيجت حفيظته … والجانب السهل والمستعتب اليسر\nمن فيه للمجتلي والمبتلي ، نسقا ، … جمال مرأى عليه سرو مختبر\nمذلل للمساعي حكمها شطط … عليه ، وهو العزيز النفس والنفر\nوزير سلم كفاه يمن طائره … شؤم الحروب ، ورأي محصد المرر\nأغنت قريحته مغنى تجاربه ؛ … ونابت اللمحة العجلى عن الفكر\nكم اشترى ، بكرى عينيه ، من سهر ؛ … هدوء عين الهدى في ذلك السهر\nفي حضرة غاب صرف الدهر - خشيته - … عنها ، ونام القطا فيها ، فلم يثر\nممتع بالربيع الطلق نازلها … يلهيه عن طيب آصال ندى بكر\nما إن يزال يبث النبت في جلد … مذ ساسها ، ويفيض الماء من حجر\nقد كنت أحسبني والنجم في قرن … ففيم أصبحت منحطا إلى العفر ؟\nأحين رف على الآفاق من أدبي … غرس له من جناه يانع الثمر\nوسيلة سببا إن لم تكن نسبا … فهو الوداد صفا من غير ما كدر\nوبائن من ثناء ، حسنه مثل … وشي المحاسن منه معلم الطرر\nيستودع الصحف لا تخفى نوافحه … إلا خفاء نسيم المسك في الصرر\nمن كل مختالة بالحبر رافلة … فيه اختيال الكعاب الرؤد بالحبر\nتجفى لها الروضة الغناء ، أضحكها … مجال دمع الندى في أعين الزهر\nيا بهجة الدهر حيا وهو إن فنيت … حياته زينة الآثار والسير\nلي في اعتمادك ، بالتأميل ، سابقة … وهجرة في الهوى ، أولى من الهجر\nففيم غضت همومي من علا هممي ، … وحاص بي مطلبي عن وجهة الظفر\nهل من سبيل ، فماء العتب لي أسن ، … إلى العذوبة من عتباك والخصر\nنذرت شكرك ، لا أنسى الوفاء به ، … إن اسفرت لي عنها أوجه البشر\nلا تله عني ، فلم أسألك ، معتسفا ، … رد الصبا ، بعد إيفاء على الكبر\nواستوفر الحظ من نصح وصاغية … كلاهما العلق لم يوهب ولم يعر\nهبني جهلت فكان الجهل سيئة … لا عذر منها سوى أني من البشر\nإن السيادة بالإغضاء لابسة … بهاءها ، وبهاء الحسن في الخفر\nلك الشفاعة لا تثنى أعنتها … دون القبول بمقبول من العذر"},{"id":"diwan-zaydun:86","bookId":"diwan-zaydun","type":"poem","seq":86,"chapter":"البحر: مجزوء الكامل","title":"يا أيها الملك الجلي","page":"","text":"يا أيها الملك الجلي … ل ، يكل ألسننا جلالك\nانظر إلى محتلنا ، … قد زان ساحته احتلالك\nنهر وروض ، نحن بينه … ما تفيئنا ظلالك\nقد فاض في هذا ندا … ك ، ونعمت هذا خلالك"},{"id":"diwan-zaydun:87","bookId":"diwan-zaydun","type":"poem","seq":87,"chapter":"البحر: طويل","title":"مرادهم حيث السلاح خمائل ؛","page":"","text":"مرادهم حيث السلاح خمائل ؛ … وموردهم حيث الدماء مناهل\nودون المنى فيهم جياد صوافن ، … ومأثورة بيض وسمر عوامل\nلكل نجيد في النجاد ، كأنما … تناط ، بمتن الرمح ، منه ، الحمائل\nطويل علينا ليله ، من حفيظة ، … كأن صبابات النفوس طوائل\nكناس دنا منه الشرى ، في محلة … بها لليث يعدو ، والغزال يغازل\nلعمر القباب الحمر ، وسط عرينهم … لقد قصرت فيها السروب العقائل\nأمحجوبة ليلى ، ولم تخضب القنا ؛ … ولا حجبت شمس الضحا القساطل\nأناة ، عليها من سنا البدر ميسم ، … وفيها من الغصن النضير شمائل\nيجول وشاحاها على خيزرانة ؛ … وتشرق تحت البردتين الخلاخل\nوليلة وافتنا الكثيب لموعد ؛ … كما ريع وسنان العشيات خاذل\nتهادى انسياب الأيم ، يعفو إثارها ، … من الوشي ، مرقوم العطعافين ذائل\nقعيدك أنى زرت ، ضوءك ساطع ، … وطيبك نفاح ، وحليك هادل\nهبيك اغتررت الحي واشيك هاجع ، … وفرعك غربيب ، وليلك لائل\nفأنى اعتسفت الهول خطوك مدمج … وردفك رجراج وعطفك مائل\nخليلي ! ما لي كلما رمت سلوة ، … تعرض شوق ، دون ذلك حائل ؟\nأراح إذا راح النسيم شآميا ؛ … كأن شمولا ما تدير الشمائل\nضلالا ، تمادى الحب في المعشر العدا ؛ … ولج الهوى في حيث تخشى الغوائل\nكأن ليس ، في نعمى الهمام محمد ، … مسل ، وفي مثنى أياديه شاغل\nأغر ، إذا شمنا سحائب جوده ، … تهلل وجه ، واستهلت أنامل\nيبشرنا بالنائل الغمر وجهه ؛ … وقبل الحيا ما تستطير المخايل\nلديه رياض ، للسجايا ، أنيقة ، … تغلغل فيها ، للعطايا ، جداول\nأتي ، فما تلك السماحة نهزة ؛ … وفي ن فما تلك الحبال حبائل\nزعيم الدهاء أن تصيب ، من العدا ، … مكايده ما لا تصيب الجحافل\nفما سيف ذاك العزم فيهم بمعضد ؛ … ولا سهم ذاك الرأي أفوق ناصل\nبنى جهور عشتم بأوفر غبطة ؛ … فلولاكم ما كان في العيش طائل\nتفاضل في السرو الملوك ، فخلتهم … أنابيب رمح ، أنتم فيه عامل\nلئن قل في أهل الزمان عديدكم … فإن دراري ، النجوم قلائل\nفداؤكم من ، إن تعده ظنونه … لحاقكم في المجد ، فالدهر ماطل\nمناكيد ، فعل الخير منهم تكلف ، … إذ الشر طبع ، ما لهم عنه ناقل\nفإن سترت أخلاقهم بتخلق ، … فكل خضيب لا محالة ناصل\nلك الخير ، إني قائل غير مقصر ؛ … فمن لي باستيفاء ما أنت فاعل\nلعمر سراة الثغر ، وافاك وفدهم ، … لما ذم منهم ذلك النزل نازل\nلأعذرت ، لما لم يملك مكثهم ، … إذا عذر المستثقل المتثاقل\nنضدت رياحين الطلاقة غضة ؛ … ورقرقت ماء البر ، وهو سلاسل\nفما منهم إلا شديد نزاعه ، … إليك ، مقيم القلب والجسم راحل\nضمان عليهم أن سيؤثر عنهم … عليك ثناء ، في المحافل ، حافل\nمساع ، هي العقد انتظام محاسن ، … تحلى بها جيد من الدهر عاطل\nتنير بها الآمال ، والليل واقب ؛ … وتخصب منها الأرض والأفق ماحل\nهنيئا لك العيد ، الذي بك أصبحت … تروق الضحى منه ، وتندى الأصائل\nتلقاك بالبشرى ، وحياك بالمنى ؛ … فبشراك ألف ، بعد عامك ، قابل\nلئن ينصرم شهر الصيام لبعده ، … نثا صالح الأعمال ما أنت عامل\nرأيت أداء الفرض ضربة لازم ، … فلم ترض حتى شيعته النوافل\nسدنت ، ببيت الله ، حب جواره ، … لك الله بالأجر المضاعف كافل\nهجرت له الدار ، التي أنت آلف … ليعتاده محض الهوى منك واصل\nفإن تتناقلك الديار فطالما … تناقلت البدر المنير المنازل\nألا كل رجوى ، في سواك ، علالة ، … وكل مديح ، لم يكن فيك ، باطل\nفما لعماد الدين ، حاشاك ، رافع ؛ … ولا للواء الملك ، غيرك ، حامل\nلأمنتني الخطب الذي أنا خائف ؛ … وبلغتني الحظ الذي أنا آمل\nأرى خاطري كالصارم العضب لم يزل … له شاحذ ، من حسن رأيك ، صاقل\nوما الشعر مما أدعيه فضيلة … تزين ، ولكن أنطقتني الفواضل\nبقيت كما تبقى معاليك ، إنها … خوالد ، حين العيش كالظل زائل\nفما نستزيد الله ، بعد نهاية ، … لنفسك غير الخلد ، إذ أنت كامل"},{"id":"diwan-zaydun:88","bookId":"diwan-zaydun","type":"poem","seq":88,"chapter":"البحر: سريع","title":"عمر ، من يعمر ذا المجلسا ،","page":"","text":"عمر ، من يعمر ذا المجلسا ، … أطول عمر ، يبهج الأنفسا\nوبعد ذا عوض عن داره … عدنا ، ومن ديباجه السندسا\nووفي الفوز بها والرضى ؛ … ووقي الأسواء والأبؤسا\nودام عباد لعهد الهدى ، … يحرس حتى يفني الأحرسا\nمعتضد بالله ، إحسانه … جم ، إذا ما الدهر يوما أسا\nالملك الغمر الندى ، المقتنى ، … من كل حمد ، علقه الأنفسا\nإن رام يوما ، وصف عليائه ، … مفوه مقتدر أخرسا\nلا زال بدرا طالعا ، نيرا ، … يكشف من آمالنا الحندسا"},{"id":"diwan-zaydun:89","bookId":"diwan-zaydun","type":"poem","seq":89,"chapter":"البحر: طويل","title":"ألم يأن أن يبكي الغمام على مثلي ،","page":"","text":"ألم يأن أن يبكي الغمام على مثلي ، … ويطلب ثأري البرق منصلت النصل\nوهلا أقامت أنجم الليل مأتما ، … لتندب في الآفاق ما ضاع من نثلي\nولو أنصفتني ، وهي أشكال همتي ، … لألقت بأيدي الذل لما رأت ذلي\nولافترقت سبع الثريا ، وغاضها ، … بمطلعها ، ما فرق الدهر من شملي\nلعمر الليالي ! إن يكن طال نزعها … لقد قرطست بالنبل في موضع النبل\nتحلت بآدابي ، وإن مآربي … لسانحة في عرض أمنية عطل\nأخص لفهمي بالقلى ، وكأنما … يبيت ، لذي الفهم ، الزمان على ذحل\nوأجفى ، على نظمي لكل قلادة ، … مفصلة السمطين ، بالمنطق الفصل\nولو أنني أسطيع ، كي أرضي العدا ، … شريت ببعض الحلم حظا من الجهل\nأمقتولة الأجفان ! ما لك والها ؟ … ألم ترك الأيام نجما هوى قبلي ؟\nأقلي بكاء ، لست أول حرة … طوت بالأسى كشحا على مضض الثكل\nوفي أم موسى عبرة أن رمت به … إلى اليم ، في التابوت ، فاعتري واسلى\nلعل المليك المجمل الصنع قادرا … له بعد يأس ، سوف يجمل صنعا لي\nولله فينا علم غيب ، وحسبنا … به ، عند جور الدهر ، من حكم عدل\nهمام عريق في الكرام ، وقلما … ترى الفرع إلا مستمدا من الأصل\nنهوض بأعباء المروءة والتقى ؛ … سحوب لأذيال السيادة والفضل\nإذا أشكل الخطب الملم ، فءنه ، … وآراءه ، كالخط يوضح بالشكل\nوذو تدرإ للعزم ، تحت أناته ، … كمون الردى في فترة الأعين النجل\nيرف ، على التأميل ، لألاء بشره ، … كما رف لألاء الحسام على الصقل\nمحاسن ، ما للحسن في البدر علة ، … سوى أنها باتت تمل فيستملي\nتغص ثنائي ، مثلما غص ، جاهدا ، … سوار الفتاة الراد بالمعصم الخدل\nوتغنى عن المدح ، اكتفاء بسروها ، … غنى المقلة الكحلاء عن زينة الكحل\nأبا الحزم ! إني ، في عتابك ، مائل … على جانب ، تأوي إليه العلا سهل\nحمائم شكوى صبحتك ، هوادلا ، … تناديك من أفنان آدابي الهدل\nجواد ، إذا استن الجياد إلى مدى … تمطر فاستولى على أمد الخصل\nثوى صافنا في مربط الهون يشتكي ، … بتصهاله ، ما ناله من أذى الشكل\nأفي العدل أن وافتك تترى رسائلي … فلم تتركن وضعا لها في يدي عدل ؟\nأعدك للجلى ، وآمل أن أرى ، … بنعماك ، موسوما ، وما أنا بالغفل\nوما زال وعد النفس لي منك بالمنى ، … كأني به قد شمت بارقة المحل\nأأن زعم الواشون ما ليس مزعما … تعذر في نصري وتعذر في خذلي ؟\nوأصدى إلى إسعافك السائغ الجنى ؛ … وأضحى إلى إنصافك السابغ الظل\nولو أنني واقعت عمدا خطيئة ، … لما كان بدعا من سجاياك أن تملي\nفلم أستتر حرب الفجار ، ولم أطع … مسيلمة ، إذ قال : إني من الرسل\nومثلي قد تهفو به نشوة الصبا ؛ … ومثلك قد يعفو ، وما لك من مثل\nوإني لتنهاني نهاي عن التي … أشاد بها الواشي ، ويعقلني عقلي\nأأنكث فيك المدح ، من بعد قوة ، … ولا أقتدي إلا بناقضة الغزل !\nذممت إذا عهد الحياة ، ولم يزل … ممرا ، على الأيام ، طعمها المحلي\nوما كنت بالمهدي إلى السودد الحنا … ولا بالمسيء القول في الحسن الفعل\nما لي لا أثني بآلاء منعم ، … إذا الروض أثنى ، بالنسيم ، على الطل\nهي النعل زلت بي ، فهل أنت مكذب … لقيل الأعادي إنها زلة الحسل ؟\nوهل لك في أن تشفع الطول شافعا … فتنجح ميمون النقيبة ، أو تتلي ؟\nأجر أعد آمن أحسن ابدأ عد اكف … حط تحف ابسط استألف صن احم اصطنع أعل\nمنى ، لو تسنى عقدها بيد الرضا … تيسر منها كل مستصعب الحل\nألا إن ظني ، بين فعليك ، واقف … وقوف الهوى بين القطيعة والوصل\nفإن تمن لي منك الأماني ، فشيمة … لذاك الفعال القصد والخلق الرسل\nوإلا جنيت الأنس من وحشة النوى … وهول السرى بين المطية والرحل\nسيعنى بما ضيعت مني حافظ ؛ … ويلفى لما أرخصت من خطري مغلي\nوأين جواب عنك ترضى به العلا ، … إذا سألتني بعد ألسنة الحفل ؟"},{"id":"diwan-zaydun:90","bookId":"diwan-zaydun","type":"poem","seq":90,"chapter":"البحر: متقارب تام","title":"لبيض الطلى ، ولسود اللمم ،","page":"","text":"لبيض الطلى ، ولسود اللمم ، … بعقلي ، مذ بن عني ، لمم\nففي ناظري ، عن رشاد ، عمى ؛ … وفي أذني ، عن ملام ، صمم\nقضت بشماسي ، على العاذلين ، … شموس مكللة بالظلم\nفما سقمت لحظات العيو … ن ، إلا لتغريني بالسقم\nيلوم الخلي على أن أجن ، … وقد مزج الشوق دمعي بدم\nوما ذو التذكر ممن يلام ؛ … ولا كرم العهد مما يذم\nوإني أراح ، إذا ما الجنو … ب راحت بريا جنوب العلم\nوأصبو لعرفان عرف الصبا ؛ … وأهدي السلام إلى ذي سلم\nومن طرب عاد نحو البرو … ق ، أجهشت للبرق حين ابتسم\nأما وزمان ، مضى عهده … حميدا ، لقد جار لما حكم\nقضى بالصبابة ، ثم انقضى ؛ … وما اتصل الأنس حتى انصرم\nليالي نامت عيون الوشا … ة عنا ، وعين الرضى لم تنم\nومالت علينا غصون الهوى ، … فأجنت ثمار المنى من أمم\nوأيامنا مذهبات البرود ، … رقاق الحواشي ، صوافي الأدم\nكأن أبا بكر الأسلمي … أجرى عليها فرند الكرم\nووشح زهرة ذاك الزمان ، … بما حاز من زهر تلك الشيم\nهو الحاجب المعتلي ، للعلا ، … شماريخ كل منيف أشم\nمليك ، غذا سابقته الملوك ، … حوى الخصل ، أو ساهمته سهم\nفأطولهم ، بالأيادي ، يدا ، … وأثبتهم ، في المعالي ، قدم\nوأروع ، لا معتفي رفده … يخيب ، ولا جاره يهتضم\nذلول الدماثة ، صعب الإباء ، … ثقيف العزيم ، إذا ما اعتزم\nسما للمجرة في أفقها ، … فجر عليها ذيول الهمم\nوناصت مساعيه زهر النجوم ، … وبارت عطاياه وطف الديم\nنهيك ، إذا جن ليل العجاج ، … سرى منه ، في جنحه ، بدر تم\nفشام السيوف بهام الكماة ؛ … وروى القنا في نحور البهم\nجواد ، ذراه مطاف العفاة ؛ … ويمناه ركن الندى المستلم\nيهيج النزال به والسؤا … ل ليثا هصورا ، وبحرا خضم\nشهدنا ، لأوتي فصل الخطاب ، … وخص بفضل النهى والحكم\nوهل فات شيء من المكرمات ؟ … جرى سيف يطلبه ، والقلم\nومستحمد بكريم الفعا … ل ، عفوا ، إذا ما اللئيم استذم\nشمائل ، تهجر عنها الشمول ؛ … وتجفى لها مشجيات النغم\nعلى الروض منها رواء يروق ؛ … وفي المسك طيب أريج يشم\nأبوه الذي فل غرب الضلال ، … ولاءم شعب الهدى ، فالتأم\nولاذ به الدين مستعصيا … بذمة أبلج ، وافي الذمم\nوجاهد ، في الله ، حق الجها … د من دان ، من دونه ، بالصنم\nفلا سامي الطرف ، إلا أذل ؛ … ولا شامخ الأنف ، إلا رغم\nتقيل في العز ، من حمير ، … مقاول عزوا جميع الأمم\nهم نعشوا الملك ، حتى استقل ؛ … وهم أظلموا الخطب ، حتى اظلم\nنجوم هدى ، والمعالي بروج ؛ … وأسد وغى ، والعوالي أجم\nأبا بكر ! اسلم على الحادثات ؛ … ولا زلت من ريبها في حرم\nأناديك ، عن مقة ، عهدها ، … كما وشت الروض أيدي الرهم\nوإن يعدني عنك شحط النوى ، … فحظي أخس ونفسي ظلم\nوإني لأصفيك محض الهوى ؛ … وأخفي ، لبعدك ، برح الألم\nوغيرك أخفر عهد الذمام ، … إذا حسن ظني عليه أذم\nومستشفع بي بشرته ، … على ثقة ، بالنجاح الأتم\nوقدما أقلت المسيء العثار ؛ … وأحسنت بالصفح عما اجترم\nوعندي ، لشكرك ، نظم العقود … تناسق فيه اللآلي التؤم\nتجد لفخرك برد الشباب ، … إذا لبس الدهر برد الهرم\nفعش معصما ، بيفاع السعود ؛ … ودم ناعما في ظلال النعم\nولا يزل الدهر ، أيامه … لكم حشم ، والليالي خدم"},{"id":"diwan-zaydun:91","bookId":"diwan-zaydun","type":"poem","seq":91,"chapter":"البحر: بسيط تام","title":"هل النداء ، الذي أعلنت ، مستمع ؛","page":"","text":"هل النداء ، الذي أعلنت ، مستمع ؛ … أم في المئات ، التي قدمت ، منتفع ؟\nإني لأعجب من حظ يسوف بي ، … كاليأس من نيله ، أن يجذب الطمع\nتأبى السكون إلى تعليل دهري لي ، … نفس إذا خودعت لم ترضها الخدع\nليس الركون إلى الدنيا دليل حجى ، … فإنها دول ، أيامها متع\nتأتي الرزايا نظاما من حوادثها ، … إذ الفوائد ، في أثنائها ، لمع\nأهل النباهة أمثالي لدهرهم ، … بقصرهم ، دون غايات المنى ، ولع\nلولا بنو جهور ما أشرقت هممي ، … كمثل بيض الليالي ، دونها الدرع\nهم الملوك ، ملوك الأرض دونهم ، … غيد السوالف ، في أجيادها تلع\nمن الورى ، إن يفوقوهم ، فلا عجب ، … كذلك الشهر ، من أيامه ، الجمع\nقوم ، متى تحتفل في وصف سؤددهم … لا يأخذ الوصف إلا بعض ما يدع\nتجهم الدهر ، فانصاتت لهم غرر ، … ماء الطلاقة ، في أسرارها ، دفع\nباهت وجوههم الأعراض من كرم ؛ … فكلما راق مرأى طاب مستمع\nسرو ، تزاحم ، في نظم المديح له ، … محاسن الشعر ، حتى بينها قرع\nأبو الوليد قد استوفى مناقبهم ، … فللتفاريق منها فيه مجتمع\nهو الكريم ، الذي سن الكرام له … زهر المساعي ، فلم تستهوه البدع\nمن عترة أوهمته ، في تعاقبها ، … أن المكارم ، إيصاء بها ، شرع\nمهذب أخلصته أوليته ، … كالسيف بالغ في إخلاصه الصنع\nإن السيوف ، إذا ما طاب جوهرها ، … في أول الطبع ، لم يعلق بها طبع\nجذلان يستضحك الأيام عن شيم ، … كالروض تضحك منه في الربى قطع\nكالبارد العذب ، لذت ، من موارده … لشارب غب تبريح الصدى ، جرع\nقل للوزير ، الذي تأميله وزري ، … إن ضاق مضطرب ، أو هال مطلع\nأصخ لهمس عتاب ، تحته مقة ، … وكلف النفس منها فوق ما تسع\nما للمتاب ، الذي أحصفت عقدته ، … قد خامر القلب ، من تضييعه ، جزع ؟\nلي ، في الموالاة ، أتباع يسرهم … أنى لهم ، في الذي نجزى به ، تبع\nألست أهل اختصاص منك ، يلبسني … جمال سيماه ؟ أم ما في مصطنع ؟\nلم أوت في الحال ، من سعيي لديك ، ونى … بل بالجدود تطير الحال أو تقع\nلا تستجز وضع قدري بعد رفعكه ، … فالله لا يرفع القدر الذي تضع !\nتقدمت لك نعمى ، رادها أملي ، … في جانب ، هو للإنسان منتجع\nما زال يونق شكري في مواقعها … كالمزن تونق ، في آثاره ، الترع\nشكر ، يروق ويرضي طيب طعمته ، … في طيه نفحات ، بينها خلع\nظن العدا ، إذ أغبت ، أنها انقطعت ؛ … هيهات ليس لمد\nلا بأس بالأمر ، إن ساءت مبادئه … نفس الشفيقن إذا ما سرت الرجع\nإن الألى كنت ، من قبل افتضاحهم ، … مثل الشجا في لهاهم ، ليس ينتزع\nلم أحظ ، إذ هم عدا ، باد نفاقهم ، … إلا كما كنت أحظى ، إذ هم شيع\nما غاظهم غير ما سيرت من مدح ، … في صائك المسك من أنفاسها فنع\nكم غرة لي تلقتها قلوبهم ؛ … كما تلقى شهاب الموقد الشمع\nإذا تأملت حبي ، غب غشهم ، … لم يخف من فلق الإصباح منصدع\nتلك العرانين ، لم يصلح لها شمم ، … فكان أهون ما نيلت به الجدع\nأودعت نعماك منهم شر مغترس ، … لن يكرم الغرس حتى تكرم البقع\nلقد جزتهم جوازي الدهر عن منن … عفت ، فلم يثنهم ، عن غمطها ، ورع\nلا زال جدك بالأعداء يصرعهم ؛ … إن كان بين جدود الناس مصطرع"},{"id":"diwan-zaydun:92","bookId":"diwan-zaydun","type":"poem","seq":92,"chapter":"البحر: طويل","title":"هو الدهر فاصبر للذي أحدث الدهر ،","page":"","text":"هو الدهر فاصبر للذي أحدث الدهر ، … فمن شيم الأبرار ، في مثلها ، الصبر\nستصبر صبر اليأس أو صبر حسبة ، … فلا تؤثر الوجه الذي معه الوزر\nحذارك من أن يعقب الرزء فتنة … يضيق لها ، عن مثل إيمانك ، العذر\nإذا آسف الثكل اللبيب ، فشفه ، … رأى أفدح الثكلين أن يهلك الأجر\nمصاب الذي يأسى بميت ثوابه ، … هو البرح ، لا الميت الذي أحرز القبر\nحياة الورعى نهج ، إلى الموت ، مهيع ، … لهم فيه إيضاع ، كما يوضع السفر\nفيا هادي المنهاج جرت ، فإنما … هو الفجر يهديك الصراط أو\nغذا الموت أضحى قصر كل معمر ، … فإن سواء طال أو قصر العمر\nألم تر أن الدين ضيم ذماره ، … فلم يغن أنصار عديدهم دثر\nبحيث استقل الملك ثاني عطفه ، … وجرر ، من أذياله ، العسكر المجر\nهو الضيم ، لو غير القضاء يرومه ، … ثناه المرام الصعب والمسلك الوعر\nإذا عثرت جرد العناجيج في القنا ، … بليل عجاج ، ليس يصدعه فجر\nأأنفس نفس ، في الورى ، أقصد الردى ؛ … وأخضر علق ، للهدى ، أفقد الدهر ؟\nأعباد ! يا أوفى الملوكن لقد عدا … عليك زمان ، من سجيته الغدر\nفهلا عداه أن علياك حليه ؛ … وذكرك ، في أردان أيامه ، عطر ؟\nغشيت فلم تغش الطراد سوابح ؛ … ولا جردت بيض ، ولا أشرعت سمر\nولا ثنت المحذور عنك جلالة ؛ … ولا غرر ثبت ولا نائل غمر\nلئن كان بطن الأرض هيء أنسه … بأنك ثاويه ، لقد أوحش الظهر\nلعمر البرود البيض في ذلك الثرى ، … لقد أدرجت ، أثناءها ، النعم الخضر\nعليك ، من الله ، السلام تحية ، … ينسمك الغفران ريحانها النضر\nوعاهد ذاك اللحد عهد سحائب ، … إذا استعبرت ، في تربه ، ابتسم الزهر\nففيه علاء لا يسامى يفاعه ، … وقدر شباب ليس يعدله قدر\nوأبيض في طي الصفيح ، كأنه … صفيحة مأثور طلاقته الأثر\nكأن لم تسر حمر المنايا ، تظلها ، … إلى مهج الأقيال ، راياته الحمر\nولم يحم ، من أن يستباح ، حمى الهدى … فلم يرضه إلا أن ارتجع الثغر\nولم ينتجعه المعتفون ، فأقبلت … عطايا ، كما والى شآبيبه القطر\nولم تكتنف آراءه ألمعية ، … كأن نجي الغيب ، في رأيها ، جهر\nولم يتشذر للأمور ، مجليا … إليها ، كما جلى من المرقب الصقر\nكلا لقبي سلطانه صح فأله ، … فباكره عضد ورواحه نصر\nإلى أن دعاه يومه ، فأجابه ، … وقد قدم المعروف واستمجد الذخر\nفأمسى ثبير ، قد تصدى لحمله … سرير ، فلم يبهضه من هضبه إصر\nألا أيها المولى الوصول عبيده ، … لقد رابنا أن يتلو الصلة الهجر\nنغاديك ، داعينا السلام ، كعهدنا ، … فما يسمع الداعي ، ولا يرفع الستر\nأعتب علينا ذاد عن ذلك الرضى … فنعتب ، أم بالمسمع المعتلي وقر ؟\nأما إنه شغل فراغك بعده … سينصات إلا أن موعده الحشر\nأأنساك ، لما ينأ عهد ، ولو نأى … سجيس الليالي لم يرم نفسي الذكر\nوكيف بنسيان ، وقد ملأت يدي … جسام أياد منك ، أيسرها الوفر ؟\nلئن كنت لم أشكر لك المنن ، التي … تمليتها تترى ، لأوبقني الكفر\nفهل علم الشلو المقدس أنني … مسوغ حال ، ضل في كنهها الفكر\nوأن متابي لم يضعه محمد ، … خليفتك ، العدل الرضى ، وابنك البر\nهو الظافر الأعلى ، المؤيد ، بالذي … له ، في الذي ولاه ، من صنعه ، سر\nرأى في اختصاصي ما رأيت ، وزادني … مزية زلفى من نتائجها الفخر\nوأرغم ، في بري ، أنوف عصابة … لقاؤهم جهم ، ولحظهم شزر\nإذا ما استوى ، في الدست ، عاقد حبوة … وقام سماطا حفله ، فلي الصدر\nوفي نفسه العلياء لي متبوأ ، … ينافسني فيه السماكان والنسر\nيطيل العدا في التناجي خفية ، … يقولون : لا تستفت ، قد قضي الأمر\nمضى نفثهم ، في عقدة السعي ، ضلة … فعاد عليهم غمة ذلك السحر\nيشب مكاني عن توقي مكانهم ، … كما شب قبل اليوم عن طوقه عمرو\nلك الخير ، إن الرزء كان غيابة ، … طلعت لنا فيها ، كما طلع البدر\nفقرت عيون كان أسخنها البكا ؛ … وقرت قلوب كان زلزلها الذعر\nولولاك أعيا رأبنا ذلك الثأى ، … وعز ، فلما ينتعش ذلك العثر\nولما قدمت الجيش ، بالأمس ، أشرقت … إليك ، من الآمال ، آفاقها الغبر\nفقضيت من فرض الصلاة لبانة ، … مشيعها نسك ، وفارطها طهر\nومن قبل ما قدمت مثنى نوافل ، … يلاقي بها من صام ، من عوز ، فطر\nورحت إلى القصر ، الذي غض طرفه … بعيد التسامي ، أن غدا غيره القصر\nفداما معا في خير دهر ، صروفه … حرام عليها أن يطورهما هجر\nوأجمل ، عن الثاوي ، الغراء ، فإن ثوى … فإنك لا الواني ولا الضرع الغمر\nوما أعطت السبعون قبل أولي الحجى … من الإرب ما أعطتك عشروك والعشر\nألست الذي ، إن ضاق ذرع بحادث ، … تبلج منه الوجه ، واتسع الصدر\nفلا تهض الدنيا جناحك بعده ، … فمنك ، لمن هاضت نوائبها ، جبر\nا زلت موفور العديد بقرة … لعينيك ، مشدودا بهم ذلك الأزر\nفإنك شمس ، في سماء رياسة ، … تطلع منهم ، حولها ، أنجم زهر\nشككنا فلم نثبت ، أأيام دهرنا … بها وسن ، أم هز أعطافها سكر ؟\nوما إن تغشتها مغازلة الكرى ؛ … وما إن تمشت ، في مفاصلها ، خمر\nسوى نشوات ، من سجايا مملك ، … يصدق ، في عليائها ، الخبر الخبر\nأرى الدهر ، إن يبطش فأنت يمينه ، … وإن تضحك الدنيا ، فأنت لها ثغر\nوكم سائل ، بالغيب عنك ، أجبته : … هناك الأيادي الشفع والسؤدد الوتر\nهناك التقى والعلم والحلم والنهى … وبذل اللها والبأس والنظم والنثر\nهمام ، إذا لاقى المناجز رده ، … وإقباله خطو ، وإدباره حضر\nمحاسن ، ما للروض ، خامره الندى ، … رواء ، إذا نصت حلاها ، ولا نشر\nمتى انتشقت لم تطر دارين مسكها … حياء ، ولم يفخر بعنبره الشحر\nعطاء ولا من ، وحكم ولا هوى ، … وحلم ولا عجز ، وعز ولا كبر\nقد استوفت النعماء فيك تمامها … علينا ، فمنا الحمد لله والشكر"},{"id":"diwan-zaydun:93","bookId":"diwan-zaydun","type":"poem","seq":93,"chapter":"البحر: كامل تام","title":"فز بالنجاح ، وأحرز الإقبالا ،","page":"","text":"فز بالنجاح ، وأحرز الإقبالا ، … وحز المنى وتنجز الآمالا\nوليهنك التأبيد والظفر اللذا … صدقاكن في السمة العلية ، فالا\nيا أيها الملك ، الذي لولا لم … تجد العقول الناشدات كمالا\nأما الثريا فالثريا نصبة … وإفادة وإنافة وجمالا\nقد شاقها الإغباب ، حتى إنها … لو تستطيع سرت إليك خيالا\nرفه ورودكها لتغنم راحة ؛ … وأطل مزاركها لتنعم بالا\nوتمثل القصر المبارك وجنة ، … قد وسطت فيها الثريا خالا\nوأدر هناك من المدام أتمها … أرجا زكا ، وأشفها جريالا\nقصر ، يقر العين منه مصنع … بهج الجوانب ، لو مشى لاختالا\nلا زلت تفترش السرور حدائقا … فيه ، وتلتحف النعيم ظلالا"},{"id":"diwan-zaydun:94","bookId":"diwan-zaydun","type":"poem","seq":94,"chapter":"البحر: طويل","title":"ألم تر أن الشمس قد ضمها القبر ؛","page":"","text":"ألم تر أن الشمس قد ضمها القبر ؛ … وأن قد كفانا ، فقدنا القمر ، البدر\nوأن الحيا ، إن كان أقلع صوبه ، … فقد فاض للآمال في إثره\nإساءة دهر أحسن الفعل بعدها ، … وذنب زمان جاء يتبعه العذر\nفلا يتهن الكاشحون ، فما دجا … لنا الليل ، إلا ريثما طلع الفجر\nوإن يك ولى جهور ، فمحمد … \nلعمري لنعم العلق أتلفه الردى … فبان ، ونعم العلق أخلفه الدهر\nهززنا به الصمصام ، فالعزم حده ، … وحليته العليا ، وإفرنده البشر\nفتى يجمع المجد المفرق همه ، … وينظم ، في أخلاقه ، السودد النثر\nأهابت إليه بالقلوب محبة ، … هي السحر للأهواء ، بل دونها السحر\nسرت حيث لا تسري من الأنفس المنى … ودبت دبيبا ليس يحسنه الخمر\nلبسنا لديه الأمن ، تندى ظلاله ، … وزهرة عيش مثلما أينع الزهر\nوعادت لنا عادات دنيا ، كأنها … بها وسن ، أو هز أعطافها سكر\nمليك ، له منا النصيحة والهوى ؛ … ومنه الأيادي البيض والنعم الخضر\nنسر وفاء ، حين نعلن طاعة ، … فما خانه سر ، ولا رابه جهر\nفقل للحيارى : قد بدا علم الهدى ؛ … وللطامع المغرور : قد قضي الأمر\nأبا الحزم ! قد ذابت عليك من الأسى … قلوب مناها الصبر ، لو ساعد الصبر\nدع الدهر يفجع بالذخائر أهله ، … فما لنفيس ، مذ طواك الردى ، قدر\nتهون الرزايا بعد ، وهي جليلة ؛ … ويعرف ، مذ فارقتنا ، الحادث النكر\nفقد ناك فقدان السحابة ، لم يزل … لها أثر يثني به السهل والوعر\nمساعيك حلي لليالي مرصع ؛ … وذكرك ، في أردان أيامها ، عطر\nفلا تبعدن ! إن المنية غاية ، … إليها التناهي طال ، أو قصر ، العمر\nعزاء ، فدتك النفس عنه ، فءن ثوى … فإنك لا الواني ، ولا الضرع الغمر\nوما الرزء في أن يودع التراب هالك ، … بلا لرزء كل الرزء أن يهلك الأجر\nأمامك ، من حفظ الإله ، طليعة ؛ … وحولك ، من آلائه ، عسكر مجر\nوما بك من فقر إلى نصر ناصر ، … كفتك ، من الله ، الكلاءة والنصر\nلك الخير ، إني واثق بك شاكر … لمثنى أياديك ، التي كفرها الكفر\nتحامى العدا ، لما اعتلقتك ، جانبي ، … وقال المناوي : شب عن طوقه عمرو\nيلين كلام ، كان يخشن منهم ، … ويفتر نحوي ذلك النظر الشزر\nفصدق طنونا لي وفي ، فإنني … لأهل اليد البيضاء منك ، ولا فخر\nومن يك ، للدنيا وللوفر ، سعيه ، … فتقريبك الدنيا ، وإقبالك الوفر"},{"id":"diwan-zaydun:95","bookId":"diwan-zaydun","type":"poem","seq":95,"chapter":"البحر: كامل تام","title":"اعجب لحال السرو كيف تحال ؛","page":"","text":"اعجب لحال السرو كيف تحال ؛ … ولدولة العلياء كيف تدال\nلا تفسحن للنفس في شأو المنى ، … إن اغترارك ، بالمنى ، لضلال\nما أمتع الآمال ، لولا أنها … تعتاق ، دون بلوغها ، الآجال\nمن سر ، لما عاش ، قل متاعه ، … فالعيش نوم ، والسرور خيال\nفي كل يوم ننتحى برزية ، … للأرض ، من برحائها ، زلزال\nإن ينكدر ، بالأمس ، نجم ثاقب ؛ … فاليوم أقلع عارض هطال\nإن النعي لجهور ومحمد … أبكى الغمام ، فدمعه منثال\nشكلان إن حم الحمام تجاذبا ؛ … لا غرو أن تتجاذب الأشكال\nولى أبو بكر ، فراع له الورى … هول ، تقاصر ، دونه ، الأهوال\nقمر هوى في الترب ، تحثى فوقه ؛ … لله ما حاز الثرى المنهال\nقد قلت ، إذ قيل السرير يقله : … هل للسرير بقدره استقلال ؟\nالآن بين ، للعقول ، زواله ، … أن الجبال ، قصارهن زوال\nما أقبح الدنيا ! خلاف مودع ، … غنيت به في حسنها تختال\nيا قبره العطر الثرى إلا يبعدن … حلو ، من الفتيان ، فيك حلال\nما أنت إلا الجفن ، أصبح طيه … نصل عليه ، من الشباب ، صقال\nفهناك نفاح الشمائل ، مثلما … طرقت بأنفاس الرياض شمال\nدان من الخلق المزين ، نازح … عن كل ما فيه عليه مقال\nشيم ينافس حسنها إحسانها ، … كالراح نافس طعمها الجريال\nيا من شأى الأمثال ، منه واحد ، … ضربت به في السودد الأمثال\nنقصت حياتك ، حين فضلك كامل ، … هلا استضيف ، إلى الكمال ، كمال !\nودعت عن عمر ، عمرت قصيرة … بمكارم ، أعمارهن طوال\nمن للندي ، إذا تنازع أهله ، … فاستجهلت ، حلماءه ، الجهال ؟\nلو كنت شاهدهم لقل مراؤهم … لأغر فيه ، مع الفتاء ، جلال\nمن للعلوم ؟ فقد هوى العلم الذي … وسمت به أنواعها الأغفال\nمن للقضاء يعز ، في أثنائه ، … إيضاح مظلمة ، لها إشكال ؟\nمن لليتيم ، تتابعت أرزاؤه ؟ … هلك الأب الحاني ، وضاع المال\nأعزز بأن ينعاك ، نعي شماتة ، … للأولياء ، المعشر الأقتال\nفجعت رحى الإسلام منك بقطبها ؛ … ليت الحسود فداك ، فهو ثفال\nزرناك لم تأذن ، كأنك غافل ؛ … ما كان منك لواجب إغفال\nأين الحفاوة ، روضها غض الجنى ؛ … أين الطلاقة ، بشرها سلسال\nأيام من يعرض عليك وداده … يكن القبول ، بشيره الإقبال\nمهما نغبك لا نربك ، وإن نزر … رفها ، فما لزيارة إملال\nهيهات لا عهد ، كعهدك ، عائد ، … إذ أنت في وجه الزمان جمال !\nفاذهب ذهاب البرء أعقبه الضنى ، … والأمن وافت بعده الآجال\nلك صالح الأعمال ، إذ شيعتها … بالبر ، ساعة تعرض الأعمال\nحيا الحيا مثواك ، وامتدت على … ضاحي ثراك ، من النعيم ، ظلال\nوإذا النسيم اعتل ، فاعتامت به ، … ساحاتك ، الغدوات والآصال\nولئن أذالك ، بعد طول صيانة ، … قدر ، فكل مصونه سيذال\nسيحوط ، من خلفته ، مستبصر … في حفظ ما استحفظته ، لا يالو\nكفل الوزير ، أبو الوليد ، بجبرهم ؛ … إن الوزير ، لمثلها ، فعال\nملك سجيته الوفاء ، فما له … بالعهد ، في ذي خلة ، إخلال\nحتم عليه لعا لعشرة حالهم ، … قد تعثر الحالات ، ثم تقال\nإيها ، نبي ذكوان ، إن غلب الأسى ، … فلكم ، إلى الصبر الجميل ، مآل\nإن كان غاب البدر عن ساهوره … منكم ، وفارق غابه الرئبال"},{"id":"diwan-zaydun:96","bookId":"diwan-zaydun","type":"poem","seq":96,"chapter":"البحر: وافر تام","title":"أعرفك راح في عرف الرياح ؟","page":"","text":"أعرفك راح في عرف الرياح ؟ … فهز ، من الهوى ، عطف ارتياحي\nوذكرك ما تعرض أم عذاب ؟ … غصصت عليه بالعذب القراح\nوهل أنا منك في نشوات شوق ، … هفت بالعقل ، أو نشوات راح ؟\nلعمر هواك ! ما وريت زناد ، … لوصل منك ، طال لها اقتداحي\nوكم أسقمت ، من قلب صحيح ، … بسقم جفونك المرضى الصحاح\nمتى أخف الغرام يصفه جسمي … بألسنة الضنى الخرس ، الفصاح\nفلو أن الثياب فحصن عني … خفيت خفاء خصرك في الوشاح\nللقينا من الواشين ، حتى … رضينا الرسل أنفاس الرياح\nورب ظلام ليل جن فوقي ، … فنبت ، عن الصباح ، إلى الصباح\nفهل عدت العفاف هناك نفسي ، … فديتك ، أو جنحت إلى الجناح ؟\nوكيف ألج ، لا يثني عناني … رشاد العزم عن غي الجماح ؟\nومن سر ابن عباد دليل ، … به بان الفساد من الصلاح\nهو الملك ، الذي برت ، فسرت … خلال منه طاهرة النواحي\nهمام خطن بالهمم السوامي ، … من العلياء في الخطط الفساح\nأغر ، إذا تجهم وجه دهر ، … تبلج فيه كالقمر اللياح\nسميع النصر لاستعداء جار ؛ … أصم الجود عن تفنيد لاح\nضرائب جهمة ، في العتب تتلى … بأخلاق ، لدى العتبى ، ملاح\nإذا أرج الثناء الروع منها ، … فكم للمسك عنه من افتضاح\nهو المبقي ملوك الأرض تدمى … قلوبهم ، كأفواه الجراح\nرآه الله أجود بالعطايا ؛ … وأطعن بالمكايد والرماح\nوأفرس للمنابر والمذاكي ؛ … وأبهى في البرود وفي السلاح\nوأمنعهم حمى عرض مصون ؛ … وأوسعهم ذرا مال مباح\nفراض له الورى ، حتى تأدت … إليه إتاوة الحي اللقاح\nلمعتضد به أرضاه سعيا ، … فأقبل وجهه وجه الفلاح\nفمن قاس الملوك إليه جهلا ، … كمن قاس النجوم إلى براح\nومعتقد الرياسة في سواه ، … كمعتقد النبوة في سجاح\nأبحر الجود ، في يوم العطايا ، … وليث البأس ، في يوم الكفاح\nلقد سفرت ، بعلتك ، الليالي … لنا عن وجه حادثة وقاح\nألست مصحها من كل داء … ومبدي حسن أوجهها الصباح ؟\nولو كشفت عن الصفحات ، شامت … بروق الموت من بيض الصفاح\nوقاك الله ما تخشى ن ووالى … عليك بصنعه المغدى المراح\nفلو أن السعادة سوغتنا … تجارتها ، الملثة بالرباح\nتجافينا عبيدك عن نفوس ، … عليك من الضنى ، حرى شحاح\nتهنأ فيك بالبرء الموفى ؛ … وتبهج منك بالألم المزاح\nفديتك كم لعيني من سمو ، … لديك ، وكم لنفسي من طماح\nألا هل جاء ، من فارقت ، أني … بساحات المنى رفل المراح ؟\nوأني ، من ظلالك ، في زمان … ندي الآصال ، رقراق الضواحي\nتحييني بريحان التحفي ؛ … وتصبحني معتقه السماح\nفها أنا قد ثملت من الأيادي ، … إذا اتصل اغتباقي في اصطباحي\nفإن أعجز ، فإن النصح ثقف ، … وإن أشكر ، فإن الشكر صاح\nلما أكسبت قدري من سناء ؛ … وما لقيت سعيي من نجاح\nلقد أنفذت ، في الآمال ، حكمي ؛ … وأجريت الزمان على اقتراحي\nوهل أخشى وقوعا ، دون حظ ، … إذا ما أث ريشك من جناحي ؟\nفما استسقيت من غيم جهام ؛ … ولا استوريت من زند شحاح\nوواصلني جميلك ، في مغيبي ، … وطالعني نداك مع انتزاحي\nولم أنفك ، إذ عدت العوادي ، … إليك رهين شوق والتياح\nفحسبي أنت ، من مسد لنعمى ؛ … وحسبك بي بشكر وامتداح"},{"id":"diwan-zaydun:97","bookId":"diwan-zaydun","type":"poem","seq":97,"chapter":"البحر: رمل تام","title":"لست بالجاحد آلاء العلل ،","page":"","text":"لست بالجاحد آلاء العلل ، … كم لها من ألم يدني الأمل\nأجتلي ، من أجلها ، بدر العلا ، … مشرقا في منزلي ، حين كمل\nحلة ، ألبس عيني فخرها ، … فاغتدت ترفل في أبهى الحلل\nرف بشر الأفق في عيني لها ، … لا لأن الشمس حلت في الحمل\nما أبالي من زماني بعدها ، … إذ أصح النفس ، إن جسمي أعل\nأيها المولى ! لقد حملت ما … لم يدع ، في وسع عبد ، محتمل\nوضح الطوق ، الذي حليتني ، … فتراءته نفوس لا مقل\nأنا لو طوقت ، منه بدلا ، … أنجم الجوزاء ، لم أرض البدل\nكم مراد لي ، من نعمائكم ، … وارف الظل ، وكم ورد علل\nلا تزل دولتكم مبسوطة ، … بسطة ، في طيها ، قبض الدول\nورأى المعتضد المنصور ما … أنبأته فيك ليت أو لعل\nفستلقاه الليالي ، طلقة ، … بتفاريق أمانيه جمل"},{"id":"diwan-zaydun:98","bookId":"diwan-zaydun","type":"poem","seq":98,"chapter":"البحر: كامل تام","title":"أقدم ، كما قدم الربيع الباكر ،","page":"","text":"أقدم ، كما قدم الربيع الباكر ، … واطلع ، كما طلع الصباح الزاهر\nقسما ، لقد وفى المنى ، ونفى الأسى ، … من أقدم البشرى بأنك صادر\nليسر مكتئب ، ويغفى ساهر ، … ويراح مرتقب ، ويوفي ناذر\nقفل وإبلال ، عقيب مطيفة … غشيت ، كما غشي السبيل العابر\nإن أعنت الجسم المكرم وعكها ؛ … فلربما وعك الهزبر الخادر\nما كان إلا كانجلاء غيابة ، … لبس ، الفرند بها ، الحسام الباتر\nفلتغد ألسنة الأنام ، ودأبها … شكر ، يجاذبه الخطيب الشاعر\nإن كان أسعد ، من وصولك ، طالع ، … فكذاك أيمن ، من قفولك ، طائر\nأضحى الزمان ، نهاره كافورة ، … والليل مسك ، من خلالك ، عاطر\nقد كان هجري الشعر ، قبل ، صريمة ، … حذري ، لذلك النقد فيها ، عاذر\nحتى إذا آنست أوبك بارئا ، … صفت القريحة واستنار الخاطر\nعي ، قلبت إلى البلاغة عيه ؛ … لولا تقاك لقلت : إنك ساحر\nلقحت ذهني ، فاجن غض ثماره ؛ … فالنخل يحرز مجتناه الآبر\nكم قد شكرتك ، غب ذكرك ، فانتشى … متذكر مني ، وغرد شاكر\nيا أيها الملك ، الذي علياؤه … مثل ، تناقله الليالي ، سائر\nيا من لبرق البشر منه تهلل ، … ما شيم إلا انهل جود هامر\nأنت ابن من مجد الملوك ، فإن يكن … للمجد عين ، فهو منها ناظر\nملك أغر ، ازدانت الدنيا به ، … \nأبناك في ثبج المجرة قبة ؛ … فهناك أنك للنجوم مخاصر\nوتلق ، من سيمتك ، صدق تفاؤلي ، … فهما المؤيد بالإله الظافر"},{"id":"diwan-zaydun:99","bookId":"diwan-zaydun","type":"poem","seq":99,"chapter":"البحر: وافر تام","title":"سأهدي النفس ، في نفس الشمال ؛","page":"","text":"سأهدي النفس ، في نفس الشمال ؛ … فقد لقح التشوق عن حيال\nإلى الشثن العزائم ، إن أثيرت … حفيظته ، إلى اللدن الخلال\nإلى الوضاح آثار المساعي ؛ … إلى النفاح أخبار المعالي\nإلى ملك ، هو المعنى المجلى … به الإشكال ، من لفظ الكمال\nإلى من لا مثيل له ، إذا ما … بدا في السرج ، أو فوق المثال\nهدية من ، لو ان الدهر سنى … مناه ، هدى إليك سرى الخيال\nفكم بوأتني ساحات نعمى ، … عذاب الورد ، وارفة الظلال"},{"id":"diwan-zaydun:100","bookId":"diwan-zaydun","type":"poem","seq":100,"chapter":"البحر: خفيف تام","title":"عذري ، إن عذلت في خلع عذري","page":"","text":"عذري ، إن عذلت في خلع عذري … غصن أثمرت ذراه ببدر\nهز منه الصبا ، فقوم شطرا ، … وتجافى ، عن الوشاح ، بشطر\nرشأ ، أقصد الجوانح ، قصدا ، … عن جفون كحلن ، عمدا ، بسحر\nكسي الحسن ، فهو يفتن فيه ، … ساحبا ذيل برده المسبكر\nتحت ظل ، من الغرارة ، فينا … ن ، وورق ، من الشبيبة ، نضر\nأبرز الجيد في غلائل بيض ؛ … وجلا الخد في مجاسد حمر\nوتثنت بعطفه ، إذ تهادى ، … خطرة تمزج الدلال بكبر\nزارني ، بعد هجعة ، والثريا … راحة ، تقدر الظلام بشبر\nوالدجى ، من نجومه ، في عقود … يتلألأن من سماك ونسر\nتحسب الأفق بينها لا زوردا ، … نثرت ، فوقه ، دنانير تبر\nفرشفت الرضاب أعذب رشف ، … وهصرت القضيب ألطف هصر\n … للتصافي ، وقرع ثغر بثغر\nيا لها ليلة ! تجلى دجاها ، … من سنا وجنتيه ، عن ضوء فجر\nقصر الوصل عمرها ؛ وبودي … أن يطول القصير منها بعمري\nمن عذيري من ريب دهر خؤون ، … كل يوم ، أراع منه بغدر\nكلما قلت : حاك فيه ملامي ، … نهستني منه عقارب تسري\nوترتني خطوبه في صفي … فاضل ، نابه ، من الدهر ، وتر\nبان عني ، وكان روضة عيني ، … فغدا اليوم ، وهو روضة فكري\nفكه ، يبهج الخليل بوجه ، … ترد العين منه ينبوع بشر\nلوذعي ، إن يبله الخبر يوما ، … أخجل الورد عن خلائق زهر\nوإذا غازلته مقلة طرف … كاد ، من رقة ، يذوب فيجري\nيا أبا القاسم الذي كان ردئي ، … وظهيري ، على الزمان ، وذخري\nيا أحق الورى بممحوض إخلا … صي ، وأولاهم بغاية شكري\nطرق الدهر ساحتي ، من تنائي … ك ، بجهم من الحوادث ، نكر\nليت شعري ! والنفس تعلم أن لي … س بمجد على الفتى : ليت شعري\nهل لخالي زماننا من رجوع ، … أم لماضي زماننا من مكر ؟\nأين أيامنا ؛ وأين ليال ، … كرياض لبسن أفواف زهر\nوزمان ، كأنما دب فيه … وسن ، أو هفا به فرط سكر\nحين نغدو إلى جداول زرق ، … يتغلغلن في حدائق خضر\nفي هضاب ، مجلوة الحسن ، حمر ، … وبواد ، مصقولة النبت ، عفر\nنتعاطى الشمول ، مذهبة السر … بال ، والجو في مطارف غبر\nفي فتو ، توشحوا بالمعالي ، … وتردوا ، بكل مجد وفخر\nوضح ، تنجلي الغياهب منهم … عن وجوه ، مثل المصابيح ، غر\nكل خرق ، يكاد ينهل ظرفا ، … زان مرأى به بأكرم خبر\nوسجايا ، كأنهن كؤوس ؛ … أو رياض قد جادها صوب قطر\nيتلقى القبول مني قبول ، … كلما راح نفحها ارتاح صدري\nفهو يسري محملا ن من سجايا … ك ، نسيما يزهى بأفوح عطر\nيا خليلي وواحدي والمعلى … من قداحي ، والمستبد ببري\nلا يضعن ودي ، الصريح ، الذي أر … ضاك منه استواء سري وجهري\nوتوالي أذمة ، نظمتنا … نظم عقد الجمان في نحر بكر\nلا يكن قصرك الجفاء ، فإن الود ، … إن ساعدت حياتي . قصري\nوأعد ، بالجواب ، دولة أنس ، … قد تقضت ، إلا علالة ذكر\nواكس متن القرطاس ديباج لفظ … يبهر الفكر من نظيم ونثر\nغرر ، من بدائع ، لا يشك الده … ر في أنها قلائد در\nتتوالى على النفوس ، دراكا ، … عن فتى موسر ، من الطبع ، مثر\nشد في حلبة البلاغة ، حتى … بان فيها عن شأو سهل وعمرو\nوإذا أنت لم تعجل جوابي ، … كان هذا الكتاب بيضة عقر\nفابق في ذمة السلامة ، ما انجا … ب ، عن الأفق ، عارض متسر\nوعليك السلام ما غنت الور … ق ، ومالت بها ذوائب سدر"},{"id":"diwan-zaydun:101","bookId":"diwan-zaydun","type":"poem","seq":101,"chapter":"البحر: طويل","title":"هو الدهر الذي أحدث الدهر ،","page":"","text":"هو الدهر الذي أحدث الدهر ، … فمن شيم الأبرار ، في مثلها ، الصبر\nستصبر صبر اليأس ، أو صبر حسبة ، … فلا ترض بالصبر ، الذي معه وزر\nحذارك من أن يعقب الرزء فتنة ، … يضيق لها ، عن مثل أخلاقك ، العذر\nإذا أسف الثكل اللبيب ، فشفه ، … رأى أبرح الثكلين أن يحبط الأجر\nمصاب الذي يأسى بميت ثوابه ، … هو البرح ، لا الميت الذي أحرز القبر\nحياة الورى نهج ، إلى الموت ، مهيع ، … لهم فيه إيضاع ، كما يوضع السفر\nفيا هادي المنهاج جرت ، فإنما … هو الفج يهديك الصراط أو البجر\nلنا ، في سوانا ، عبرة غير أننا … نغر بأطماع الأماني ، فنغتر\nإذا الموت أضحى قصر كل معمر ، … فإن سواء طال أو قصر العمر\nألم تر أن الدين ريع ذماره ، … فلم يغن أنصار عديد ولا وفر\nبحيث استقل الملك ثاني عطفه ، … وجرر ، من أذياله ، العسكر المجر\nهو الضيم ، لو غير القضاء يرومه ، … شآه المرام الصعب والمسلك الوعر\nإذا عثرت جرد السوابح في القنا … بليل عجاج ، ليس يصدعه فجر\nلقد بكر الناعي علينا بدعوة … عوان ، أمضتنا لها لوعة بكر\nأأنفس نفس في الورى أقصد الردى ؟ … وأخطر علق ، للهدى ، أهلك الدهر ؟\nهينئا ، لبطن الأرض ، أنس مجدد … بثاوية حلته ، فاستوحش الظهر\nبطاهرة الأثواب ، فاتنة الضحى ، … مسبحة الآناء ، محرابها الخدر\nفإن أنئيت فالنفس أنأى نفيسة ، … إذ الجسم لا يسمو لتذكيره ذكر\nحصان إن التقوى استبدت بسرها ، … فمن صالح الأعمال يستوضح الجهر\nيطأطأ ستر الصون دون حجابها ، … فيرفع ، عن مثنى نوافلها ، الستر\nلعمر البرود البيض في ذلك الثرى ، … لقد أدرجت ، أثناءها ، النعم الخضر\nعليها سلام الله تترى ، تحية ، … ينسمها الغفران ، ريحانها النضر\nوعاهد تلك الأرض عهد غمامة ، … إذا استعبرت في تربها ابتسم الزهر\nفديناك ، إن الرزء كان غمامة ، … طلعت لنا فيها ، كما يطلع البدر\nألست الذي إن ضاق ذرع بحادث … تبلج منه الوجه واتسع الصدر ؟\nتعز بحواء ، التي الخلق نسلها ، … فمن دونها في العصر يتبعه العصر\nنساء النبي المصطفى ، أمهاتنا ، … ثوين فمعناهن ، مذ حقب ، قفر\nوجازيتها الحسنى ، فأم شفيقة ، … تحفى بها ابن ، كل أفعاله بر\nتمنت وفاة ، في حياتك ، بعدما … توالت ، كنظم العقد ، آمالها النثر\nكأن الردى نذر عليها مؤكد ، … فإن أسعفت بالحظ فيك وفي النذر\nتولت فأبقت ، من مجاب دعائها ، … نفائس ذخر ما يقاس به ذخر\nتتم به النعمى ، وتتسق المنى ، … وتستدفع البلوى ، ويستقبل الصبر\nفلا تهض الدنيا جناحك بعدها ، … فمنك ، لمن هاضت نوائبها ، جبر\nا زلت موفور العديد بقرة … لعينيك ، مشدود بهم ذلك الأزر\nبنى جهور ! أنتم سماء رياسة … لعافيكم ، في أفقها ، أنجم زهر\nترى الدهر ، إن يبطش فمنكم يمينه ، … وإن تضحك الدنيا ، فأنتم لها ثغر\nلكم كل رقراق السماح ، كأنه … حسام عليه ، من طلاقته ، أثر\nسحائب نعمى أبرقت وتدفقت ، … فصيبها الجدوى ، وبارقها البشر\nإذا ما ذكرتم واستشفت خلالكم … تضوعت الأخبار ، واستمجد الخبر\nطريقتكم مثلى ، وهديكم رضى ، … ونائلكم غمر ، ومذهبكم قصر\nوكم سائل ، بالغيب عنكم ، أجبته : … هناك الأيادي الشفع والسودد الوتر\nعطاء ولا من ، وحكم ولا هوى ، … وحلم ولا عجز ، وعز ولا كبر\nقد استوفت النعماء فيكم تمامها … علينا ، فمنا الحمد لله والشكر"},{"id":"diwan-zaydun:102","bookId":"diwan-zaydun","type":"poem","seq":102,"chapter":"البحر: طويل","title":"أجل ، إن ليلى حيث أحياؤها الأسد ،","page":"","text":"أجل ، إن ليلى حيث أحياؤها الأسد ، … مهاة حمتها ، في مراتعها ، أسد\nيمانية تدنو وينأى مزارها ؛ … فسيان منها في الهوى القرب والبعد\nإذا نحن زرناها تمرد مارد ، … وعز فلم نظفر به ، الأبلق الفرد\nتحول رماح الخط دون اعتيادها ، … وخيل ، تمطى نحو غاياتها ، جرد\nلحي لقاح ، تأنف الضيم منهم … جحاجحة شيب ، وصيابة مرد\nأب ذو اعتزام ، أو أخ ذو تسرع ؛ … فشيخان ماضي الهم ، أو فاتك جلد\nفما شيم ، من ذي الهبة الصارم ، الشبا ؛ … ولا حط ، عن ذي الميعة السابح ، اللبد\nوفي الكلة الحمراء ، وسط قبابهم ، … فتاة ، كمثل البدر ، قابله السعد\nعقيلة سرب ، لا الأراك مراده ؛ … ولا قمن منه البرير ولا المرد\nتهادى ، فيضنيها الوشاح ، غريرة ، … تأوه مهما ناس ، في جيدها ، العقد\nإذا استحفظت سر السرى جنح ليلها … تناسى النمومان : الألوة ، والند\nلها عدة بالوصل ، يوعد غبها … مصاليت ، ينسى ، في وعيدهم ، الوعد\nعزيز عليهم أن يعود خيالها ، … فيسعف منها نائل ، في الكرى ، ثمد\nكفى لوعة أن الوصال نسيئة ، … يطيل عناء المقتضي ، والهوى نقد\nستبلغها عنا الشمال تحية ، … نوافح أنفاس الجنوب لها رد\nفما نسي الإلف ، الذي كان بيننا ، … لطول تنائينا ، ولا ضيع العهد\nلئن قيل : في الجد النجاح الطالب ؛ … لقل غناء الجد ما لم يكن جد\nينال الأماني ، بالحظيرة ، وادع ، … كما أنه يكدي ، الذي شأنه الكد\nهو الدهر ، مهما أحسن الفعل مرة ، … فعن خطإ ، لكن إساءته عمد\nحذارك أن تغتر منه بجانب ، … ففي كل واد ، من نوائبه ، سعد\nولولا السراة الصيد من آل جهور … لأعوز من يعدى عليه ، متى يعدو\nملوك لبسنا الدهر في جنباتهم ، … رقيق الحواشي ، مثلما فوف البرد\nبحيث مقيل الأمن ، ضاف ظلاله ؛ … وفي منهل العيش العذوبة والبرد\nهم النفر البيض ، الذين وجوههم … تروق فتستشفي بها الأعين الرمد\nكرام يمد الراغبون أكفهم … إلى أبحر منهم ، لها باللهامد\nفلا ينع منهم هالك ، فهو خالد … بآثاره ؛ إن الثناء هو الخلد\nأقلوا عليهم ، لا أبا لأبيكم ، … من اللوم ، أو سدوا المكان الذي سدوا\nأولئك ، إن نمنا سرى ، في صلاحنا ، … سجاع علينا ، كحل أجفانهم سهد\nأليس أبو الحزم ، الذي غب سعيه ، … تبصر غاوينا ، فبان له الرشد\nأغر تمهدنا به الحفضن بعدما … أقض علينا مضجع ، ونبا مهد\nلشمر حتى انجاب عارض فتنة ، … تألق منها البرق ، واصطخب الرعد\nفسالم من كانت له الحرب عادة ؛ … ووافق من لا شك في أنه ضد\nهو الأثر المحمود ، إن عاد ذكره … تطلعت العلياء ، واستشرف المجد\nتولى ، فلولا أن تلاه محمد ، … لأوطأ ، خد الحر أخمصه ، العبد\nمليك يسوس الملك منه مقلد ، … روى عن أبيه فيه ما سنه الجد\nسجيته الحسنى ، وشيمته الرضى ، … وسيرته المثلى ، ومذهبه القصد\nهمام ، إذا زان الندي بحبوة … ترجح ، في أثنائها ، الحسب العد\nزعيم ، لأبناء السيادة ، بارع ، … عليهم به تثنى الخناصر ، إن عدوا\nبعيد منال الحال ، داني جنى الندى ، … إذا ذكرت أخلاقه خجل الورد\nتهلل ، فانهلت سماء يمينه … عطايا ، ثرى الآمال ، من صوبها ، جعد\nممر ، لمن عاداه ، إذ أولياؤه … يلذ لهم كالماء ، شيب به الشهد\nإذا اعترف الجاني عفا عفو قادر ، … علا قدره عن أن يلج به حقد\nومتئد لو زاحم الطود حلمه … لحاجزه ركن ، من الطود ، منهد\nله عزمة مطوية ، في سكينة ، … كما لان متن السيف ، واخشوشن الحد\nيوكل بالتدبير خاطر فكرة ، … إن اقتدحت ، في خاطر ، أثقب الزند\nذراع لما يأتي به الدهر ، واسع ؛ … وباع ، إلى ما يحرز الفخر ممتد\nإذا أسهب المثنون فيه ، شأتهم … مراتب عليا ، كل عن عفوها الجهد\nهو الملك المشفوع ، بالنسك ، ملكه ، … فيا فضل ما يخفي ويا سرو ما يبدو\nإلى الله أواب ، ولله خائف ، … وبالله معتد ، وفي الله مشتد\nلقد أوسع الإسلام ، بالأمس ، حسبة ، … نحت غرض الأجر الجزيل ، فلم تعد\nأباح حمى الخمر الخبيثة ، حائطا … حمى الدين ، من أن يستباح له حد\nفطوق باستئصالها المصر منة ، … يكاد يؤدي ، شكرها ، الحجر الصلد\nهي الرجس ، إن يذهبه عنه ، فمحسن … شهير الأيادي ، ما لآلائه جحد\nمظنة آثام ، وأم كبائر ، … يقصر ، عن أدنى مايبها ، العد\nرأى نقص ما يجبيه منها زيادة ، … إذ العوض المرضي ، إلا يرح يغدو\nغني ، فحسن الظن بالله ماله ؛ … عزيز ، فصنع الله ، من حوله ، جند\nلنعم حديث البر تودعه الصبا ، … تبث نثاه ، حيث لا توضع البرد\nتغلغل في سمع الرباب ، وطالعت … له صورة ، لم يعم ، عن حسنها ، الخلد\nمساع أجدت زينة الأرض ، فالحصى … لآلىء نثر ، والثرى عنبر ورد\nلدى زهرات الروض عنها بشارة ؛ … وفي نفحات المسك ، من طيبها ، وفد\nفديتك ، إني قائل ، فمعرض … بأوطار نفس ، منك ، لم تقضها بعد\nمنى كالشجا دون اللهاة تعرضت ، … فلم يك للمصدود ، من نفثها ، بد\nأمثلي غفل ، خامل الذكر ضائع ، … ضياع الحسام العضب ، أصدأه الغمد\nأبى ذاك أن الدهر قد ذل صعبه … فسني منه ، بالذي نشتهي ، العقد\nأنا السيف لا ينبو مع الهز غربه ، … إذا ما نبا السيف ، الذي تطبع الهند\nبدأت بنعمى غضة ، إن توالها ، … فحسن الألى ، في أن يواليها سرد\nلعمرك ! ما للمال أسعى ، فإنما … يرى المال أسنى حظه ، الطبع الوغد\nولكن لحال ، إن لبست جمالها ، … كسوتك ثوب النصح ، أعلامه الحمد\nأتتك القوافي ، شاهدات بما صفا … من الغيب ، فاقبلها فما غرك الشهد\nليحظى ولي ، سره وفق جهره ، … فظاهره شكر ، وباطنه ود\nيميزه ، ممن سواه ، وفاؤه … وإخلاصه ، إذ كل غانية هند"},{"id":"diwan-zaydun:103","bookId":"diwan-zaydun","type":"poem","seq":103,"chapter":"البحر: كامل تام","title":"للحب ، في تلك القباب ، مراد ،","page":"","text":"للحب ، في تلك القباب ، مراد ، … لو ساعف الكلف المشوق مراد\nليغر هواك ، فقد أجد حماية … لفتاة نجد ، فتية أنجاد\nكم ذا التجلد ؟ لن يساعفك الهوى … بالوصل ، إلا أن يطول نجاد\nأعقيلة السرب ! المباح لوردها … صفو الهوى ، إذ حلئ الوراد\nما للمصايد لم تنلك بحيلة ؟ … إن الظباء لتدرى ، فتصاد\nإن يعد عن سمرات جزعك سامر … في كل مطلع لهم إرعاد\nفبما ترقرق للمتيم بينها … غلل ، شفى حر الغليل ، براد\nأنا حين أطرق ليس يفتأ طارقي … شوق ، كما طرق السليم عداد\nينهى جفاؤكن عن زيارتي ، الكرى ، … كيلا يزور خيالك المعتاد\nلا تقطعي صلة الخيال تجنبا ، … إذ فيه من عوز الوصال سداد\nما ضر أنك بالسلام ضنينة ، … أيام طيفك ، بالعناق ، جواد\nهلا حملت السقم عن جسم له ، … في كلة زرت عليك ، فؤاد\nأو عدت من سقم الهوى ؛ إن الهوى … مما يطيل ضنى الفتى ، فيعاد\nإيها ! فلولا أن أروعك بالسرى … لدنا وساد ، أو لطال سواد\nلغشيت سجفك في ملاءة نثرة ، … فضل ، سوى أن العطاف نجاد\nلأميل في سكر اللمى فيبيت لي ، … مما حوى ذاك السوار ، وساد\nفعدي المنى ، فوعيد قومك لم يكن … ليعوق عن أن يقتضى الميعاد\nأصبو إلى ورد الخدود ، إذا عدت … جرد ، تبلغني جناه ، وراد\nوأراح للعطر ، السطوع أريجه ، … إن شيب بالجسد العطير جساد\nعزم إذا قصد الحمى لم يثنه … أن القنا ، من دونها ، أقصاد\nمن كان يجهل ما البليد ، فإنه … من تطبيه ، عن الحظوظ ، بلاد\nوفتى الشهامة من ، إذا أمل سما ، … نفذت به شورى ، أو استبداد\nمن مبلغ عني الأحبة ، إذ أبت … ذكراهم أن يطمئن مهاد\nلا يأس ؛ رب دنو دار جامع … للشمل ، قد أدى إليه بعاد\nإن أغترب فمواقع الكرم ، الذي … في الغرب شمت بروقه ، أرتاد\nأو أنأ ، عن صيد الملوك بجانبي ، … فهم العبيد مليكهم عباد\nالمجد عذر في الفراق لمن نأى ، … ليرى المصانع منه كيف تشاد\nيا هل أتى من ظن بي ، فظنونه … شتى ترجح بينها الأضداد\nأني رأيت المنذرين ، كليهما ، … في كون ملك لم يحله فساد\nوبصرت بالبردين إرث محرق ، … لم تخلقا ، إذ تخلق الأبراد\nوعرفت من ذي الطوق عمر وثأره … لجذيمة الوضاح ، حين يكاد\nوأتى بي النعمان يوم نعيمه ، … نجم تلقى سعده الميلاد\nقد ألفت أشتاتهم في واحد ، … إلا يكنهم أمة ، فيكاد\nفكأنني طالعتهم بوفادة ، … لم يستطعها عروة الوفاد\nفي قصر ملك كالسدير ، أو الذي … ناطت به شرفاتها سنداد\nتتوهم الشهباء فيه كتيبة … بفناء ، اليحموم فيه جواد\nيختال ، من سير الأشاهب وسطه ، … بيض ، كمرهفة السيوف ، جعاد\nفي آل عباد حططت ، فأعصمت … هممي ، بحيث أنافت الأطواد\nأهل المناذرة ، الذين هم الربى … فوق الملوك ، إذ الملوك وهاد\nقوم إذا عدت معد عقيلة ، … ماء السماء ، فهم لها أولاد\nبيت تود الشهب ، في أفلاكها ، … لو أنها ، لبنائه ، أوتاد\nممدودة ، بلهى الندى ، أطنابه ، … مرفوعة ، بالبيض ، منه عماد\nمتقادم إلا تكن شمس الضحى … لدة له ، فنجومها أرآد\nنيطت بعباد لآلىء مجدهم ، … فتلألأت ، في تومها ، الأفراد\nملك إذا افتنت صفات جلاله ، … فتقاصرت عن بعضها الأعداد\nنسيت زبيد عمرها ، بل أعرضت … عن وصف كعب بالسماح إياد\nفضح الدهاة ، فلو تقدم عهده … لعنا المغيرة ، أو أقر زياد\nلا يأمن الأعداء رجم ظنونه ؛ … إن الغيوب وراءها إمداد\nملك ، إذا ما اختال غرة فيلق ، … قد أمطيت ، عقبانه ، الآساد\nأسد ، فرائسها الفوارس في الوغى ، … لكن براثنها ، هناك ، صعاد\nخلت اللواء غمامة في ظلها … قمر ، بغرته السنا الوقاد\nشيحان منغمس السنان من العدا … في النقع ، حيث تغلغل الأحقاد\nتشكو إليه الشمس نقع كتيبة ، … ما زال منه ، لعينها ، إرماد\nجيش ، إذا ما الأفق سافر طيره … معه ، ففي ذمم الصوارم زاد\nمستطرف للمجد ، لم يك حسبه … مجد ، يدور مع الزمان ، تلاد\nما كان منه إلى رفاهة راحة ، … حتى يخلد ، مثله ، إخلاد\nأرج الندي ، متى تفز بجواره ، … يطب الحديث ويعبق الإنشاد\nلو أن خاطره الجميع مفرق … في الخلق ، أوشك أن يحس جماد\nنفسي فداؤك ، أيها الملك الذي … زهر النجوم ، لوجهه ، حساد\nتبدو عليك ، من الوسامة ، حلة … يهفو إليها ، بالنفوس ، وداد\nلم يشف منك العين أول نظرة … لولا المهابة راجعت تزداد\nما كان من خلل ، فأنت سداده … في الدهر ، أو أود ، فأنت سداد\nالدين وجه ، أنت فيه غرة ، … والملك جفن ، أنت فيه سواد\nلله منك يد علت ، تولي بها … صفدا فيحمد ، أو يفك صفاد\nلو أن أفواه الملوك توافقت … فيها ، لوافق حظها الإسعاد\nنفع العداة اليأس منك ، لأنه … بردت عليه منهم الأكباد\nينصاع من جاراك مقبوض الخطا … فكأنما عضت به الأقياد\nقد قلت للتالي ثناءك سورة ، … ما للورى ، في نصها ، إلحاد\nأعد الحديث عن السيادة ، إنه … ليس الحديث يمل حين يعاد\nكرم ، كماء المزن راق ، خلاله ، … أدب ، كروض الحزن بات يجاد\nومحاسن ، زهر الزمان بزهرها ، … فكأنما أيامه أعياد\nيا أيها الملك الذي ، في ظله ، … ريض الزمان ، فذل منه قياد\nيا خير معتضد بمن أقداره ، … في كل معضلة ، له أعضاد\nلما وردت ، بورد حضرتك ، المنى ، … فهقت لدي جمامها الأعداد\nفاستقبلتني الشمس تبسط راحة … للبحر ، من نفحاتها ، استمداد\nفلئن فخرت ، بما بلغت ، لقل لي … ألا يكون من النجوم عتاد\nمهما امتدحت سواك ، قبل ، فإنما … مدحي ، إلى مدحي ، لك استطراد\nيغشى الميادين الفوارس ، حقبة ، … كيما يعلمها ، النزال ، طراد\nفلأسحبن ذيل المنى في ساحة ، … إلا أوف بها المنى ، فأزاد\nوليستفيدن السناء ، مع الغنى ، … عبد يفيد النصح ، حين يفاد\nولأنت أنفس شيمة من أن يرى ، … لنفيس أعلاقي لديك ، كساد\nهيهات قد ضمن الصباح لمن سرى … أن يستتب ، لسعيه ، الإحماد\nلا تعدمن ، من الحظوظ ، ذخيرة … تبقى ، فلا يتلو البقاء نفاد"},{"id":"diwan-zaydun:104","bookId":"diwan-zaydun","type":"poem","seq":104,"chapter":"البحر: طويل","title":"ليهن الهدى إنجاح سعيك في العدا ،","page":"","text":"ليهن الهدى إنجاح سعيك في العدا ، … وأن راح صنع الله نحوك ، واغتدى\nونهجك سبل الرشد في قمع من غوى … وعدلك في استئصال من جار واعتدى\nوأن بات من والاك في نشوة الغنى ؛ … وأصبح من عاداك في غمرة الردى\nوبشراك دنيا غضة العهد طلقة ، … كما ابتسم النوار عن أدمع الندى\nودولة سعد لا انتهاء لحده ، … إذا قيل فيه قد تناهى تولدا\nدعوت ، فقال النصر : لبيك ماثلا ، … ولم تك كالداعي يجاوبه الصدى\nوأحمدت عقبى الصبر في درك المنى … كما بلغ الساري الصباح فأحمدا\nأعباد ، يا أوفى الملوك بذمة ، … وأرعاهم عهدا وأطولهم يدا\nتباينت في حاليك : غرت تواضعا … لتستوفي العليا ، وأنجدت سوددا\nولما اعتضدت الله كنت مؤهلا … لديه لأن تحمى وتكفى وتعضدا\nوجدناك إن ألقحت سعيا نتجته ، … وغيرك شاو ، حين أنضج رمدا\nوكم ساعد الأعداء أول مطمع … رأوك بعقباه أحق وأسعدا\nفلا ظافر إلا ، إلى سعدك ، اعتزى ، … ولا سائس إلا بتدبيرك اقتدى\nضلالا لمفتون سموت بحاله ، … إلى أن بدت ، بين الفراقد ، فرقدا\nرأى حطها أولى به ، فأحلها … حضيضا ، بكفران الصنيعة ، أوهدا\nوما زاد ، لما لج في البغي ، أنه … سعى للذي أصلحت منها فأفسدا\nفزل وقد أمطيته ثبج السها ؛ … وضل وقد لقيته قبس الهدى\nطويل عثار الجرم ، قلت له : لعا … بحلم ، تلقى جهله ، فتغمدا\nتجنى فأهديت النصيحة محضة ؛ … ولج فواليت العقاب مرددا\nولم تأله ، بقيا عليه ، تنظرا … لفيئة من أكرمته ، فتمردا\nفما آثر الأولى ، ولا قلد الحجى ، … ولا شكر النعمى ، ولا حفظ اليدا\nكأنك أهديت السوابح ضمرا … ليركضها ، فيما كرهت ، فيجهدا\nوأجررته ذيل الحبير تألفا ، … ليخلق ، فيما جر ، حقدا مجددا\nسل الحائن المعتر : كيف احتقابه ، … مع الدهر ، عارا بالعرار مخلدا ؟\nرأى أنه أضحى هزبرا مصمما ، … فلم يعد أن أمسى ظليما مشردا\nدهاه ، إذا ما جنه الليل ، أنه … أقام عليه ، آخر الدهر ، سرمدا\nيحاذر أن يلفى قتيلا معفرا ، … إذا الصبح وافى ، أو أسيرا مقيدا\nلبئس الوفاء استن في ابن عقيدة … عشية لم يصدره من حيث أوردا\nقرين له أغواه ، حتى إذا هوى ، … تبرأ يعتد البراءة أرشدا\nفأصبح يبكيه المصاب بثكله … بكاء لبيد حين فارق أربدا\nفداء لإسماعيل كل مرشح ، … إذا جشم الأمر الجسيم تبلدا\nأفاد من الأملاك حدثان فشلهم … موالي ، لم يشك الصدى منهم الصدى\nأعاد الصباح الطلق ليلا عليهم ، … فجاء وأثنى ناظر الشمس أرمدا\nفحل هلالا ، في ظلام عجاجة ، … تلاحظه الأقمار ، في الأفق ، حسدا\nيراجم من صنهاجة وزناتة ، … بمثل نجوم القذف ، مثنى وموحدا\nهم الأولياء المانحوك صفاءهم ، … إذا امتاز مصفى الود ممن توددا\nلهم كل ميمون النقيبة بازل ، … كفيل بأن يستهزم الجمع مفردا\nيسرك ، في الهيجا ، إذا جر لامة ؛ … ويرضيك ، في النادي ، إذا اعتم وارتدى\nكرهت ، لسيف الملك ، ألفة غمده ، … وقل غناء السييف ما كان مغمدا\nولم تر للشبل الإقامة في الشرى ، … فجد افتراسا حين أصحر للعدا\nهمام ، إذا حاربت ، فارفع لواءه ، … فما زال منصور اللواء ، مؤيدا\nويأنف من لين المهاد ، تعوضا … بصهوة طيار ، إلى الروع أجردا\nوقدما شكا حمل التمائم يافعا ، … ليحمل رقراق الفرند ، مهندا\nولم نر سيفا ، باتك الحد قبله ، … تناول سيفا ، دونه ، فتقلدا\nلئن أنجزت منه الشمائل آخرا ، … لقد قدمت منه المخايل موعدا\nقررت به عينا ، فكم ساد عترة ؛ … وكم ساس سلطانا ، وكم زان مشهدا\nوأعطيتما ، فيما تريغانه ، الرضى ؛ … وبلغتما ، مما تريدانه ، المدى"},{"id":"diwan-zaydun:105","bookId":"diwan-zaydun","type":"poem","seq":105,"chapter":"البحر: متقارب تام","title":"هي الشمس ، مغربها في الكلل ؛","page":"","text":"هي الشمس ، مغربها في الكلل ؛ … ومطلعها من جيوب الحلل\nوغصن ، ترشف ماء الشباب ، … ثراه الهوى ، وجناه الأمل\nتهادى ، لطيفة طي الوشاح ؛ … وترنو ، ضعيفة كر المقل\nوتبرز خلف حجاب العفاف ؛ … وتسفري تحت نقاب الخجل\nبدت في لدات ، كزهر النجوم ، … حسان التحلي ملاح العطل\nمشين ، يهادين روض الربى ، … بيانع روض الصبا المقتبل\nفمن قضب تتثنى بريح ؛ … ومن قضب تتثنى بدل\nومن زهرات تندى بمسك ؛ … ومن زهرات تندى بطل\nتعاهد صوب العهاد الحمى ، … ولا زال مربعها في ملل\nمراد ، من الحب ، غض الجنى ، … لديه ، من الوصل ، ورد علل\nليالي ما انفك يهدي السرور … حبيب سرى ، ورقيب غفل\nزمان ، كأن الفتى المسلمي … تكنفه عدله ، فاعتدل\nتدارك ، من حكمه ، أن يعيد … به عزة الدين ، أيام ذل\nويوضح رسم التقى ، إذ عفا ؛ … ويطلع نجم الهدى ، إذ أفل\nحمدنا المظفر لما رأى … لمنصورنا سيرة ، فامتثل\nمليك ، تجلى له غرة ، … تأملها غرة تهتبل\nأشف الورى ، في النهى ، رتبة ؛ … وأشهرهم ، في المعالي ، مثل\nوأحرى الأنام بأمر ونهي ؛ … وأدرى الملوك بعقد وحل\nيمان ، له التاج من بينهم ، … بما أورث التبعون الأول\nسنام ، من المجد ، عالي الذرا ، … يظل العدا منه تحت الأظل\nتقيل ، في المهد ، ظل اللواء ؛ … وسيم النهوض به ، فاستقل\nونيطت حمائله الوافيات ، … مكان تمائمه ، فاحتمل\nوما بلت البرد تلك الدمو … ع ، إلا وفي البرد ليث أبل\nعهدنا المكارم فيه معاني ، … تبشرنا فيه منها الجمل\nترى ، بعد بشر ، يريك الغمام ، … تهلل بارقه ، فاستهل\nيصدق ما حدثتنا عسى … به عنه ، أو أنبأتنا لعل\nفما وعد الظن ، إلا وفى ؛ … ولا قالت النفس ، إلا فعل\nفلقى مناوئه ما اتقى ؛ … وأعطى مؤمله ما سأل\nغمام يظل ، وشمس تنير ، … فأقبل ينعم من ذي قبل\n … وبحر يفيض ، وسيف يسل\nقسيم المحيا ، ضحوك السماح ، … لطيف الحوار ، أديب الجدل\nتوشى ، البلاغة ، أقلامه ، … إذا ما الضمير عليها أمل\nبيان يبين ، للسامعي … ن ، أن من السحر ما يستحل\nألا هل سبيل إلى العيب فيه ، … فكم عين ، من قبله ، من كمل\nلئن لبس الملك رحب الملا … ء ، فاختال منه بذيل رفل\nفإن تزوده للمعالي ؛ … وإن تأهبه للأجل\nفيا خير سواس هذي الأمور ، … وناسك أرباب هذي الدول\nوليت الثغور ، فلم تعد أن … رأبت الثأى ، وسددت الخلل\nسواك ، إذا قلد الأمر ، جار ، … وغيرك ، إن ملك الفيء ، غل\nحمى لا يزال ، لمن حله ، … أمانان : من عدم ، أو وجل\nفأنجم دهرهم سعدة ؛ … وشمس زمانهم في الحمل\nأبا بكر ! اسمع أحاديث لو … تبث بسمع عليل أبل\nسأشكر أنك أعليتني … بأحظى مكان ، وأدنى محل\nوأني إن زرت لم تحتجب ؛ … وإن طال بي مجلس لم تمل\nتبسمت ثم ثنيت الوساد ، … فحسبي من خطر ما أجل\nفلو صافح التبر خدي لهان ؛ … ولو كاثر القطر شكري لقل\nبأمثالها يسترق الكريم ، … إذا مطمع بسواه أخل\nفلا تعدمنك المساعي ، التي … لأم المناويك فيها الهبل\nفأنت الجريء ، إذا الشبل هاب ، … وأنت الدليل ، إذا النجم ضل\nوما ابنك إلا جلاء العيون ، … إذا ناظر بسواه ، اكتحل\nربيب السيادة ، في حجرها ، … تدر له ثديها ، إذ حفل\nتمكن يتلوك ، في الصالحات ، … فلما تفته ، ولما ينل"},{"id":"diwan-zaydun:106","bookId":"diwan-zaydun","type":"poem","seq":106,"chapter":"البحر: طويل","title":"سل المعشر الأعداء إن رمت صرفهم","page":"","text":"سل المعشر الأعداء إن رمت صرفهم … عن القصد ، إن أعياك منه مرام\nأتوك كآساد الشرى فرددتهم ، … كما أجفلت ، وسط الفلاة ، نعام\nمضوا يسألون الناس عما وراءهم … فيخبرهم ، بالمبكيات ، عصام\nوما ضاق عنهم جانب العذر ، إنهم … كمثل القطا ، لو يتركون لناموا\nفداء ، لباديس ، النفوس ، وجاده … من الشكر ، في أفق الوفاء ، غمام\nفما لحقت ، تلك العهود ، ملامة ؛ … ولا ذم ، من ذاك الحفاظ ، ذمام\nومثلك والى مثله ، فتصافيا ، … كما صافت ، الماء القراح ، مدام\nرسيلك ، في شأو المعالي ، كلاكما … بعيد المدى ، صعب الهموم ، همام\nلعمري ! لقد أحظيته بوفادة … لأسنى كريم ، أنجبته كرام\nفما انفك إلا عدل نفسك إن يسر … فللجسم لا للنفس منك مقام\nحسامك مهما تخترطه لمثلها ، … فقل غناء السيف ، حين يشام"},{"id":"diwan-zaydun:107","bookId":"diwan-zaydun","type":"poem","seq":107,"chapter":"البحر: رمل تام","title":"كم لريح الغرب من عرف ندي ،","page":"","text":"كم لريح الغرب من عرف ندي ، … كالشراب العذب في نفس الصدي\nحيث عباد فتى المجد ، الذي … نصت الدنيا به نص الهدي\nملك راحته بحر الندى ، … مثلما غرته بدر الندي\nأصبحت دولته ، في عصرنا ، … كفرند عاد في سيف صدي"},{"id":"diwan-zaydun:108","bookId":"diwan-zaydun","type":"poem","seq":108,"chapter":"البحر: رمل تام","title":"أسقيط الطل فوق النرجس ،","page":"","text":"أسقيط الطل فوق النرجس ، … أم نسيم الروض تحت الحندس ؟\nأم نظام للآل نسق ، … جامع كل خطير منفس\nأم قريض جاءني عن ملك ، … مالك بالبر رق الأنفس\nدلهت فكري ، من إبداعه ، … حيرة في منطق لي مخرس\nبت منه بين سهل مطمع ، … خادع ، يتلى بحزن مؤيس\nيا ندى يمنى أبي القاسم غم ؛ … يا سنا شمس المحيا أشمس\nيا بهيج الخلق العذب ابتسم ؛ … يا مهيج الأنف الصعب اعبس\nيا جمال الموكب الغادي ، إذا … سار فيه ، يا بهاء المجلس\nأنت لم يقنعك أن ألبستني … نعمة ، تذكر عهد السندس\nفتلطفت لأن حليتني ، … موليا طولي محلى ملبس\nداك تنويه ثناني فخره ، … سامي اللحظ أشم المعطس\nشرفت بكر المعالي خطبة … منك ، فانعم بسرور المعرس\nتمنح التأبيد ، يجلى لك عن … ظفر حلو وعز أقعس\nوارتشف معسول نصر أشنب ، … تجتنيه من عجاج ألعس\nوارتفق بالسعد في دست المنى ، … تصبح الصنع دهاق الأكؤس\nفاعتراض الدهر ، فيما شئته ، … مرتقى ، في صدره ، لم يهجس"},{"id":"diwan-zaydun:109","bookId":"diwan-zaydun","type":"poem","seq":109,"chapter":"البحر: طويل","title":"رضاك لنا ، قبل الطهور ، مطهر ؛","page":"","text":"رضاك لنا ، قبل الطهور ، مطهر ؛ … وقربك ، من دون البخور ، معطر\nفلو عز حمام لأدفأنا ذرى ، … يفيض به ماء الندى المتفجر\nولو لم يكن طيب لأغنت حفاوة … تمسك منها حالنا ، وتعنبر\nفلا فارق الدنيا سناء مقدس … بعيشك فيها ، أو ثناء مجمر\nودمت ملقى ، كل يوم ، صبيحة ، … يغاديك فيها ، بالفتوح ، مبشر"},{"id":"diwan-zaydun:110","bookId":"diwan-zaydun","type":"poem","seq":110,"chapter":"البحر: متقارب تام","title":"أمولاي بلغت أقصى الأمل ،","page":"","text":"أمولاي بلغت أقصى الأمل ، … وسوغت دأبا نساء الأجل\nوعمرت ، ما شئت ، في دولة … تقصر عنها طوال الدول\nفأنت الذي غر أفعاله … تحلى بها الدهر ، بعد العطل\nيشرف ، مملوكك المسترق ، … نظم من الكلم المنتخل\nوراح تعيد ، إلى من أسن ، … طيب زمان الصبا المقتبل\nفأخجلني البر من فرطه ، … وإن الجواب ليبدي الخجل\nوقد يقبل ، الدهر ، مولى الأنا … م جهد العبيد ، إذا ما أقل\nسعدت كما سعد المشتري ؛ … ونلت علا لم ينلها زحل"},{"id":"diwan-zaydun:111","bookId":"diwan-zaydun","type":"poem","seq":111,"chapter":"البحر: متقارب تام","title":"أفاض سماحك بحر الندى ؛","page":"","text":"أفاض سماحك بحر الندى ؛ … وأقبس هديك نور الهدى\nورد ، الشباب ، اعتلافك ، بعد … مفارقتي ظله الأبردا\nوما زال رأيك ، في ، الجميل ، … يفتح لي الأمل الموصدا\nوحسبي من خالد الفخر أن … رضيت قبولي ، مستعبدا\nويا فرط بأوي ، إذا ما طلعت ، … فقمت أقبل تلك اليدا\nورددت لحظي في غرة ، … إذا اجتليت شفت الأرمدا\nوطاعة أمرك فرض أرا … ه من كل مفترض ، أوكدا\nهي الشرع أصبح دين الضمير ، … فلو قد عصاك لقد ألحدا\nوحاشاي من أن أضل الصراط ، … فيعدوني الكفر عما بدا\nوأخلف موعد من لا أرى … لدهري ، إلا به ، موعدا\nأتاني عتاب متى أدكر … ه ، في نشوات الكرى ، أسهدا\nوإن كان أعقبه ما اقتضى … شفاء السقام ، ونقع الصدى\nثناء ثنى ، في سناء المح … ل ، زهر الكواكب لي حسدا\nقريض متى أبغ للقرض منه … أداء أجد شأوه أبعدا\nلو الشمس ، من نظمه ، حليت ، … أو البدر قام له منشدا\nلضاعف ، من شرف النيري … ين ، حظا به قارن الأسعدا\nفديتك مولى : إذا ما عثرت … أقال ، ومهما أزغ أرشدا\nركنت إلى كرم الصفح منه ، … فآمنني ذاك أن يحقدا\nوآنست سوق احتمال أبى … لمستبضع العذر أن يكسدا\nشفيعي إليه هوى مخلص ، … كما أخلص السابك العسجدا\nومن وصلي هجرة لا أعد ، … لحالي ، سوى يومها مولدا\nونعمى ، تفيأتها أيكة ، … فشكري حمام بها غردا\nتبارك من جمع الخير فيك ، … وأشعرك الخلق الأمجدا\nمضاء الجنان ، وظرف اللسان ، … وجود البنان بسكب الجدا\nرأى شيمتيك لما تستحق ، … وقفى ، فأظفر إذ أيدا\nليهنك أنك أزكى الملوك … بفيء ، وأشرفهم سوددا\nسوى ناجل لك سامي الهمو … م ، داني الفواضل ، نائي المدى\nهمام أغر ، رويت الفخار … حديثا ، إلى سروه مسندا\nسلكت إلى المجد منهاجه ، … فقد طابق الأطرف الأتلدا\nهو الليث قلد منك النجاد ، … ليوم الوغى ، شبله الأنجدا\nيعدك صارم عزم ورأي ، … فترضيه جرد أو أغمدا\nوما استبهم القفل في الحادثا … ت ، إلا رآك له مقلدا\nفأمطاك منكب طرف النجوم ؛ … وأوطأ أخمصك الفرقدا\nفلا زلتما ، يرفع الأوليا … ء ملككما ، ويحط العدا\nونفسي لنفسيكما البرتي … ن ، من كل ما يتوقى ، الفدا\nفمن قال : أن لستما أوحدي … ن في الصالحات ، فما وحدا"},{"id":"diwan-zaydun:112","bookId":"diwan-zaydun","type":"poem","seq":112,"chapter":"البحر: رمل تام","title":"أيها الظافر أبشر بالظفر ؛","page":"","text":"أيها الظافر أبشر بالظفر ؛ … واجتل التأييد في أبهى الصور\nوتفيأ ظل سعد ، تجتني … فيه ، من غرس المنى ، أحلى الثمر\nورد الصبح ، فكم مستوحش ، … غرض منك إلى أنس الصدر\nكان من قربك في عيش ند ، … عطر الآصال ، وضاح البكر\nكلما شاء تأتى أن يرى … خلق البرجيس ، في خلق القمر\nفثوى دونك مثوى قلق ، … يشتكي من ليله مطل السحر\nقل لساقينا : يحز أكؤسه ؛ … ولشادينا : يصل قطع الوتر\nحسبنا سكر جنته ذكر ، … دونه السكر الذي يجني السكر\nلم يغادر لي سقامي جلدا ، … مع أني لم أزل ثبت المرر\nأيها الماشي البراز ، المنبري … لزماني ، إن مشى نحوي الخمر\nوالذي إن سيم ما فوق الرضى ، … وجد الألوى البعيد المستمر\nوإذا أعتب في معتبة ، … لان منه جانب السمح اليسر\nنظمي المهدى إلى أبرع من … نظم السحر بيانا ، أو نثر\nلي فيه المثل السائر عن … جالب التمر إلى أرض هجر\nغير أن العذر رسم واضح ، … تنفث الشكوى إذا الشوق صدر\nثم قد وفق عبد ، عظمت … نعمة المولى عليه ، فشكر\nلا عدا حظك إقبال ترى … قاضيا ، أثناءه ، كل وطر\nواصطبح كأس الرضى من ملك … سرت في إرضائه أزكى السير\nحين صممت إلى أعدائه ، … فانتحتهم منك صماء الغير\nفاض غمر للندى من فوقهم ، … كان يروي شربهم منه الغمر\nسبق الناس ، فصلى منك من … إن رأى آثاره الزهر اقتفر\nزنتما الأيام ، إذ ملككما … سال ، في أوجهها ، سيل الغرر\nفابقيا في دولة قادرة ، … بعض حراس نواحيها القدر\nمستذلي من طغى ، مستأصلي … شأفة الباغي ، مقيلي من عثر\nعلمي من ضل ، مزني من شكا … خلة الإمحال ، بدري من نظر\nتضحك الأزمن ، عن علياكما ، … ضحك الروضة عن ثغر الزهر"},{"id":"diwan-zaydun:113","bookId":"diwan-zaydun","type":"poem","seq":113,"chapter":"البحر: مجزوء الكامل","title":"هل يشكرن أبو الوليد","page":"","text":"هل يشكرن أبو الوليد … إدناءك الأمل البعيد\nأو أن تسوغ نعمة … للدهر ، أسهرت الحسود\nإن لم يدن بنصيحة … ترضيك ، فهو من اليهود\nلا زلت رافع راية ، … تضحي السعود لها جنود"},{"id":"diwan-zaydun:114","bookId":"diwan-zaydun","type":"poem","seq":114,"chapter":"البحر: متقارب تام","title":"يقصر قربك ليلي الطويلا ؛","page":"","text":"يقصر قربك ليلي الطويلا ؛ … ويشفي وصالك قلبي العليلا\nوإن عصفت منك ريح الصدود ، … فقدت نسيم الحياة البليلا\nكما أنني ، إن أطلت العثار ، … ولم يبد عذري وجها جميلا\nوجدت أبا القاسم الظافر ، ال … مؤيد بالله ، مولى مقيلا\nإذا ما نداه همى والحيا … شآه ، كشأو الجواد البخيلا\nوأقلامه وفق أسيافه ، … يظل الصرير يباري الصليلا"},{"id":"diwan-zaydun:115","bookId":"diwan-zaydun","type":"poem","seq":115,"chapter":"البحر: مجزوء الكامل","title":"أنت المسبب للولوع ،","page":"","text":"أنت المسبب للولوع ، … ومثير كامنة الدموع\nيتمنيان لو اعفيا ، … مهما طلعت ، من الطلوع\nوالظافر الملك المؤي … د واحد ، عدل الجموع\nالبدر في سحب البرو … د ، الليث في لبد الدروع\nعنت الأصول لأصله ، … وتقاصرت عنه الفروع"},{"id":"diwan-zaydun:116","bookId":"diwan-zaydun","type":"poem","seq":116,"chapter":"البحر: بسيط تام","title":"أبا الوليد ، وما شطت بنا الدار ،","page":"","text":"أبا الوليد ، وما شطت بنا الدار ، … وقل منا ومنك اليوم زوار\nوبيننا كل ما تدريه من ذمم ، … وللصبا ورق خضر ونوار\nوكل عتب وإعتاب جرى ، فله … مواقع حلوة ، عندي ، وآثار\nفأذكر أخاك بخير ، كلما لعبت … به الليالي ، فإن الدهر دوار"},{"id":"diwan-zaydun:117","bookId":"diwan-zaydun","type":"poem","seq":117,"chapter":"البحر: بسيط تام","title":"لو أنني لك في الأهواء مختار ،","page":"","text":"لو أنني لك في الأهواء مختار ، … لما جرت بالذي تشكوه أقدار\nلكنها فتن ، في مثل غيهبها … تعمى البصائر ، إن لم تعم أبصار\nفأحسن الظن ، لا ترتب بعهد فتى ، … تعفو العهود وتبقى منه آثار\nلو كان يعطى المنى في الأمر يمكنه … لما أغبك ، يوما ، منه زوار\nفلا يريبنك ، في ذكر الصديق به ، … من ليس يجهل أن الدهر دوار"},{"id":"diwan-zaydun:118","bookId":"diwan-zaydun","type":"poem","seq":118,"chapter":"البحر: وافر تام","title":"تباعدنا ، على قرب الجوار ،","page":"","text":"تباعدنا ، على قرب الجوار ، … كأنا صدنا شحط المزار\nتطلع لي هلال الهجر بدرا ، … وصار هلال وصلك في سرار\nوشاع شنيع وصلك لي وهجري ، … فهلا كان ذلك في استتار ؟\nأيجمل أن ترى عني صبورا ، … وأصبح مولعا دون اصطبار\nولما أن هجرت ، وطال غفري … عقرت هموم نفسي بالعقار\nوكنت أزيد سمعك من عتابي ، … ولكن عاقني قرب الخمار\nفراع مودتي ، واحفظ جواري … فإن الله أوصى بالجوار\nوزرني منعما ، من غير أمر … وآنس موحشا من عقر دار"},{"id":"diwan-zaydun:119","bookId":"diwan-zaydun","type":"poem","seq":119,"chapter":"البحر: وافر تام","title":"هواي ، وإن تناءت عنك داري ،","page":"","text":"هواي ، وإن تناءت عنك داري ، … كمثل هواي في حال الجوار\nمقيم ، لا تغيره عواد ، … تباعد بين أحيان المزار\nرأيتك قلت : إن الوصل بدر ؛ … متى خلت البدور من السرار ؟\nورابك أنني جلد صبور ؛ … وكم صبر يكون عن اصطبار\nولم أهجر لعتب ، غير أني … أضرت بي معاقرة العقار\nوأنا لخمر ، ليس لها خمار ، … تبرح بي ، فكيف مع الخمار ؟\nوهل أنسى لديك نعيم عيش ، … كوشي الخد ، طرز بالعذار ؟\nوساعات يجول اللهو فيها … مجال الطل في حدق البهار ؟\nوإن يك قر عنك اليوم جسمي ، … فديت ، فما لقلبي من قرار !\nوكنت على البعاد أجل علق … لدي ، فكيف إذ أصبحت جاري ؟"},{"id":"diwan-zaydun:120","bookId":"diwan-zaydun","type":"poem","seq":120,"chapter":"البحر: سريع","title":"طابت لنا ليلتنا الخاليه ؛","page":"","text":"طابت لنا ليلتنا الخاليه ؛ … فلتنسناها هذه التاليه !\nأبا المعالي ! نحن في راحة ، … فانقل إلينا القدم العاليه\nليلتنا عاطلة ، إن تغب … عنا ، فزرنا كي ترى حاليه\nأنت الذي ، لو تشترى ساعة … منه بدهر ، لم تكن غاليه"},{"id":"diwan-zaydun:121","bookId":"diwan-zaydun","type":"poem","seq":121,"chapter":"البحر: طويل","title":"بنى جهور ! أحرقتم بجفائكم","page":"","text":"بنى جهور ! أحرقتم بجفائكم … جناني ، ولكن المدائح تعبق\nتعدونني كالعنبر الورد ، إنما … تطيب لكم أنفاسه حين يحرق !"},{"id":"diwan-zaydun:122","bookId":"diwan-zaydun","type":"poem","seq":122,"chapter":"البحر: كامل تام","title":"قل للوزير ، وقد قطعت بمدحه","page":"","text":"قل للوزير ، وقد قطعت بمدحه … زمني ، فكان السجن منه ثوابي :\nلا تخش في حقي بما أمضيته … من ذاك في ، ولا توق عتابي\nلم تخط في أمري الصواب موفقا … هذا جزاء الشاعر الكذاب !"},{"id":"diwan-zaydun:123","bookId":"diwan-zaydun","type":"poem","seq":123,"chapter":"البحر: مجزوء الوافر","title":"أصخ لمقالتي ، واسمع ؛","page":"","text":"أصخ لمقالتي ، واسمع ؛ … وخذ ، فيما ترى ، أو دع\nوأقصر ، بعدها ، أو زد ؛ … وطر ، في إثرها ، أوقع\nألم تعلم بأن الده … ر يعطي ، بعدما يمنع ؟\nوأن السعي قد يكدي ؛ … وأن الظن قد يخدع ؟\nوكم ضر امرأ أمر ، … توهم أنه ينفع ؟\nفإن يجدب ، من الدنيا ، … جناب طالما أمرع\nفما إن غاض لي صبر ؛ … وما إن فاض لي مدمع\nوكائن رامت الأيا … م ترويعي ، فلم أرتع\nإذا صابتني الجلى ، … تجلت عن فتى أروع\nعلى ما فات لا يأسى ؛ … ومما ناب لا يجزع\nتدب إلي ، ما تألو ، … عقارب ما تني تلسع\nكأنا لم ؤالفنا … زمان لين الأخدع\nإذ الدنيا ، متى نقتد … أبي سرورها يتبع\nوإذ للحظ إقبال ؛ … وإذ في العيش مستمتع\nوإذ أوتارنا تهفو ؛ … وإذ أقداحنا تترع\nوأوطار المنى تقضى ؛ … وأسباب الهوى تشفع\nفمن أدمانة تعطو ؛ … ومن قمرية تسجع\nأعد نظرا ، فإن البغ … ي مما لم يزل يصرع\nولا تطع التي تغوي … ك ، فهي لغيهم أطوع\nتقبل إن أتى خطب ، … وأنف الفحل لا يقرع\nولا تك منك تلك الدا … ر بالمرأى ، ولا المسمع\nفإن قصارك الدهلي … ز ، حين سواك في المضجع"},{"id":"diwan-zaydun:124","bookId":"diwan-zaydun","type":"poem","seq":124,"chapter":"البحر: طويل","title":"ولما التقينا للوداع غدية ،","page":"","text":"ولما التقينا للوداع غدية ، … وقد خففت ، في ساحة القصر ، رايات\nوقرنت الجرد العتاق ، وصفقت … طبول ، ولاحت للفراق علامات\nبكينا دما ، حتى كأن عيوننا ، … لجري الدموع الحمر ، فيها جراحات\nوكنا نرجي الأوب ، بعد ثلاثة ؛ … فكيف ، وقد كانت عليها زيادات !"},{"id":"diwan-zaydun:125","bookId":"diwan-zaydun","type":"poem","seq":125,"chapter":"البحر: متقارب تام","title":"أتتك بلون المحب الحجل ،","page":"","text":"أتتك بلون المحب الحجل ، … تخالط لون المحب الوجل\nثمار ، تضمن إدراكها … هواء ، أحاط بها معتدل\nتأتى لإلطاف تدريجها ، … فمن حر شمس إلى برد ظل\nإلى أن تناهت شفاء العليل ، … وأنس المشوق ، ولهو الغزل\nفلو تجمد الراح لم تعدها ؛ … وإن هي ذابت فخمر تحل\nلها منظر حسن في العيون ، … كدنياك لكنه منتقل\nوطعم يلذ لمن ذاقه ، … كلذة ذكراكن لو لم يمل\nوريا ، إذا نفحت خلتها … تمل ثناءك ، أو تستهل\nيمثل ملمسها ، للأكف ، … لين زمانك أو يمتثل\nصفوت ، فأدللت في عرضها ؛ … ومن يصف منه الهوى فليدل\nقبولكها نعمة غضة ، … وفضل ، بما قبله ، متصل\nولو كنت أهديت نفسي اختصر … ت ، على أنها غاية المحتفل"},{"id":"diwan-zaydun:126","bookId":"diwan-zaydun","type":"poem","seq":126,"chapter":"البحر: مجزوء الخفيف","title":"خنت عهدي ، ولم أخن ؛","page":"","text":"خنت عهدي ، ولم أخن ؛ … بعت ودي بلا ثمن\nقائلا : هل مزايد … رابحا ؟ ثم من يزن ؟\nعدتي كنت للزما … ن ، فقد حلت والزمن\nأرخص البيع كيف شئ … ت ، وذرني لتندمن\nسوف تبلى بغيرنا ، … جرب الناس وامتحن"},{"id":"diwan-zaydun:127","bookId":"diwan-zaydun","type":"poem","seq":127,"chapter":"البحر: مجزوء الرمل","title":"لا افتنان كافتناني","page":"","text":"لا افتنان كافتناني … في حلى الظرف الحسان\nخصني بالأدب الله ، … فأعلى فيه شاني\nخاطري أنفد ، مهما … قيس ، من حد السنان\nأيهضا المرسل أطيا … ر المعمى لامتحاني\nهاك ، كي تزداد ، في الآ … داب ، علما بمكاني\nقد أتتنا الطير تشدو … بعض أبيات الأغاني\nبرطانات ، قضتنا … ما اقتضتنا من بيان\nإن تغنى البلبل اهتا … ج غناء الورشان\nفتأدى منه بيتا … غزل منفردان\nلمحب في حبيب ، … عنه ناء منه دان\nيا بعيد الدار ، موصو … لا بقلبي ولساني\nربما باعدك الده … ر ، فأدنتك الأماني"},{"id":"diwan-zaydun:128","bookId":"diwan-zaydun","type":"poem","seq":128,"chapter":"البحر: مجزوء الكامل","title":"يا من تزينت الريا","page":"","text":"يا من تزينت الريا … سة حين ألبس ثوبها\nوله يد يئس الغما … م من أن يعارض صوبها\nجاءتك جامدة المدا … م ، فخذ عليها ذوبها"},{"id":"diwan-zaydun:129","bookId":"diwan-zaydun","type":"poem","seq":129,"chapter":"البحر: منسرح","title":"قد أحسن الله في الذي صنعه ،","page":"","text":"قد أحسن الله في الذي صنعه ، … عارض كرب بلطفه رفعه\nتبارك الله ! إن عادة حس … ناه ، مع الشكر ، غير منتزعه\nيا سيدي المستبد من مقتي ، … بخطة فاتت الحساب سعه\nوافاني العقد ، زين ناظمه ، … والوشي لا راع حادث صنعه\nبثثت فيه البديع منتقيا ، … كالروض إذ بث ، في الربى ، قطعه\nأزاح كرب الدواء مطلعه ، … لما بدا طالع السرور معه\nكم دعوة ، قد حواه ، صالحة ، … من أملي أن تكون مستمعه\nجملة ما نفسك السرية من حا … لي ، إلى علم كنهه ، طلعه\nأن الدواء التذت عواقبه … مني نفس ، تبشعت جرعه\nفالحمد لله ، لا شريك له ، … إن بدأ الطول ، منعما ، شفعه"},{"id":"diwan-zaydun:130","bookId":"diwan-zaydun","type":"poem","seq":130,"chapter":"البحر: كامل تام","title":"أخطب ، فملكك يفقد الإملاكا ؛","page":"","text":"أخطب ، فملكك يفقد الإملاكا ؛ … واطلب ، فسعدك يضمن الإدراكا\nوصل النجوم بحظ من لو رامها … هجرت إليه زهرها الأفلاكا\nواستهد ، من أحمى مراتعها ، المها ، … فالصعب يسمح في عنان هواكا\nيا أيها الملك ، الذي تدبيره … أضحى ، لملكة الزمان ، ملاكا\nهذي الليالي بالأماني سمحة ، … فمتى تقل : هاتي ! تقل لك : هاكا\nفاعقل شواردها ، إزاء عقيلة ، … وافت مبشرة بنيل مناكا\nأهدى الزمان إليك منها تحفة ، … لم تعد أن قرت بها عيناكا\nشمس توارت ، في ظلام مضيعة ، … ثم استطار لها السنا بسناكا\nقرنت ببدر التم ، كافلة له … أن سوف تتبع فرقدين سماكا\nهي والفقيدة ، كالأديم اخترته ، … فقددت إذ خلق الشراك شراكا\nفاصفح عن الرزء المعاود ذكره ؛ … واستأنف النعمى فتلك بذاكا\nلم يبق عذر في تقسم خاطر ، … إلا الصبابة ، من دماء عداكا\nكفار أنعمك ، الألى حليتهم … أطواقهم ، سيطوقون ظباكا\nأعرض عن الخطرات ، إنك إن تشأ … تكن النجوم أسنة لقناكا\nهصر النعيم بعطف دهرك فانثنى ، … وجرى الفرند بصفحتي دنياكا\nوبدا زمانك لابسا ديباجة ، … تجلو ، لعين المجتلي ، سيماكا\nدنيا لزهرتها شعاع مذهب ، … لو كان وصفا كان بعض حلاكا\nفتمل في فرش الكرامة ناعما ؛ … واعقد بمرتبة السرور حباكا\nوأطل ، إلى شدو القيان ، إصاخة ؛ … وتلق مترعة الكؤوس دراكا\nتحتثها ، مثنى مثاني غادة ، … شفعت بحث غنائها الإمساكا\nما العيش إلا في الصبوح بسحرة ، … قد جاسدت أنوارها الأحلاكا\nلك أريحية ماجد ، إن تعترض … في لهو راحك ، تستهل لهاكا\nمن كان يعلق ، في خلال ندامه ، … ذم ببعض خلاله ، فخلاكا\nأسبوع أنس ، محدث لي وحشة ، … علما بأني فيه لست أراكا\nفأنا المعذب ، غير أني مشعر … ثقة بأنك ناعم ، فهناكا\nإني أقوم بشكر طولك ، بعدما … ملأت من الدنيا يدي يداكا\nبردت ظلال ذراك ، واحلولى جنى … نعماك لي ، وصفت جمام نداكا\nوأمنت عادية العدا الأقتال مذ … أعصمت في أعلى يفاع حماكا\nجهد المقل نصيحة ممحوضة … أفردت مهديها ، فلا إشراكا\nوثناء محتفل ، كأن ثناءه … مسك ، بأردان المحافل صاكا\nولتدعني ، وعدوك الشاني ، فإن … يرم القراع يجد سلاحي شاكا\nلا تعدمن الحظ غرسا ، مطلعا … ثمر الفوائد ، دانيا لجناكا\nوالنصر جارا لا يحاول نقلة ؛ … والصنع رهنا ، لا يريد فكاكا\nوإذا غمام السعد أصبح صوبه … درك المطالب ، فليصل سقياكا\nفالدهر معترف بأنا لم نكن … لنسر منه ، بساعة ، لولاكا"},{"id":"diwan-zaydun:131","bookId":"diwan-zaydun","type":"poem","seq":131,"chapter":"البحر: طويل","title":"وليل أدمنا فيه شرب مدامة ،","page":"","text":"وليل أدمنا فيه شرب مدامة ، … إلى أن بدا للصبح ، في الليل ، تأثير\nوجاءت نجوم الصبح تضرب في الدجى … فولت نجوم الليل ، والليل مقهور\nفحزنا من اللذات أطيب طيبها ، … ولم يعرنا هم ، ولا عاق تكدير\nخلا أنه ، لو طال ، دامت مسرني ، … ولكن ليالي الوصل ، فيهن تقصير"},{"id":"diwan-zaydun:132","bookId":"diwan-zaydun","type":"poem","seq":132,"chapter":"البحر: خفيف تام","title":"لست من بابة الملوك أبا ال","page":"","text":"لست من بابة الملوك أبا ال … عباس دعهم فشأنهم غير شانك\nما جزاء الوزير منك ، إذا اخ … تصك ، أن تستمر في إدمانك\nأتراه لا يستريب لإمسا … كك سرد العراق تحت لسانك\nمذ نهانا ، عن المدام ، انتهينا ، … مع أنا نعد من صبيانك"},{"id":"diwan-zaydun:133","bookId":"diwan-zaydun","type":"poem","seq":133,"chapter":"البحر: مجزوء الخفيف","title":"دونك الراح جامده ،","page":"","text":"دونك الراح جامده ، … وفدت خير وافده\nوجدت سوق ذوبها ، … عند تقواك ، كاسده\nفاستحالت إلى الجمو … د ، وجاءت مكايده"},{"id":"diwan-zaydun:134","bookId":"diwan-zaydun","type":"poem","seq":134,"chapter":"البحر: مجزوء الكامل","title":"جاءتك وافدة الشمول ،","page":"","text":"جاءتك وافدة الشمول ، … في المنظر الحسن ، الجميل\nلم تحظ ، ذائبة ، لدي … ك ، ولم تنل حظ القبول\nفتجامدت ، محتالة ، … والمرء يعجز لا الحويل\nلولا انقلاب العين س … دت ، دون بغيتها ، السبيل\nلهجرتها صفراء في … بيضاء ، هاجرها قليل\nالكأس من رأد الضحى ؛ … والراح من طفل الأصيل\nآثرت عائدة التقى ، … ورغبت في الأجر الجزيل\nيا أيها الملك ، الذي … ما في الملوك له عديل\nيا ماء مزن ، يا شها … ب دجنة ، يا ليث غيل\nيا من عجبنا أن يجو … د ، بمثله ، الزمن البخيل\nبشراك دنيا غضة ، … في ظل إقبال ظليل\nرقت ، كما سال العذا … ر بجانب الخد الأسيل\nوتأودت ، كالغصن قا … بل عطفه ، نفس القبول\nيصبي مقبلها الشه … ي ولحظها الساجي العليل\nفتملها في العزة ال … قعساء ، والعمر الطويل"},{"id":"diwan-zaydun:135","bookId":"diwan-zaydun","type":"poem","seq":135,"chapter":"البحر: كامل تام","title":"الدهر ، إن أملى ، فصيح أعجم ،","page":"","text":"الدهر ، إن أملى ، فصيح أعجم ، … يعطي اعتباري ما جهلت ، فأعلم\nإن الذي قدر الحوادث قدرها ، … ساوى لديه الشهد منها العلقم\nولقد نظرت ، فلا اغتراب يقتضي … كدر المآل ، ولا توق يعصم\nكم قاعد يحظى ، فتعجب حاله ، … من جاهد يصل الدؤوب ، فيحرم\nوأرى المساعي كالسيوف تبادرت … شأو المضاء ، فمنثن ومصمم\nولكم تسامى ، بالرفيع نصابه ، … خطر ، فناصبه الوضيع الألأم\nوأشد فاجعة الدواهي محسن … يسعى ، ليعلقه الجريمة مجرم\nتلقى الحسود أصم عن جرس الوفا ، … ولقد يصيخ ، إلى الرقاة ، الأرقم\nقل للبغاة المنبضين قسيهم : … سترون من تصميه تلك الأسهم\nأسررتم ، فرأى ، نجي عيوبكم ، … شيحان ، مدلول عليها ، ملهم\nوعبأتم للفسق ظفر سعاية … لم يعدكم أن رد ، وهو مقلم\nونبذتم التقوى وراء ظهوركم ، … فغدا ، بغيضكم ، التقي الأكرم\nما كان حلم محمد ليحيله … عن عهده دغل الضمير ، مذمم\nملك تطلع للنواظر غرة ، … زهراء ، يبديها الزمان الأدهم\nيغشى النواظر من جهير روائه ، … خلق ، يرى ملء الصدور ، مطهم\nوسنا جبين يستطير شعاعه ، … يغني ، عن القمرين ، من يتوسم\nصلت ، تود الشمس لو صيغت له … تاجا ، ترصع جانبيه الأنجم\nفضحت محاسنه الرياض بكى الحيا … وهنا عليها ، فاغتدت تتبسم\nبالقدر يبعد ، والتواضع يدني ، … والبشر يشمس ، والندى يتغيم\nجذلان ، في يوم الوغى ، متطلق … وجها إليها ، والردى متجهم\nبأس ، كما صال الهزبر ، إزاءه … جود ، كما جاش الخضم الخضرم\nنفسي فداؤك ، أيها الملك ، الذي … كل الملوك له ، العلاء ، تسلم\nسدت الجميع ، فليس منهم منكر ، … أن صرت فذهم الذي لا يتأم\nلا غرو ، أم المجد ، في بكر الحجى … من أن يضاف إليك صنو ، أعقم\nفاحسم دواعي كل شر دونه ؛ … فالداء يسري ، إن عدا ، لا يحسم\nكم سقط زند قد نما ، حتى غدا … بركان نار ، كل شيء تحطم\nوكذلك السيل الجحاف ، فإنما … أولاه طل ، ثم وبل يثجم\nوالمال يخرج أهله عن حدهم ؛ … وافهم فإنك بالبواطن أفهم\nواذكر صنيع أبيك ، أول أمره ، … في كل متهم ، فإنك تعلم\nلم يبق منهم من توقع شره ، … فصفت له الدنيا ، ولذ المطعم\nفعلام تنكل عن صنيع مثله ؛ … ولأنت أمضى في الخطوب ، وأشهم\nوجنابك الثبت ، الذي لا ينثني ؛ … وحسامك العضب ، الذي لا يكهم\nوالحال أوسع ، والعوالي جمة ؛ … والمجد أشمخ ، والصريمة أصرم\nلا تتركن للناس موضع شبهة ، … واحزم ، فمثلك في العظائم أحزم\nقد قال شاعر كندة ، فيما مضى ، … بيتا على مر الليالي يعلم :\nلا يسلم الشرف الرفيع من الأذى … حتى يراق على جوانبه الدم\nفرق عوت ، فزأرت زأرة زاجر ، … راع الكليب بها السبنتى الضيغم\nيا ليت شعري ! هل يعود سفيههم ، … أم قد حماه النبح ، ذاك ، المكعم ؟\nلي منك ، فليذب الحسود تلظيا ، … لطف المكانة ، والمحل الأكرم\nوشفوف حظ ، ليس يفتأ يجتلى … غض الشباب ، وكل حظ يهرم\nلم تلف صاغيتي ، لديك ، مضاعة ، … كلا ولا خفي اصطناعي الأقدم\nبل أوسعت حفظا ، وصدق رعاية ، … ذمم موثقة العرا ، لا تفصم\nفليخرقن الأرض شكر منجد … مني ، تناقله المحافل ، متهم\nعطر ، هو المسك السطوع ، يطيب في … شم العقول أريجه المتنسم\nوإذا غصون المكرمات تهدلت ، … كان ، الثناء ، هديلها المترنم\nالفخر ثغر ، عن حفاظك ، باسم ؛ … والمجد برد ، من وفائك ، معلم\nفاسلم مدى الدنيا ، فأنت جمالها ، … وتسوغ النعمى ، فإنك منعم"},{"id":"diwan-zaydun:136","bookId":"diwan-zaydun","type":"poem","seq":136,"chapter":"البحر: خفيف تام","title":"إن للأرض والسماء وللما","page":"","text":"إن للأرض والسماء وللما … ء علينا أذمة لا تذم\nهي بعض اسم من أحب ولاء ، … وبتكرير بعضها يستتم"},{"id":"diwan-zaydun:137","bookId":"diwan-zaydun","type":"poem","seq":137,"chapter":"البحر: منسرح","title":"أفدتني ، من نفائس الدرر ،","page":"","text":"أفدتني ، من نفائس الدرر ، … ما أبرزته غوائص الفكر\nمن لفظة قارنت نظيرتها ، … قران سقم الجفون للحور\nأبدعها خاطر ، بدائعه ، … في النظم ، حازت جلالة الخطر\nالعطر منها سرى له نفس ، … من نفس الروض ، رق في السحر\nيا راقم الوشي ، زانه ذهب ، … رقرق إذ رف منه في الطرر\nوناظم العقد ، نظم مقتدر ، … يفصل ، بين العيون ، بالغرر\nلي بالنضال ، الذي نشطت له ، … عهد قديم ، معجم الأثر\nهل أنصل السهم في الجفير ، وقد … تعطلت فوقه من الوتر\nما الشعر إلا لمن قريحته … غريضه النور ، غضه الثمر\nتبسم عن كل زاهر أرج ، … مثل الكمام ابتسمن عن زهر\nإن الشفيع الهمام ، سوغه الل … ه اتصال التأييد بالظفر\nالفاضل الخبر في الملوك ، إذا … قصر خبر عن غاية الخبر\nنجل الذي نصحه وطاعته … كالحج ، تتلوة بره العمر\nشاهد عهدي لك الصحيح ، بإخ … لاص نأى صفوه عن الكدر\nمشيت في عذلي البراز لمن … لم يرض ، في العذر ، مشية الخمر\nوقلت : مطل الغني ورد من ال … ظلم ، يلقى ملاوم الصدر\nولي معاذير ، لو تطلع في … ليلي سرار ، أغنت عن القمر\nمنها اتقائي لأن أكون أنا ال … جالب ، ما قلته ، إلى هجر\nلكن سيأتيك ما يجوزه … سروك ، دأب المسامح اليسر\nفاكتف منه بنظرة عنن ، … لا حظ فيه لكرة النظر"},{"id":"diwan-zaydun:138","bookId":"diwan-zaydun","type":"poem","seq":138,"chapter":"البحر: مجتث","title":"يا بانيا كل مجد ؛","page":"","text":"يا بانيا كل مجد ؛ … وهادما كل وجد\nجسم السرور سوي ، … من صوغ نعماك ، عندي\nفهب له روح راح ، … ينطق بأحفل حمد"},{"id":"diwan-zaydun:139","bookId":"diwan-zaydun","type":"poem","seq":139,"chapter":"البحر: خفيف تام","title":"قد بعثناه ينفع الأعضاء ،","page":"","text":"قد بعثناه ينفع الأعضاء ، … حين يجلو ، بلطفه ، السخناء\nجاء يزهى بمستشف رقيق ، … يخدع العين رقة وصفاء\nتنفذ العين منه في ظرف نور ، … ملأته أيدي الشموس ضياء\nأكسبته الأيام برد هواء ، … فهو جسم قد صيغ نارا وماء\nمنظر يبهج القلوب ، وطعم … تشكر النفس عهده استمراء\nلذة الوصل ناله ، بعد يأس ، … كلف طالما تشكى الجفاء\nيفضح الشهد طعمه ، كلما قي … س إليه ، ويخجل الصهباء\nفضل السابق المقدم ، في النض … ج ، فأزرى بطعمه إزراء\nغير أني بعثت هذا غذاء ، … يشتهيه الفتى ، وذاك دواء\nملطف يبرد المزاج ، إذا … جاش التهابا ، ويقمع الصفراء"},{"id":"diwan-zaydun:140","bookId":"diwan-zaydun","type":"poem","seq":140,"chapter":"البحر: سريع","title":"قل لأبي حفص ، ولم تكذب ،","page":"","text":"قل لأبي حفص ، ولم تكذب ، … يا قمر الديوان والموكب\nما لأبي صفوان ، مألوفنا ، … أبرق في الألفة عن خلب ؟\nولم يعد ، إلا كما يتقي ، … مسترق السمع ، من الكوكب ؟\nعنفه ، بالله ، على فعله ، … واشتم ، وإن لم يستقم ، فاضرب\nوعاطه صهباء مشمولة ، … يرى لها المشرق في المغرب\nوليشرب الأكثر من كأسه ، … واعمد إلى فضلته فاشرب\nعقوبة ، أحسن بها سنة ، … في مثله ، من حسن مذنب\nوباكرا الطيب ، وروحا له ، … فأنتما في زمن طيب"},{"id":"diwan-zaydun:141","bookId":"diwan-zaydun","type":"poem","seq":141,"chapter":"البحر: سريع","title":"أيتها النفس إليه اذهبي ،","page":"","text":"أيتها النفس إليه اذهبي ، … فما لقلبي عنه من مذهب\nمفضض الثغر له نقطة … من عنبر في خده المذهب\nأنساني التوبة من حبه … طلوعه شمسا من المغرب"},{"id":"diwan-zaydun:142","bookId":"diwan-zaydun","type":"poem","seq":142,"chapter":"البحر: طويل","title":"ألا هل لنا من بعد هذا التفرق","page":"","text":"ألا هل لنا من بعد هذا التفرق … سبيل فيشكو كل صب بما لقي ؟\nوقد كنت أوقات التزاور في الشتا … أبيت على جمر من الشوق محرق\nفكيف وقد أمسيت في حال قطعة … لقد عجل المقدار ما كنت أتقي\nتمر الليالي لا أرى البين ينقضي … ولا الصبر من رق التشوق معتقي"},{"id":"diwan-zaydun:143","bookId":"diwan-zaydun","type":"poem","seq":143,"chapter":"البحر: طويل","title":"لحا الله يوما لست فيه بملتق","page":"","text":"لحا الله يوما لست فيه بملتق … محياك من أجل النوى والتفرق\nوكيف يطيب العيش دون مسرة … وأي سرور للكئيب المؤرق ؟"},{"id":"diwan-zaydun:144","bookId":"diwan-zaydun","type":"poem","seq":144,"chapter":"البحر: خفيف تام","title":"قد علقنا سواك علقا نفيسا","page":"","text":"قد علقنا سواك علقا نفيسا … وصرفنا إليه عنك النفوسا\nولبسنا الجديد من خلع الح … ب ولم نأل أن خلعنا اللبيسا\nليس منك الهوى ولا أنت منه … اهبطي مصر أنت من قوم موسى"},{"id":"diwan-zaydun:145","bookId":"diwan-zaydun","type":"poem","seq":145,"chapter":"البحر: خفيف تام","title":"وبنفسي وإن أضر بنفسي","page":"","text":"وبنفسي وإن أضر بنفسي … قمر لا ينال منه السرار\nجال ماء النعيم منه بخد … فيه للمستشف نور ونار\nمتجن يحلو تجنيه عندي … فهو يجني ومني الإعتذار"},{"id":"diwan-zaydun:146","bookId":"diwan-zaydun","type":"poem","seq":146,"chapter":"البحر: خفيف تام","title":"أنا ظرف للهو كل ظريف","page":"","text":"أنا ظرف للهو كل ظريف … أنا مستودع لعلق شريف\nأنا كالصدر في الإحاطة بالرا … ح إذا الراح كالضمير اللطيف\nسل عن الطيبات فهي فنون … ألفت في أحسن التأليف\nأي حسن يفي بحسني محمو … لا بكفي وصفية أو وصيف"},{"id":"diwan-zaydun:147","bookId":"diwan-zaydun","type":"poem","seq":147,"chapter":"البحر: طويل","title":"لقد سرنا أن النعي موكل","page":"","text":"لقد سرنا أن النعي موكل … بطاغية قد حم منه حمام\nتجانب صوب المزن عن ذلك الصدى … ومر عليه الغيث وهو جهام"},{"id":"diwan-zaydun:148","bookId":"diwan-zaydun","type":"poem","seq":148,"chapter":"البحر: طويل","title":"وما ضربت عتبى لذنب أتت به","page":"","text":"وما ضربت عتبى لذنب أتت به … ولكنما ولادة تشتهي ضربي\nفقامت تجر الذيل عاثرة به … وتمسح طل الدمع بالعنم الرطب"},{"id":"diwan-zaydun:149","bookId":"diwan-zaydun","type":"poem","seq":149,"chapter":"البحر: بسيط تام","title":"عرفت عرف الصبا إذ هب عاطره","page":"","text":"عرفت عرف الصبا إذ هب عاطره … من أفق من أنا في قلبي أشاطره\nأراد تجديد ذكراه على شحط … وما تيقن أني الدهر ذاكره\nنأى المزار به والدار دانية … يا حبذا الفأل الو صحت زواجره\nخلي أبا الجيش هل يقضي اللقاء لنا … فيشتفي منك قلب أنت هاجره ؟\nقصاره قيصر إن قام مفتخرا … لله أوله مجدا وآخره"},{"id":"diwan-zaydun:150","bookId":"diwan-zaydun","type":"poem","seq":150,"chapter":"البحر: طويل","title":"كأن عشي القطر في شاطىء النهر","page":"","text":"كأن عشي القطر في شاطىء النهر … وقد زهرت فيه الأزاهر كالزهر\nترش بماء الورد رشا وتنثني … لتغليف أفواه بطيبة الخمر"},{"id":"diwan-zaydun:151","bookId":"diwan-zaydun","type":"poem","seq":151,"chapter":"البحر: بسيط تام","title":"أكرم بولادة ذخرا لمدخر","page":"","text":"أكرم بولادة ذخرا لمدخر … لو فرقت بين بيطار وعطار\nقالوا : أبو عامر أضحى يلم بها ، … قلت : الفراشة قد تدنو من النار\nعيرتمونا بأن قد صار يخلفنا … فيمن نحب وما في ذاك من عار\nأكل شهي أصبنا من أطايبه … بعضا وبعضا صفحنا عنه للفار"}]};